window.SOURCES = [{"path":"main.py","group":"","text":"#!/usr/bin/env python3\n\n\"\"\"\nRun the full pipeline in order.\n\nBy default the pipeline is rebuilt from the stored snapshots\n(RawData/ and the IGDB_miner CSVs), so results are reproducible:\n\n    1. Scripts/analyze_game_delisting_sources.py   -> Analysis/\n    2. RQ2_package/export_doesitplay_overlaps.py    -> RQ2_package/\n    3. RQ3 historical analysis notebook             -> RQ3_package/historical_analysis/\n    4. RQ3 delisting causes (validate + analyze)    -> RQ3_package/delisting_causes/\n       from the stored LLM answers in RQ3_package/delisting_causes/llm_cache/\n    5. docs/build_pipeline_page.py (if present)    -> docs/ (pipeline page data)\n\nLive steps are opt-in because their results change over time:\n\n    --scrape   re-mine the websites into RawData/ before step 1\n    --igdb     re-query IGDB into IGDB_miner/ after step 1\n               (needs real credentials in IGDB_miner/config.py)\n    --classify re-run the local LLM cause classification before step 4\n               (needs Ollama running with the models pulled)\n\nRawData/DelistedGames/delistedgames.json has no miner and is never refreshed.\n\"\"\"\n\nimport argparse\nimport importlib.util\nimport logging\nimport subprocess\nimport sys\nimport tempfile\nfrom pathlib import Path\n\n\nBASE_DIR = Path(__file__).resolve().parent\n\nSCRAPERS = [\n    BASE_DIR / \"Scripts\" / \"mining_dead_game_wiki.py\",\n    BASE_DIR / \"Scripts\" / \"mining_doesItPlay.py\",\n    BASE_DIR / \"Scripts\" / \"mining_delisted_steam_tracker.py\",\n]\n\nUNIFY_SCRIPT = BASE_DIR / \"Scripts\" / \"analyze_game_delisting_sources.py\"\n\nIGDB_SCRIPT = BASE_DIR / \"IGDB_miner\" / \"igdb_game_metadata_miner.py\"\nIGDB_CONFIG = BASE_DIR / \"IGDB_miner\" / \"config.py\"\n\nRQ2_SCRIPT = BASE_DIR / \"RQ2_package\" / \"export_doesitplay_overlaps.py\"\n\nRQ3_NOTEBOOK = (\n    BASE_DIR\n    / \"RQ3_package\"\n    / \"historical_analysis\"\n    / \"game_delisting_statistics_with_igdb_correlation.ipynb\"\n)\n\nCAUSES_DIR = BASE_DIR / \"RQ3_package\" / \"delisting_causes\"\nCLASSIFY_SCRIPT = CAUSES_DIR / \"classify_delisting_causes.py\"\nVALIDATE_SCRIPT = CAUSES_DIR / \"validate_delisting_causes.py\"\nANALYZE_SCRIPT = CAUSES_DIR / \"analyze_delisting_causes.py\"\nLLM_CACHE_DIR = CAUSES_DIR / \"llm_cache\"\n\nDOCS_SCRIPT = BASE_DIR / \"docs\" / \"build_pipeline_page.py\"\n\nIGDB_PLACEHOLDERS = {\"token here\", \"client id here\"}\n\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format=\"%(asctime)s - %(levelname)s - %(message)s\",\n)\n\nlogger = logging.getLogger(__name__)\n\n\ndef run(command: list, cwd: Path = BASE_DIR) -> None:\n    logger.info(\"Running: %s\", \" \".join(str(part) for part in command))\n\n    subprocess.run(command, cwd=cwd, check=True)\n\n\ndef run_script(script: Path) -> None:\n    run([sys.executable, script])\n\n\ndef check_igdb_credentials() -> None:\n    spec = importlib.util.spec_from_file_location(\"config\", IGDB_CONFIG)\n    config = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(config)\n\n    if {config.token, config.CLIENT_ID} & IGDB_PLACEHOLDERS:\n        sys.exit(\n            f\"Set token and CLIENT_ID in {IGDB_CONFIG} before using --igdb.\"\n        )\n\n\ndef run_notebook(notebook: Path) -> None:\n    with tempfile.TemporaryDirectory() as tmp:\n        run(\n            [\n                sys.executable, \"-m\", \"jupyter\", \"nbconvert\",\n                \"--to\", \"notebook\",\n                \"--execute\",\n                \"--output-dir\", tmp,\n                notebook.name,\n            ],\n            cwd=notebook.parent,\n        )\n\n\ndef main():\n    parser = argparse.ArgumentParser(\n        description=\"Run the pipeline from raw data to figures.\"\n    )\n\n    parser.add_argument(\n        \"--scrape\",\n        action=\"store_true\",\n        help=\"Re-mine the websites into RawData/ first (results change over time).\",\n    )\n\n    parser.add_argument(\n        \"--igdb\",\n        action=\"store_true\",\n        help=\"Re-query IGDB for genres and yearly release counts (slow, needs credentials).\",\n    )\n\n    parser.add_argument(\n        \"--classify\",\n        action=\"store_true\",\n        help=\"Classify delisting causes with local LLMs via Ollama (slow, needs Ollama).\",\n    )\n\n    args = parser.parse_args()\n\n    if args.igdb:\n        check_igdb_credentials()\n\n    if args.scrape:\n        for script in SCRAPERS:\n            run_script(script)\n\n    run_script(UNIFY_SCRIPT)\n\n    if args.igdb:\n        run_script(IGDB_SCRIPT)\n\n    run_script(RQ2_SCRIPT)\n\n    run_notebook(RQ3_NOTEBOOK)\n\n    if args.classify:\n        run_script(CLASSIFY_SCRIPT)\n\n    if any(LLM_CACHE_DIR.glob(\"*.jsonl\")):\n        run_script(VALIDATE_SCRIPT)\n        run_script(ANALYZE_SCRIPT)\n    else:\n        logger.warning(\"No LLM caches in %s; skipping the delisting-cause analysis.\", LLM_CACHE_DIR)\n\n    if DOCS_SCRIPT.exists():\n        run_script(DOCS_SCRIPT)\n\n    logger.info(\"Pipeline completed.\")\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"requirements.txt","group":"","text":"# Mining (Scripts/mining_*.py, IGDB_miner/)\nrequests\nbeautifulsoup4\nlxml\n\n# Aggregation and analysis\npandas\nscipy\nmatplotlib\n\n# Running the notebooks\njupyter\n\n# Delisting causes (RQ3_package/delisting_causes/)\nrapidfuzz\n"},{"path":"Scripts/analyze_game_delisting_sources.py","group":"Scripts","text":"#!/usr/bin/env python3\n\n\"\"\"\nAggregate and analyze game delisting / shutdown datasets.\n\nInputs (under ../RawData/):\n    - DeadGameWiki/dead_games.json\n    - DelistedGames/delistedgames.json\n    - SteamTracker/steam_delisted_apps.json\n    - doesitplay_games.json\n\nOutputs are written to ../Analysis/:\n    - unified_games.csv\n    - source_statistics.csv\n    - source_status_statistics.csv\n    - cross_source_overlap.csv\n    - model_readiness.json\n\nImportant modeling note:\nThe four sources are useful for descriptive analysis, historical\ndelisting/shutdown cases, and offline/download-dependency characteristics.\nHowever, they are still NOT sufficient by themselves for a valid prospective\nmodel of \"will this game be delisted?\". A representative, time-aligned control\npopulation and pre-event snapshots are still required.\n\"\"\"\n\nimport json\nimport logging\nimport re\nimport unicodedata\nfrom pathlib import Path\n\nimport pandas as pd\n\n\n# ---------------------------------------------------------------------------\n# Configuration\n# ---------------------------------------------------------------------------\n\nBASE_DIR = Path(__file__).resolve().parent\nRAW_DATA_DIR = BASE_DIR.parent / \"RawData\"\n\nDEAD_GAMES_FILE = RAW_DATA_DIR / \"DeadGameWiki\" / \"dead_games.json\"\nDELISTED_GAMES_FILE = RAW_DATA_DIR / \"DelistedGames\" / \"delistedgames.json\"\nSTEAM_TRACKER_FILE = RAW_DATA_DIR / \"SteamTracker\" / \"steam_delisted_apps.json\"\nDOESITPLAY_FILE = RAW_DATA_DIR / \"doesitplay_games.json\"\n\nOUTPUT_DIR = BASE_DIR.parent / \"Analysis\"\n\nUNIFIED_CSV = OUTPUT_DIR / \"unified_games.csv\"\nSOURCE_STATS_CSV = OUTPUT_DIR / \"source_statistics.csv\"\nSTATUS_STATS_CSV = OUTPUT_DIR / \"source_status_statistics.csv\"\nOVERLAP_CSV = OUTPUT_DIR / \"cross_source_overlap.csv\"\nMODEL_READINESS_JSON = OUTPUT_DIR / \"model_readiness.json\"\n\n# A valid future-prediction target is intentionally not fabricated.\nFUTURE_TARGET_COLUMN = \"target_delisted_within_12m\"\n\n# Steam Tracker app types that are not released games.\nNON_GAME_STEAM_TYPES = {\"Unreleased\", \"Test app\"}\n\n# Title keywords marking betas, demos, test builds, DLC and soundtracks.\n# Matched on the original title: normalize_title strips \"(Beta)\" etc.\nNON_GAME_TITLE_PATTERN = r\"\\b(?:beta|demo|test server|playtest|soundtrack|dlc)\\b\"\n\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format=\"%(asctime)s - %(levelname)s - %(message)s\",\n)\n\nlogger = logging.getLogger(__name__)\n\n\n# ---------------------------------------------------------------------------\n# JSON loading\n# ---------------------------------------------------------------------------\n\ndef remove_trailing_commas(text: str) -> str:\n    \"\"\"\n    Remove trailing commas before '}' or ']' while respecting JSON strings.\n\n    This is useful because one of the supplied JSON files contains at least\n    one trailing comma and therefore fails strict json.loads().\n    \"\"\"\n    result = []\n    in_string = False\n    escaped = False\n    i = 0\n\n    while i < len(text):\n        char = text[i]\n\n        if in_string:\n            result.append(char)\n\n            if escaped:\n                escaped = False\n            elif char == \"\\\\\":\n                escaped = True\n            elif char == '\"':\n                in_string = False\n\n            i += 1\n            continue\n\n        if char == '\"':\n            in_string = True\n            result.append(char)\n            i += 1\n            continue\n\n        if char == \",\":\n            j = i + 1\n\n            while j < len(text) and text[j].isspace():\n                j += 1\n\n            if j < len(text) and text[j] in \"}]\":\n                # Skip only the comma. Whitespace is preserved by the loop.\n                i += 1\n                continue\n\n        result.append(char)\n        i += 1\n\n    return \"\".join(result)\n\n\ndef load_json(path: Path):\n    \"\"\"\n    Load JSON strictly first. If parsing fails because of trailing commas,\n    retry after a conservative cleanup.\n    \"\"\"\n    logger.info(\"Loading %s\", path)\n\n    text = path.read_text(encoding=\"utf-8\")\n\n    try:\n        return json.loads(text)\n    except json.JSONDecodeError as exc:\n        logger.warning(\n            \"Strict JSON parsing failed for %s: %s. \"\n            \"Retrying after removing trailing commas.\",\n            path.name,\n            exc,\n        )\n\n        cleaned = remove_trailing_commas(text)\n        return json.loads(cleaned)\n\n\n# ---------------------------------------------------------------------------\n# Generic helpers\n# ---------------------------------------------------------------------------\n\ndef normalize_title(value) -> str:\n    \"\"\"\n    Normalize a title for approximate cross-source matching.\n\n    This is deliberately conservative: it normalizes case, accents,\n    punctuation and parenthetical qualifiers. It is NOT full entity\n    resolution.\n    \"\"\"\n    if pd.isna(value):\n        return \"\"\n\n    value = re.sub(r\"[™®©]\", \"\", str(value))\n    value = unicodedata.normalize(\"NFKC\", value).casefold()\n\n    value = re.sub(r\"\\([^)]*\\)\", \" \", value)\n\n    value = re.sub(r\"\\[\\s*relisted\\s*\\]\", \" \", value)\n\n    # Preserve Unicode letters/numbers instead of forcing ASCII.\n    value = re.sub(r\"[^\\w]+\", \" \", value, flags=re.UNICODE)\n    value = value.replace(\"_\", \" \")\n    value = re.sub(r\"\\s+\", \" \", value)\n\n    return value.strip()\n\n\ndef earliest_year(value):\n    \"\"\"\n    Extract the first 4-digit year from free-form source text.\n    \"\"\"\n    if pd.isna(value):\n        return pd.NA\n\n    years = re.findall(r\"\\b(?:19|20)\\d{2}\\b\", str(value))\n\n    if years:\n        return min(int(year) for year in years)\n\n    return pd.NA\n\n\ndef serialize_complex_values(value):\n    \"\"\"\n    Make list/dict source fields safe for CSV export without discarding them.\n    \"\"\"\n    if isinstance(value, (list, dict)):\n        return json.dumps(value, ensure_ascii=False)\n\n    return value\n\n\ndef normalize_yes_no(value):\n    \"\"\"\n    Normalize values such as 'Yes', 'Yes*', 'No', and 'No*'.\n\n    Returns True/False when the value is recognizable, otherwise pd.NA.\n    \"\"\"\n    if pd.isna(value):\n        return pd.NA\n\n    normalized = str(value).strip().casefold().replace(\"*\", \"\")\n\n    if normalized == \"yes\":\n        return True\n    if normalized == \"no\":\n        return False\n\n    return pd.NA\n\n\ndef prefix_raw_columns(df: pd.DataFrame, prefix: str) -> pd.DataFrame:\n    \"\"\"\n    Preserve every original source field under a source-specific raw prefix.\n    \"\"\"\n    raw = df.copy()\n\n    for column in raw.columns:\n        raw[column] = raw[column].map(serialize_complex_values)\n\n    raw.columns = [\n        f\"raw__{prefix}__{column.replace('.', '__').replace(' ', '_')}\"\n        for column in raw.columns\n    ]\n\n    return raw\n\n\n# ---------------------------------------------------------------------------\n# Source-specific normalization\n# ---------------------------------------------------------------------------\n\ndef normalize_dead_game_list(records) -> pd.DataFrame:\n    source = pd.DataFrame(records)\n\n    canonical = pd.DataFrame(\n        {\n            \"source\": \"dead_game_list\",\n            \"source_record_id\": source.index.astype(str),\n            \"game_name\": source[\"Game\"],\n            \"normalized_title\": source[\"Game\"].map(normalize_title),\n            \"publisher\": source[\"Publisher\"],\n            \"developer\": pd.NA,\n            \"platforms\": source[\"Platform(s)\"],\n            \"release_info\": source[\"Release date\"],\n            \"event_info\": source[\"Death date\"],\n            \"release_year\": source[\"Release date\"].map(earliest_year),\n            \"event_year\": source[\"Death date\"].map(earliest_year),\n            \"source_status\": source[\"State\"],\n            \"is_explicitly_delisted\": pd.NA,\n            \"is_historically_unavailable\": source[\"State\"].isin(\n                [\n                    \"Dead\",\n                    \"Fan-Resurrected\",\n                    \"Fan-Preserved\",\n                    \"Dev-Preserved\",\n                ]\n            ),\n            \"is_dead\": source[\"State\"].eq(\"Dead\"),\n            \"is_at_risk\": source[\"State\"].eq(\"At Risk\"),\n            \"offline_play\": pd.NA,\n            \"offline_play_bool\": pd.NA,\n            \"download_required\": pd.NA,\n            \"download_required_bool\": pd.NA,\n        }\n    )\n\n    raw = prefix_raw_columns(source, \"deadgamelist\")\n\n    return pd.concat(\n        [canonical.reset_index(drop=True), raw.reset_index(drop=True)],\n        axis=1,\n    )\n\n\ndef normalize_delisted_games(records) -> pd.DataFrame:\n    source = pd.json_normalize(records)\n\n    canonical = pd.DataFrame(\n        {\n            \"source\": \"delisted_games\",\n            \"source_record_id\": source[\"id\"].astype(str),\n            \"game_name\": source[\"data.title\"],\n            \"normalized_title\": source[\"data.title\"].map(normalize_title),\n            \"publisher\": source[\"data.publisher\"],\n            \"developer\": source[\"data.developer\"],\n            \"platforms\": source[\"data.platform\"],\n            \"release_info\": source[\"data.digital_release\"],\n            \"event_info\": source[\"data.delisting\"],\n            \"release_year\": source[\"data.digital_release\"].map(earliest_year),\n            \"event_year\": source[\"data.delisting\"].map(earliest_year),\n            \"source_status\": \"Historically delisted\",\n            # This source is explicitly a historical delisting catalogue.\n            \"is_explicitly_delisted\": True,\n            \"is_historically_unavailable\": True,\n            \"is_dead\": pd.NA,\n            \"is_at_risk\": False,\n            \"offline_play\": pd.NA,\n            \"offline_play_bool\": pd.NA,\n            \"download_required\": pd.NA,\n            \"download_required_bool\": pd.NA,\n        }\n    )\n\n    raw = prefix_raw_columns(source, \"delistedgames\")\n\n    return pd.concat(\n        [canonical.reset_index(drop=True), raw.reset_index(drop=True)],\n        axis=1,\n    )\n\n\ndef normalize_steam_tracker(records) -> pd.DataFrame:\n    source = pd.DataFrame(records)\n\n    explicit_delisted = source[\"Type\"].eq(\"Delisted\")\n\n    unavailable_types = {\n        \"Delisted\",\n        \"Purchase disabled\",\n        \"F2P (unavailable)\",\n        \"Retail only\",\n    }\n\n    canonical = pd.DataFrame(\n        {\n            \"source\": \"steam_tracker\",\n            \"source_record_id\": source[\"AppID\"].astype(str),\n            \"game_name\": source[\"Name\"],\n            \"normalized_title\": source[\"Name\"].map(normalize_title),\n            \"publisher\": pd.NA,\n            \"developer\": pd.NA,\n            \"platforms\": \"Steam / PC\",\n            \"release_info\": pd.NA,\n            \"event_info\": source[\"Changed\"],\n            \"release_year\": pd.NA,\n            \"event_year\": source[\"Changed\"].map(earliest_year),\n            \"source_status\": source[\"Type\"],\n            \"is_explicitly_delisted\": explicit_delisted,\n            \"is_historically_unavailable\": source[\"Type\"].isin(\n                unavailable_types\n            ),\n            \"is_dead\": pd.NA,\n            \"is_at_risk\": False,\n            \"offline_play\": pd.NA,\n            \"offline_play_bool\": pd.NA,\n            \"download_required\": pd.NA,\n            \"download_required_bool\": pd.NA,\n        }\n    )\n\n    raw = prefix_raw_columns(source, \"steamtracker\")\n\n    return pd.concat(\n        [canonical.reset_index(drop=True), raw.reset_index(drop=True)],\n        axis=1,\n    )\n\n\ndef normalize_doesitplay(records) -> pd.DataFrame:\n    \"\"\"\n    Normalize DoesItPlay test rows.\n\n    A row describes a platform/version/region/test-device observation.\n    DoesItPlay provides dependency features, not a delisting outcome.\n    \"\"\"\n    source = pd.DataFrame(records)\n\n    offline_bool = source[\"OfflinePlay\"].map(normalize_yes_no)\n    download_bool = source[\"DownloadRequired\"].map(normalize_yes_no)\n\n    source_status = (\n        \"Offline=\" + source[\"OfflinePlay\"].fillna(\"\").astype(str).str.strip()\n        + \"; DownloadRequired=\"\n        + source[\"DownloadRequired\"].fillna(\"\").astype(str).str.strip()\n    )\n\n    canonical = pd.DataFrame(\n        {\n            \"source\": \"doesitplay\",\n            \"source_record_id\": source[\"No\"].astype(str),\n            \"game_name\": source[\"Game\"],\n            \"normalized_title\": source[\"Game\"].map(normalize_title),\n            \"publisher\": pd.NA,\n            \"developer\": pd.NA,\n            \"platforms\": source[\"Platform\"],\n            \"release_info\": pd.NA,\n            \"event_info\": pd.NA,\n            \"release_year\": pd.NA,\n            \"event_year\": pd.NA,\n            \"source_status\": source_status,\n            \"is_explicitly_delisted\": pd.NA,\n            \"is_historically_unavailable\": pd.NA,\n            \"is_dead\": pd.NA,\n            \"is_at_risk\": pd.NA,\n            \"offline_play\": source[\"OfflinePlay\"],\n            \"offline_play_bool\": offline_bool,\n            \"download_required\": source[\"DownloadRequired\"],\n            \"download_required_bool\": download_bool,\n        }\n    )\n\n    raw = prefix_raw_columns(source, \"doesitplay\")\n\n    return pd.concat(\n        [canonical.reset_index(drop=True), raw.reset_index(drop=True)],\n        axis=1,\n    )\n\n\n# ---------------------------------------------------------------------------\n# Unified dataframe\n# ---------------------------------------------------------------------------\n\ndef create_unified_dataframe(\n    dead_games_records,\n    delisted_games_records,\n    steam_tracker_records,\n    doesitplay_records,\n) -> pd.DataFrame:\n    \"\"\"\n    Create one unified dataframe while retaining every original source field.\n    \"\"\"\n    frames = [\n        normalize_dead_game_list(dead_games_records),\n        normalize_delisted_games(delisted_games_records),\n        normalize_steam_tracker(steam_tracker_records),\n        normalize_doesitplay(doesitplay_records),\n    ]\n\n    unified = pd.concat(\n        frames,\n        ignore_index=True,\n        sort=False,\n    )\n\n    non_game_type = (\n        unified[\"source\"].eq(\"steam_tracker\")\n        & unified[\"source_status\"].isin(NON_GAME_STEAM_TYPES)\n    )\n    non_game_title = unified[\"game_name\"].astype(str).str.contains(\n        NON_GAME_TITLE_PATTERN, case=False, regex=True\n    )\n\n    # Titles with no letters/digits (e.g. \"**\", \"#\") cannot be matched.\n    empty_title = unified[\"normalized_title\"].eq(\"\")\n\n    return unified[\n        ~(non_game_type | non_game_title | empty_title)\n    ].reset_index(drop=True)\n\n\n# ---------------------------------------------------------------------------\n# Statistics\n# ---------------------------------------------------------------------------\n\ndef safe_sum(series: pd.Series):\n    \"\"\"\n    Sum booleans while handling nullable/mixed columns.\n    \"\"\"\n    return int(series.astype(\"boolean\").sum(skipna=True))\n\n\ndef compute_source_statistics(\n    unified: pd.DataFrame,\n) -> pd.DataFrame:\n    rows = []\n\n    for source_name, group in unified.groupby(\"source\", sort=True):\n        nonempty_titles = group.loc[\n            group[\"normalized_title\"].ne(\"\"),\n            \"normalized_title\",\n        ]\n\n        rows.append(\n            {\n                \"source\": source_name,\n                \"records\": len(group),\n                \"unique_normalized_titles\": nonempty_titles.nunique(),\n                \"duplicate_title_rows\": int(\n                    nonempty_titles.duplicated().sum()\n                ),\n                \"explicitly_delisted_records\": safe_sum(\n                    group[\"is_explicitly_delisted\"]\n                ),\n                \"historically_unavailable_records\": safe_sum(\n                    group[\"is_historically_unavailable\"]\n                ),\n                \"dead_records\": safe_sum(group[\"is_dead\"]),\n                \"at_risk_records\": safe_sum(group[\"is_at_risk\"]),\n                \"release_year_available\": int(\n                    group[\"release_year\"].notna().sum()\n                ),\n                \"event_year_available\": int(\n                    group[\"event_year\"].notna().sum()\n                ),\n                \"offline_play_yes\": safe_sum(\n                    group[\"offline_play_bool\"]\n                ),\n                \"offline_play_no\": safe_sum(\n                    group[\"offline_play_bool\"].eq(False)\n                ),\n                \"download_required_yes\": safe_sum(\n                    group[\"download_required_bool\"]\n                ),\n                \"download_required_no\": safe_sum(\n                    group[\"download_required_bool\"].eq(False)\n                ),\n            }\n        )\n\n    return pd.DataFrame(rows)\n\n\ndef compute_status_statistics(\n    unified: pd.DataFrame,\n) -> pd.DataFrame:\n    \"\"\"\n    Keep source-specific status semantics rather than forcing incompatible\n    states into one artificial label.\n    \"\"\"\n    stats = (\n        unified.groupby(\n            [\"source\", \"source_status\"],\n            dropna=False,\n        )\n        .size()\n        .reset_index(name=\"records\")\n    )\n\n    stats[\"percentage_within_source\"] = (\n        stats[\"records\"]\n        / stats.groupby(\"source\")[\"records\"].transform(\"sum\")\n        * 100\n    ).round(2)\n\n    return stats\n\n\ndef compute_cross_source_overlap(\n    unified: pd.DataFrame,\n) -> pd.DataFrame:\n    \"\"\"\n    Estimate cross-source overlap using normalized titles.\n\n    Title normalization is useful for exploratory statistics but should not\n    be treated as perfect entity resolution.\n    \"\"\"\n    title_sets = {}\n\n    for source_name, group in unified.groupby(\"source\"):\n        title_sets[source_name] = set(\n            group.loc[\n                group[\"normalized_title\"].ne(\"\"),\n                \"normalized_title\",\n            ]\n        )\n\n    sources = sorted(title_sets)\n\n    rows = []\n\n    for i, source_a in enumerate(sources):\n        for source_b in sources[i + 1:]:\n            overlap = title_sets[source_a] & title_sets[source_b]\n\n            rows.append(\n                {\n                    \"source_a\": source_a,\n                    \"source_b\": source_b,\n                    \"common_normalized_titles\": len(overlap),\n                }\n            )\n\n    if len(sources) >= 3:\n        common_all = set.intersection(\n            *(title_sets[source] for source in sources)\n        )\n\n        rows.append(\n            {\n                \"source_a\": \"ALL_SOURCES\",\n                \"source_b\": \"ALL_SOURCES\",\n                \"common_normalized_titles\": len(common_all),\n            }\n        )\n\n    return pd.DataFrame(rows)\n\n\n# ---------------------------------------------------------------------------\n# Modeling readiness\n# ---------------------------------------------------------------------------\n\ndef assess_delisting_prediction_readiness(\n    unified: pd.DataFrame,\n) -> dict:\n    \"\"\"\n    Assess whether the current data support a prospective model predicting\n    whether a currently active game will be delisted in the future.\n\n    The current datasets are event/curation based, so this function does not\n    fabricate a binary target from source membership.\n    \"\"\"\n    source_counts = (\n        unified[\"source\"]\n        .value_counts()\n        .sort_index()\n        .astype(int)\n        .to_dict()\n    )\n\n    at_risk_count = safe_sum(unified[\"is_at_risk\"])\n    explicit_delisted_count = safe_sum(\n        unified[\"is_explicitly_delisted\"]\n    )\n\n    reasons_not_ready = [\n        (\n            \"There is no representative negative/control population of \"\n            \"ordinary active games sampled independently of delisting risk.\"\n        ),\n        (\n            \"The Delisted Games source is a historical delisting catalogue, \"\n            \"so source membership already selects positive cases.\"\n        ),\n        (\n            \"Steam Tracker's delisted-app page primarily contains apps that \"\n            \"are already unavailable, purchase-disabled, delisted, unreleased, \"\n            \"test apps, or otherwise exceptional.\"\n        ),\n        (\n            \"The Dead Game List contains useful At Risk and Dead states, but \"\n            \"it is still a curated risk/death list rather than a population \"\n            \"sample of active games.\"\n        ),\n        (\n            \"DoesItPlay adds a broader reference set and useful pre-event \"\n            \"features such as offline play and download dependency, but its \"\n            \"rows do not provide a time-aligned delisting outcome.\"\n        ),\n        (\n            \"Fields such as delisting date, death date, Changed, State, and \"\n            \"post-event Notes would leak the outcome if used as predictors.\"\n        ),\n        (\n            \"The sources use different semantics: store delisting, purchase \"\n            \"disablement, server/game death, preservation, offline play, and \"\n            \"download dependency are not the same event.\"\n        ),\n    ]\n\n    recommended_solutions = [\n        (\n            \"Collect a control cohort of active/non-delisted games from Steam \"\n            \"or another store, ideally using the same observation dates as \"\n            \"the positive cases.\"\n        ),\n        (\n            \"Define a precise prediction target and horizon, e.g. \"\n            \"'delisted from Steam within the next 12 months'.\"\n        ),\n        (\n            \"Create historical snapshots so every feature is measured before \"\n            \"the prediction cutoff; exclude post-delisting text/status/date \"\n            \"fields from model inputs.\"\n        ),\n        (\n            \"Use AppID/store IDs for entity resolution where possible, and \"\n            \"use normalized/fuzzy title matching only as a fallback.\"\n        ),\n        (\n            \"Use DoesItPlay's OfflinePlay and DownloadRequired fields as \"\n            \"candidate dependency features after entity resolution, while \"\n            \"keeping platform/version/region/test-device context.\"\n        ),\n        (\n            \"Add other pre-event features such as game age, publisher/developer \"\n            \"delisting history, player-count trend, review trend, update \"\n            \"recency, price/discount history, store tags, multiplayer/online \"\n            \"dependency, DLC activity, and build/depot activity.\"\n        ),\n        (\n            \"Distinguish store delisting from server shutdown/game death. \"\n            \"Consider separate labels or a multi-task formulation.\"\n        ),\n        (\n            \"Use a time-based train/validation/test split instead of a random \"\n            \"split once historical snapshots are available.\"\n        ),\n        (\n            \"For time-to-delisting, consider survival analysis with \"\n            \"right-censored active games instead of forcing a binary label.\"\n        ),\n        (\n            \"If negatives remain incomplete, investigate positive-unlabeled \"\n            \"(PU) learning rather than treating unknown games as true negatives.\"\n        ),\n        (\n            \"Match controls to delisted games by release year, platform, \"\n            \"genre/popularity, and publisher size to reduce selection bias.\"\n        ),\n    ]\n\n    return {\n        \"ready_for_prospective_delisting_prediction\": False,\n        \"requested_target\": FUTURE_TARGET_COLUMN,\n        \"total_records\": int(len(unified)),\n        \"unique_normalized_titles\": int(\n            unified.loc[\n                unified[\"normalized_title\"].ne(\"\"),\n                \"normalized_title\",\n            ].nunique()\n        ),\n        \"source_counts\": source_counts,\n        \"explicit_delisted_records\": explicit_delisted_count,\n        \"at_risk_records\": at_risk_count,\n        \"reasons_not_ready\": reasons_not_ready,\n        \"recommended_solutions\": recommended_solutions,\n    }\n\n\n# ---------------------------------------------------------------------------\n# Main\n# ---------------------------------------------------------------------------\n\ndef main():\n    OUTPUT_DIR.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    dead_games_records = load_json(\n        DEAD_GAMES_FILE\n    )\n\n    delisted_games_records = load_json(\n        DELISTED_GAMES_FILE\n    )\n\n    steam_tracker_records = load_json(\n        STEAM_TRACKER_FILE\n    )\n\n    doesitplay_records = load_json(\n        DOESITPLAY_FILE\n    )\n\n    unified = create_unified_dataframe(\n        dead_games_records,\n        delisted_games_records,\n        steam_tracker_records,\n        doesitplay_records,\n    )\n\n    source_stats = compute_source_statistics(\n        unified\n    )\n\n    status_stats = compute_status_statistics(\n        unified\n    )\n\n    overlap_stats = compute_cross_source_overlap(\n        unified\n    )\n\n    readiness = assess_delisting_prediction_readiness(\n        unified\n    )\n\n    # ------------------------------------------------------------------\n    # Exports\n    # ------------------------------------------------------------------\n\n    unified.to_csv(\n        UNIFIED_CSV,\n        index=False,\n    )\n\n    source_stats.to_csv(\n        SOURCE_STATS_CSV,\n        index=False,\n    )\n\n    status_stats.to_csv(\n        STATUS_STATS_CSV,\n        index=False,\n    )\n\n    overlap_stats.to_csv(\n        OVERLAP_CSV,\n        index=False,\n    )\n\n    MODEL_READINESS_JSON.write_text(\n        json.dumps(\n            readiness,\n            ensure_ascii=False,\n            indent=2,\n        ),\n        encoding=\"utf-8\",\n    )\n\n    # ------------------------------------------------------------------\n    # Console summary\n    # ------------------------------------------------------------------\n\n    print(\"\\n=== SOURCE STATISTICS ===\")\n    print(\n        source_stats.to_string(\n            index=False\n        )\n    )\n\n    print(\"\\n=== STATUS DISTRIBUTIONS ===\")\n    print(\n        status_stats.to_string(\n            index=False\n        )\n    )\n\n    print(\"\\n=== CROSS-SOURCE TITLE OVERLAP ===\")\n    print(\n        overlap_stats.to_string(\n            index=False\n        )\n    )\n\n    print(\"\\n=== MODEL READINESS ===\")\n    print(\n        \"Ready for prospective delisting prediction:\",\n        readiness[\"ready_for_prospective_delisting_prediction\"],\n    )\n\n    print(\"\\nReasons:\")\n    for reason in readiness[\"reasons_not_ready\"]:\n        print(f\"  - {reason}\")\n\n    print(\"\\nRecommended next steps:\")\n    for solution in readiness[\"recommended_solutions\"]:\n        print(f\"  - {solution}\")\n\n    print(\"\\nFiles written:\")\n    print(f\"  - {UNIFIED_CSV}\")\n    print(f\"  - {SOURCE_STATS_CSV}\")\n    print(f\"  - {STATUS_STATS_CSV}\")\n    print(f\"  - {OVERLAP_CSV}\")\n    print(f\"  - {MODEL_READINESS_JSON}\")\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"Scripts/classify_all_titles.py","group":"Scripts","text":"\"\"\"Rule-based taxonomy classification for every unique title, plus input\nbatches for LLM classification of the titles that need judgement.\n\nA title needs the LLM when it has free text (delistedGames, DeadGameWiki)\nor appears in more than one source. All other titles are classified by the\nrules in sample_taxonomy_classification.classify().\n\nOutputs:\n    Analysis/taxonomy_rules_all.csv   rule-based labels for all titles\n    <batch_dir>/batch_NNN.json        LLM input, one file per batch\n\nUsage: python Scripts/classify_all_titles.py <batch_dir> [batch_size]\n\"\"\"\n\nimport json\nimport sys\nfrom pathlib import Path\n\nimport pandas as pd\n\nsys.path.insert(0, str(Path(__file__).resolve().parent))\nfrom sample_taxonomy_classification import classify, s  # noqa: E402\n\nROOT = Path(__file__).resolve().parents[1]\nIN_CSV = ROOT / \"Analysis\" / \"unified_games.csv\"\nOUT_CSV = ROOT / \"Analysis\" / \"taxonomy_rules_all.csv\"\nTEXT_SOURCES = {\"delisted_games\", \"dead_game_list\"}\nPRESERVED = {\"Dev-Preserved\", \"Fan-Preserved\", \"Fan-Resurrected\"}\nINFO_CHARS = 6000\n\nLLM_FIELDS = {\n    \"steam_tracker\": [\"raw__steamtracker__Type\", \"raw__steamtracker__Keyshops\",\n                      \"raw__steamtracker__Changed\"],\n    \"doesitplay\": [\"raw__doesitplay__Platform\", \"raw__doesitplay__Version\",\n                   \"raw__doesitplay__Region\", \"raw__doesitplay__OfflinePlay\",\n                   \"raw__doesitplay__DownloadRequired\"],\n    \"dead_game_list\": [\"raw__deadgamelist__State\", \"raw__deadgamelist__Single_Player_at_risk\",\n                       \"raw__deadgamelist__Subscription_(Pay_to_Play)\",\n                       \"raw__deadgamelist__Notes\"],\n    \"delisted_games\": [\"raw__delistedgames__data__digital_release\",\n                       \"raw__delistedgames__data__delisting\",\n                       \"raw__delistedgames__data__available_on\"],\n}\n\n\ndef info_text(value):\n    value = s(value)\n    if not value:\n        return \"\"\n    try:\n        parts = json.loads(value)[2:]\n    except json.JSONDecodeError:\n        parts = [value]\n    return \"\\n\".join(p.strip() for p in parts if p.strip())[:INFO_CHARS]\n\n\ndef llm_record(r):\n    rec = {\"source\": r[\"source\"], \"name\": s(r[\"game_name\"]), \"platforms\": s(r[\"platforms\"]),\n           \"publisher\": s(r[\"publisher\"]), \"release_year\": s(r[\"release_year\"]),\n           \"event_year\": s(r[\"event_year\"]), \"status\": s(r[\"source_status\"])}\n    for f in LLM_FIELDS[r[\"source\"]]:\n        if s(r[f]):\n            rec[f.split(\"__\")[-1]] = s(r[f])\n    if r[\"source\"] == \"delisted_games\":\n        rec[\"info\"] = info_text(r[\"raw__delistedgames__data__info\"])\n    return rec\n\n\ndef main():\n    batch_dir = Path(sys.argv[1])\n    batch_size = int(sys.argv[2]) if len(sys.argv) > 2 else 40\n    batch_dir.mkdir(parents=True, exist_ok=True)\n\n    d = pd.read_csv(IN_CSV, low_memory=False)\n    size = d.groupby(\"source\")[\"normalized_title\"].nunique().sort_values()\n    rank = {src: i for i, src in enumerate(size.index)}\n    d = d.assign(_r=d[\"source\"].map(rank)).sort_values(\n        [\"normalized_title\", \"_r\", \"source_record_id\"])\n\n    rows, llm_items = [], []\n    for title, recs in d.groupby(\"normalized_title\", sort=False):\n        prim = recs.iloc[0]\n        sources = set(recs[\"source\"])\n        c = classify(prim)\n        dgl = recs[recs[\"source\"] == \"dead_game_list\"]\n        if len(dgl):\n            st = s(dgl.iloc[0][\"raw__deadgamelist__State\"])\n            if st in PRESERVED:\n                c[\"D7\"] = st\n        needs_llm = bool(sources & TEXT_SOURCES) or len(sources) > 1\n        platform = s(prim[\"raw__doesitplay__Platform\"]) or s(prim[\"platforms\"])\n        rows.append({\n            \"normalized_title\": title, \"game_name\": prim[\"game_name\"],\n            \"stratum_source\": prim[\"source\"],\n            \"all_sources\": \"|\".join(sorted(sources)),\n            \"platform\": platform, \"needs_llm\": needs_llm,\n            **{f\"D{i}\": c[f\"D{i}\"] for i in range(1, 8)},\n            \"evidence\": c[\"evidence\"],\n        })\n        if needs_llm:\n            llm_items.append({\"title_id\": title, \"target_source\": prim[\"source\"],\n                              \"target_platform\": platform,\n                              \"records\": [llm_record(r) for _, r in recs.iterrows()]})\n\n    pd.DataFrame(rows).to_csv(OUT_CSV, index=False)\n    for i in range(0, len(llm_items), batch_size):\n        path = batch_dir / f\"batch_{i // batch_size:03d}.json\"\n        path.write_text(json.dumps(llm_items[i:i + batch_size], ensure_ascii=False, indent=1))\n    print(f\"{len(rows)} titles -> {OUT_CSV.name}; {len(llm_items)} need LLM -> \"\n          f\"{(len(llm_items) + batch_size - 1) // batch_size} batches in {batch_dir}\")\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"Scripts/merge_taxonomy_classification.py","group":"Scripts","text":"\"\"\"Merge rule-based and LLM taxonomy labels into one file for all titles.\n\nInputs:\n    Analysis/taxonomy_rules_all.csv   from classify_all_titles.py\n    Analysis/taxonomy_llm_haiku.csv   Haiku labels for titles with free text\n                                      or several sources (needs_llm == True)\nOutput:\n    Analysis/taxonomy_full_classification.csv\n\nTitles with needs_llm take the Haiku labels; all others keep the rule labels.\nD5 counts official servers only: a title whose D7 is Fan-Preserved or\nFan-Resurrected cannot be D5 = Active (fan-run servers are captured by D7).\nTaxonomy v2 refinements are applied to the Haiku labels, which predate them\n(the rule labels already follow them):\n  - D4 Minor -> Optional Multiplayer when a DeadGameWiki entry with\n    Single_Player_at_risk = No names multiplayer, or the rationale does;\n  - D6 -> Legacy OS when every listed platform is a discontinued runtime/OS.\nFinally, the manually reviewed sample (taxonomy_sample_classification.csv)\noverrides all other labels (method = \"manual review\").\n\nUsage: python Scripts/merge_taxonomy_classification.py\n\"\"\"\n\nimport sys\nfrom pathlib import Path\n\nimport pandas as pd\n\nsys.path.insert(0, str(Path(__file__).resolve().parent))\nfrom sample_taxonomy_classification import CURRENT, MULTIPLAYER, is_legacy_os, s  # noqa: E402\n\nROOT = Path(__file__).resolve().parents[1]\nRULES_CSV = ROOT / \"Analysis\" / \"taxonomy_rules_all.csv\"\nLLM_CSV = ROOT / \"Analysis\" / \"taxonomy_llm_haiku.csv\"\nSAMPLE_CSV = ROOT / \"Analysis\" / \"taxonomy_sample_classification.csv\"\nGAMES_CSV = ROOT / \"Analysis\" / \"unified_games.csv\"\nOUT_CSV = ROOT / \"Analysis\" / \"taxonomy_full_classification.csv\"\n\nDIMENSIONS = {\n    \"D1\": \"D1_digital_availability\",\n    \"D2\": \"D2_physical_availability\",\n    \"D3\": \"D3_medium_completeness\",\n    \"D4\": \"D4_online_dependency\",\n    \"D5\": \"D5_service_status\",\n    \"D6\": \"D6_platform_accessibility\",\n    \"D7\": \"D7_preservation\",\n}\nFAN_PRESERVED = {\"Fan-Preserved\", \"Fan-Resurrected\"}\n\n\ndef multiplayer_titles():\n    \"\"\"Titles with a DeadGameWiki entry whose single-player survives and whose\n    name or notes say the online part is multiplayer.\"\"\"\n    g = pd.read_csv(GAMES_CSV, low_memory=False)\n    dgl = g[(g[\"source\"] == \"dead_game_list\")\n            & (g[\"raw__deadgamelist__Single_Player_at_risk\"] == \"No\")]\n    text = dgl[\"game_name\"].map(s) + \" \" + dgl[\"raw__deadgamelist__Notes\"].map(s)\n    return set(dgl.loc[text.str.contains(MULTIPLAYER), \"normalized_title\"])\n\n\ndef refine(labels, title, platform, rationale, mp_titles):\n    \"\"\"Apply the taxonomy v2 values to labels made before they existed.\"\"\"\n    changes = []\n    if labels[\"D4\"] == \"Minor\" and (title in mp_titles or MULTIPLAYER.search(rationale)):\n        labels[\"D4\"] = \"Optional Multiplayer\"\n        changes.append(\"D4 Minor -> Optional Multiplayer\")\n    if labels[\"D6\"] == CURRENT and is_legacy_os(platform):\n        labels[\"D6\"] = \"Legacy OS\"\n        changes.append(\"D6 -> Legacy OS\")\n    return \"; \".join(changes)\n\n\ndef main():\n    rules = pd.read_csv(RULES_CSV, keep_default_na=False)\n    llm = pd.read_csv(LLM_CSV, keep_default_na=False).set_index(\"title_id\")\n    sample = pd.read_csv(SAMPLE_CSV, keep_default_na=False).set_index(\"normalized_title\")\n    mp_titles = multiplayer_titles()\n\n    rows, missing = [], []\n    for _, r in rules.iterrows():\n        use_llm = r[\"needs_llm\"] == \"True\" or r[\"needs_llm\"] is True\n        if use_llm and r[\"normalized_title\"] not in llm.index:\n            missing.append(r[\"normalized_title\"])\n            use_llm = False\n        title = r[\"normalized_title\"]\n        src = llm.loc[title] if use_llm else r\n        labels = {k: src[k] for k in DIMENSIONS}\n        refined = refine(labels, title, r[\"platform\"], src[\"rationale\"], mp_titles) if use_llm else \"\"\n        if labels[\"D7\"] in FAN_PRESERVED and labels[\"D5\"] == \"Active\":\n            labels[\"D5\"] = \"Shut down\"\n        method = \"LLM (Haiku)\" if use_llm else \"rules\"\n        confidence = src[\"confidence\"] if use_llm else \"\"\n        evidence = src[\"rationale\"] if use_llm else r[\"evidence\"]\n        note = \"\"\n        if title in sample.index:\n            m = sample.loc[title]\n            labels = {k: m[col] for k, col in DIMENSIONS.items()}\n            method, confidence, evidence, note, refined = (\n                \"manual review\", \"\", m[\"evidence\"], m[\"manual_note\"], \"\")\n        rows.append({\n            \"normalized_title\": r[\"normalized_title\"],\n            \"game_name\": r[\"game_name\"],\n            \"stratum_source\": r[\"stratum_source\"],\n            \"all_sources\": r[\"all_sources\"],\n            \"platform\": r[\"platform\"],\n            **{col: labels[k] for k, col in DIMENSIONS.items()},\n            \"method\": method,\n            \"confidence\": confidence,\n            \"evidence\": evidence,\n            \"manual_note\": note,\n            \"refinement\": refined,\n        })\n\n    out = pd.DataFrame(rows)\n    out.to_csv(OUT_CSV, index=False)\n    print(f\"wrote {len(out)} titles -> {OUT_CSV.name}: \"\n          + \", \".join(f\"{n} {m}\" for m, n in out[\"method\"].value_counts().items())\n          + f\"; {(out.refinement != '').sum()} Haiku labels refined\")\n    if missing:\n        print(f\"WARNING: {len(missing)} titles had no LLM labels, kept rules: {missing}\")\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"Scripts/mining_dead_game_wiki.py","group":"Scripts","text":"#!/usr/bin/env python3\n\nimport json\nimport logging\nfrom pathlib import Path\nfrom urllib.parse import urljoin\n\nimport requests\nfrom bs4 import BeautifulSoup\nfrom requests.adapters import HTTPAdapter\nfrom urllib3.util.retry import Retry\n\n\n# ---------------------------------------------------------------------------\n# Configuration\n# ---------------------------------------------------------------------------\n\nURL = \"https://stopkillinggames.wiki.gg/wiki/Dead_game_list\"\n\nMEDIAWIKI_API_URL = \"https://stopkillinggames.wiki.gg/api.php\"\nMEDIAWIKI_PAGE = \"Dead_game_list\"\n\nTABLE_ID = \"dead-game-table\"\n\nOUTPUT_FILE = (\n    Path(__file__).resolve().parent.parent\n    / \"RawData\" / \"DeadGameWiki\" / \"dead_games.json\"\n)\n\n\n# ---------------------------------------------------------------------------\n# Logging\n# ---------------------------------------------------------------------------\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format=\"%(asctime)s - %(levelname)s - %(message)s\",\n)\n\nlogger = logging.getLogger(__name__)\n\n\n# ---------------------------------------------------------------------------\n# HTTP utilities\n# ---------------------------------------------------------------------------\n\ndef create_session() -> requests.Session:\n    \"\"\"\n    Create an HTTP session with retries and browser-like headers.\n    \"\"\"\n    session = requests.Session()\n\n    retries = Retry(\n        total=3,\n        backoff_factor=1,\n        status_forcelist=[429, 500, 502, 503, 504],\n        allowed_methods=[\"GET\"],\n    )\n\n    adapter = HTTPAdapter(max_retries=retries)\n\n    session.mount(\"https://\", adapter)\n    session.mount(\"http://\", adapter)\n\n    session.headers.update(\n        {\n            \"User-Agent\": (\n                \"Mozilla/5.0 (Windows NT 10.0; Win64; x64) \"\n                \"AppleWebKit/537.36 (KHTML, like Gecko) \"\n                \"Chrome/152.0.0.0 Safari/537.36\"\n            ),\n            \"Accept\": (\n                \"text/html,application/xhtml+xml,application/xml;\"\n                \"q=0.9,image/avif,image/webp,*/*;q=0.8\"\n            ),\n            \"Accept-Language\": \"en-US,en;q=0.9\",\n        }\n    )\n\n    return session\n\n\ndef download_page(session: requests.Session) -> str:\n    \"\"\"\n    Download the normal wiki page.\n\n    If the normal page cannot be retrieved or does not contain the expected\n    table, fall back to the MediaWiki API.\n    \"\"\"\n    logger.info(\"Downloading %s\", URL)\n\n    try:\n        response = session.get(\n            URL,\n            timeout=60,\n        )\n\n        response.raise_for_status()\n\n        html = response.text\n\n        if f'id=\"{TABLE_ID}\"' in html:\n            logger.info(\n                \"Downloaded %.2f MB from the normal page.\",\n                len(response.content) / (1024 * 1024),\n            )\n\n            return html\n\n        logger.warning(\n            \"Page downloaded, but table '%s' was not found. \"\n            \"Trying MediaWiki API.\",\n            TABLE_ID,\n        )\n\n    except requests.RequestException as exc:\n        logger.warning(\n            \"Could not download normal wiki page: %s\",\n            exc,\n        )\n\n    return download_page_via_api(session)\n\n\ndef download_page_via_api(session: requests.Session) -> str:\n    \"\"\"\n    Retrieve the rendered page HTML through the MediaWiki API.\n    \"\"\"\n    logger.info(\"Downloading page through MediaWiki API.\")\n\n    params = {\n        \"action\": \"parse\",\n        \"page\": MEDIAWIKI_PAGE,\n        \"prop\": \"text\",\n        \"format\": \"json\",\n        \"formatversion\": 2,\n    }\n\n    response = session.get(\n        MEDIAWIKI_API_URL,\n        params=params,\n        timeout=60,\n    )\n\n    response.raise_for_status()\n\n    data = response.json()\n\n    if \"parse\" not in data or \"text\" not in data[\"parse\"]:\n        raise RuntimeError(\n            \"MediaWiki API response does not contain rendered page HTML.\"\n        )\n\n    html = data[\"parse\"][\"text\"]\n\n    logger.info(\n        \"Received %.2f MB of rendered HTML through the API.\",\n        len(html.encode(\"utf-8\")) / (1024 * 1024),\n    )\n\n    return html\n\n\n# ---------------------------------------------------------------------------\n# HTML parsing\n# ---------------------------------------------------------------------------\n\ndef clean_cell(cell) -> str:\n    \"\"\"\n    Extract normalized visible text from a table cell.\n    \"\"\"\n    return cell.get_text(\n        \" \",\n        strip=True,\n    )\n\n\ndef extract_home_page(cell) -> str:\n    \"\"\"\n    Extract the URL from the 'Home page' column.\n\n    If the cell contains an <a> element, use its href rather than its\n    displayed text. Relative wiki URLs are converted to absolute URLs.\n    \"\"\"\n    link = cell.find(\"a\", href=True)\n\n    if link:\n        return urljoin(URL, link[\"href\"])\n\n    return clean_cell(cell)\n\n\ndef parse_table(html: str) -> list[dict]:\n    \"\"\"\n    Parse the dead game table and return one dictionary per game.\n\n    Column names are extracted dynamically from the table header.\n    \"\"\"\n    soup = BeautifulSoup(\n        html,\n        \"lxml\",\n    )\n\n    table = soup.find(\n        \"table\",\n        id=TABLE_ID,\n    )\n\n    if table is None:\n        raise RuntimeError(\n            f\"Could not find table with id='{TABLE_ID}'. \"\n            \"The website structure may have changed.\"\n        )\n\n    # ------------------------------------------------------------------\n    # Header\n    #\n    # Unlike the Steam Tracker table, this wiki table has the header\n    # directly inside the first <tr> rather than inside <thead>.\n    # ------------------------------------------------------------------\n\n    header_row = table.find(\"tr\")\n\n    if header_row is None:\n        raise RuntimeError(\n            \"Could not find the table header row.\"\n        )\n\n    headers = [\n        th.get_text(\" \", strip=True)\n        for th in header_row.find_all(\"th\")\n    ]\n\n    if not headers:\n        raise RuntimeError(\n            \"No table headers found.\"\n        )\n\n    logger.info(\n        \"Found %d columns: %s\",\n        len(headers),\n        headers,\n    )\n\n    # ------------------------------------------------------------------\n    # Data rows\n    # ------------------------------------------------------------------\n\n    results = []\n\n    rows = table.find_all(\"tr\")\n\n    # Skip the first row because it contains the table headers.\n    for row_number, row in enumerate(\n        rows[1:],\n        start=1,\n    ):\n        cells = row.find_all(\n            \"td\",\n            recursive=False,\n        )\n\n        if not cells:\n            continue\n\n        if len(cells) != len(headers):\n            logger.warning(\n                \"Skipping row %d: expected %d cells, found %d.\",\n                row_number,\n                len(headers),\n                len(cells),\n            )\n            continue\n\n        record = {}\n\n        for header, cell in zip(\n            headers,\n            cells,\n        ):\n            if header == \"Home page\":\n                value = extract_home_page(cell)\n            else:\n                value = clean_cell(cell)\n\n            record[header] = value\n\n        results.append(record)\n\n    logger.info(\n        \"Successfully parsed %d games.\",\n        len(results),\n    )\n\n    return results\n\n\n# ---------------------------------------------------------------------------\n# JSON output\n# ---------------------------------------------------------------------------\n\ndef save_json(\n    data: list[dict],\n    output_file: Path,\n) -> None:\n    \"\"\"\n    Save extracted data as pretty-printed UTF-8 JSON.\n    \"\"\"\n    output_file.parent.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    with output_file.open(\n        \"w\",\n        encoding=\"utf-8\",\n    ) as file:\n        json.dump(\n            data,\n            file,\n            ensure_ascii=False,\n            indent=2,\n        )\n\n    logger.info(\n        \"Saved %d records to %s\",\n        len(data),\n        output_file,\n    )\n\n\n# ---------------------------------------------------------------------------\n# Main\n# ---------------------------------------------------------------------------\n\ndef main():\n    session = create_session()\n\n    html = download_page(session)\n\n    games = parse_table(html)\n\n    save_json(\n        games,\n        OUTPUT_FILE,\n    )\n\n    # Show a small preview.\n    if games:\n        logger.info(\"First extracted record:\")\n        print(\n            json.dumps(\n                games[0],\n                indent=2,\n                ensure_ascii=False,\n            )\n        )\n\n\nif __name__ == \"__main__\":\n    main()"},{"path":"Scripts/mining_delisted_steam_tracker.py","group":"Scripts","text":"#!/usr/bin/env python3\n\nimport argparse\nimport json\nimport logging\nfrom pathlib import Path\n\nimport requests\nfrom bs4 import BeautifulSoup\nfrom requests.adapters import HTTPAdapter\nfrom urllib3.util.retry import Retry\n\n\nURL = \"https://steam-tracker.com/apps/delisted\"\nTABLE_ID = \"delisted-apps\"\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format=\"%(asctime)s - %(levelname)s - %(message)s\",\n)\nlogger = logging.getLogger(__name__)\n\n\ndef create_session() -> requests.Session:\n    \"\"\"\n    Create an HTTP session with retries and a browser-like User-Agent.\n    \"\"\"\n    session = requests.Session()\n\n    retries = Retry(\n        total=3,\n        backoff_factor=1,\n        status_forcelist=[429, 500, 502, 503, 504],\n        allowed_methods=[\"GET\"],\n    )\n\n    adapter = HTTPAdapter(max_retries=retries)\n    session.mount(\"https://\", adapter)\n    session.mount(\"http://\", adapter)\n\n    session.headers.update(\n        {\n            \"User-Agent\": (\n                \"Mozilla/5.0 (Windows NT 10.0; Win64; x64) \"\n                \"AppleWebKit/537.36 (KHTML, like Gecko) \"\n                \"Chrome/152.0.0.0 Safari/537.36\"\n            ),\n            \"Accept\": (\n                \"text/html,application/xhtml+xml,application/xml;\"\n                \"q=0.9,image/avif,image/webp,*/*;q=0.8\"\n            ),\n            \"Accept-Language\": \"en-US,en;q=0.9\",\n        }\n    )\n\n    return session\n\n\ndef download_page(url: str) -> str:\n    \"\"\"\n    Download the HTML page.\n    \"\"\"\n    logger.info(\"Downloading %s\", url)\n\n    session = create_session()\n\n    response = session.get(\n        url,\n        timeout=60,\n    )\n\n    response.raise_for_status()\n\n    logger.info(\n        \"Downloaded %.2f MB\",\n        len(response.content) / (1024 * 1024),\n    )\n\n    return response.text\n\n\ndef clean_cell(cell) -> str:\n    \"\"\"\n    Extract the visible textual value from a table cell.\n\n    Examples:\n        <td>...</td> -> \"34270\"\n\n        <td>\n            <a>SEGA Mega Drive & Genesis Classics</a>\n        </td>\n        -> \"SEGA Mega Drive & Genesis Classics\"\n    \"\"\"\n    return cell.get_text(\" \", strip=True)\n\n\ndef parse_table(html: str) -> list[dict]:\n    \"\"\"\n    Parse the delisted-apps HTML table.\n\n    The column names are read directly from the table header instead\n    of being hard-coded.\n    \"\"\"\n    soup = BeautifulSoup(html, \"lxml\")\n\n    table = soup.find(\"table\", id=TABLE_ID)\n\n    if table is None:\n        raise RuntimeError(\n            f\"Could not find table with id='{TABLE_ID}'. \"\n            \"The website structure may have changed.\"\n        )\n\n    # Read column names dynamically.\n    headers = [\n        th.get_text(\" \", strip=True)\n        for th in table.select(\"thead th\")\n    ]\n\n    if not headers:\n        raise RuntimeError(\"No table headers found.\")\n\n    logger.info(\"Columns found: %s\", headers)\n\n    results = []\n\n    tbody = table.find(\"tbody\")\n\n    if tbody is None:\n        raise RuntimeError(\"Table contains no <tbody> element.\")\n\n    for row in tbody.find_all(\"tr\", recursive=False):\n\n        cells = row.find_all(\"td\", recursive=False)\n\n        # Skip empty / malformed rows.\n        if not cells:\n            continue\n\n        if len(cells) != len(headers):\n            logger.warning(\n                \"Skipping row: expected %d cells, found %d\",\n                len(headers),\n                len(cells),\n            )\n            continue\n\n        values = [clean_cell(cell) for cell in cells]\n\n        record = dict(zip(headers, values))\n\n        results.append(record)\n\n    return results\n\n\ndef save_json(data: list[dict], output_file: Path) -> None:\n    \"\"\"\n    Save extracted data as pretty-printed UTF-8 JSON.\n    \"\"\"\n    output_file.parent.mkdir(parents=True, exist_ok=True)\n\n    with output_file.open(\"w\", encoding=\"utf-8\") as f:\n        json.dump(\n            data,\n            f,\n            ensure_ascii=False,\n            indent=2,\n        )\n\n    logger.info(\n        \"Saved %d records to %s\",\n        len(data),\n        output_file,\n    )\n\n\ndef main():\n    parser = argparse.ArgumentParser(\n        description=\"Scrape delisted Steam apps from steam-tracker.com\"\n    )\n\n    parser.add_argument(\n        \"-o\",\n        \"--output\",\n        type=Path,\n        default=(\n            Path(__file__).resolve().parent.parent\n            / \"RawData\" / \"SteamTracker\" / \"steam_delisted_apps.json\"\n        ),\n        help=\"Output JSON file\",\n    )\n\n    parser.add_argument(\n        \"--url\",\n        default=URL,\n        help=\"Steam Tracker URL\",\n    )\n\n    args = parser.parse_args()\n\n    html = download_page(args.url)\n\n    data = parse_table(html)\n\n    logger.info(\"Extracted %d applications.\", len(data))\n\n    save_json(data, args.output)\n\n\nif __name__ == \"__main__\":\n    main()"},{"path":"Scripts/mining_doesItPlay.py","group":"Scripts","text":"#!/usr/bin/env python3\n\nimport json\nimport logging\nimport math\nimport re\nimport time\nfrom pathlib import Path\nfrom urllib.parse import urljoin\n\nimport requests\nfrom bs4 import BeautifulSoup\nfrom requests.adapters import HTTPAdapter\nfrom urllib3.util.retry import Retry\n\n\n# ---------------------------------------------------------------------------\n# Configuration\n# ---------------------------------------------------------------------------\n\nBASE_URL = \"https://www.doesitplay.org\"\nLIST_URL = f\"{BASE_URL}/list\"\n\nTABLE_ID = \"indextable\"\n\nOUTPUT_FILE = (\n    Path(__file__).resolve().parent.parent\n    / \"RawData\" / \"doesitplay_games.json\"\n)\n\n# Be polite to the website.\nREQUEST_DELAY_SECONDS = 0.5\n\n\n# ---------------------------------------------------------------------------\n# Logging\n# ---------------------------------------------------------------------------\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format=\"%(asctime)s - %(levelname)s - %(message)s\",\n)\n\nlogger = logging.getLogger(__name__)\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef create_session() -> requests.Session:\n    \"\"\"\n    Create an HTTP session with retries and browser-like headers.\n    \"\"\"\n    session = requests.Session()\n\n    retries = Retry(\n        total=3,\n        backoff_factor=1,\n        status_forcelist=[429, 500, 502, 503, 504],\n        allowed_methods=[\"GET\"],\n    )\n\n    adapter = HTTPAdapter(max_retries=retries)\n\n    session.mount(\"https://\", adapter)\n    session.mount(\"http://\", adapter)\n\n    session.headers.update(\n        {\n            \"User-Agent\": (\n                \"Mozilla/5.0 (Windows NT 10.0; Win64; x64) \"\n                \"AppleWebKit/537.36 (KHTML, like Gecko) \"\n                \"Chrome/152.0.0.0 Safari/537.36\"\n            ),\n            \"Accept\": (\n                \"text/html,application/xhtml+xml,application/xml;\"\n                \"q=0.9,image/avif,image/webp,*/*;q=0.8\"\n            ),\n            \"Accept-Language\": \"en-US,en;q=0.9\",\n        }\n    )\n\n    return session\n\n\ndef download_page(\n    session: requests.Session,\n    page: int,\n) -> str:\n    \"\"\"\n    Download one page of the game list.\n    \"\"\"\n    logger.info(\"Downloading page %d\", page)\n\n    response = session.get(\n        LIST_URL,\n        params={\"page\": page},\n        timeout=60,\n    )\n\n    response.raise_for_status()\n\n    logger.info(\n        \"Downloaded %.2f KB\",\n        len(response.content) / 1024,\n    )\n\n    return response.text\n\n\n# ---------------------------------------------------------------------------\n# Parsing helpers\n# ---------------------------------------------------------------------------\n\ndef clean_text(element) -> str:\n    \"\"\"\n    Extract normalized visible text.\n    \"\"\"\n    if element is None:\n        return \"\"\n\n    return element.get_text(\n        \" \",\n        strip=True,\n    )\n\n\ndef extract_platform(game_cell) -> str:\n    \"\"\"\n    Extract the platform displayed inside the Game cell.\n\n    Example:\n        <div class='platform ps5'>PS5</div>\n    \"\"\"\n    platform_element = game_cell.find(\n        \"div\",\n        class_=\"platform\",\n    )\n\n    return clean_text(platform_element)\n\n\ndef extract_platform_code(game_cell) -> str:\n    \"\"\"\n    Extract the CSS platform identifier.\n\n    Examples:\n        platform ps5     -> ps5\n        platform seriesx -> seriesx\n    \"\"\"\n    platform_element = game_cell.find(\n        \"div\",\n        class_=\"platform\",\n    )\n\n    if platform_element is None:\n        return \"\"\n\n    classes = platform_element.get(\n        \"class\",\n        [],\n    )\n\n    for css_class in classes:\n        if css_class != \"platform\":\n            return css_class\n\n    return \"\"\n\n\ndef extract_game_info(game_cell) -> tuple[str, str]:\n    \"\"\"\n    Extract the game title and the URL to its DoesItPlay detail page.\n    \"\"\"\n    link = game_cell.find(\n        \"a\",\n        href=True,\n    )\n\n    if link is None:\n        return clean_text(game_cell), \"\"\n\n    game_name = clean_text(link)\n\n    game_url = urljoin(\n        BASE_URL,\n        link[\"href\"],\n    )\n\n    return game_name, game_url\n\n\ndef parse_results_count(soup: BeautifulSoup):\n    \"\"\"\n    Extract the total number of results from text such as:\n\n        3522 results found\n\n    Returns None when the value cannot be found.\n    \"\"\"\n    page_text = soup.get_text(\n        \" \",\n        strip=True,\n    )\n\n    match = re.search(\n        r\"([\\d,]+)\\s+results?\\s+found\",\n        page_text,\n        flags=re.IGNORECASE,\n    )\n\n    if match is None:\n        return None\n\n    return int(\n        match.group(1).replace(\",\", \"\")\n    )\n\n\n# ---------------------------------------------------------------------------\n# Table parser\n# ---------------------------------------------------------------------------\n\ndef parse_table(html: str) -> tuple[list[dict], int | None]:\n    \"\"\"\n    Parse one page of the DoesItPlay game table.\n\n    Returns:\n        records\n        total result count, if detectable\n    \"\"\"\n    soup = BeautifulSoup(\n        html,\n        \"lxml\",\n    )\n\n    table = soup.find(\n        \"table\",\n        id=TABLE_ID,\n    )\n\n    if table is None:\n        raise RuntimeError(\n            f\"Could not find table with id='{TABLE_ID}'. \"\n            \"The website structure may have changed.\"\n        )\n\n    tbody = table.find(\"tbody\")\n\n    if tbody is None:\n        raise RuntimeError(\n            \"Could not find table body.\"\n        )\n\n    records = []\n\n    rows = tbody.find_all(\n        \"tr\",\n        recursive=False,\n    )\n\n    for row in rows:\n\n        cells = row.find_all(\n            \"td\",\n            recursive=False,\n        )\n\n        if not cells:\n            continue\n\n        # ---------------------------------------------------------------\n        # Expected table layout:\n        #\n        # 0 -> mobile-only duplicate\n        # 1 -> No.\n        # 2 -> Game\n        # 3 -> Version\n        # 4 -> Region\n        # 5 -> Tested on\n        # 6 -> Offline play\n        # 7 -> Download required\n        # ---------------------------------------------------------------\n\n        if len(cells) < 8:\n            logger.warning(\n                \"Skipping malformed row with %d cells.\",\n                len(cells),\n            )\n            continue\n\n        number_cell = cells[1]\n        game_cell = cells[2]\n        version_cell = cells[3]\n        region_cell = cells[4]\n        tested_on_cell = cells[5]\n        offline_cell = cells[6]\n        download_cell = cells[7]\n\n        game_name, game_url = extract_game_info(\n            game_cell\n        )\n\n        record = {\n            \"No\": clean_text(number_cell),\n\n            \"Game\": game_name,\n\n            # Additional structured information from the Game cell.\n            \"Platform\": extract_platform(game_cell),\n            \"PlatformCode\": extract_platform_code(game_cell),\n\n            \"Version\": clean_text(version_cell),\n            \"Region\": clean_text(region_cell),\n            \"TestedOn\": clean_text(tested_on_cell),\n\n            \"OfflinePlay\": clean_text(offline_cell),\n            \"DownloadRequired\": clean_text(download_cell),\n\n            # Useful for later enrichment.\n            \"GameURL\": game_url,\n        }\n\n        records.append(record)\n\n    total_results = parse_results_count(\n        soup\n    )\n\n    return records, total_results\n\n\n# ---------------------------------------------------------------------------\n# Pagination\n# ---------------------------------------------------------------------------\n\ndef scrape_all_games(\n    session: requests.Session,\n) -> list[dict]:\n    \"\"\"\n    Scrape every page from DoesItPlay.\n\n    The first page is used to determine the total number of results and\n    estimate the number of pages. A duplicate-page check is also used as\n    a safety mechanism.\n    \"\"\"\n    all_records = []\n\n    # ---------------------------------------------------------------\n    # First page\n    # ---------------------------------------------------------------\n\n    first_html = download_page(\n        session,\n        page=1,\n    )\n\n    first_records, total_results = parse_table(\n        first_html\n    )\n\n    if not first_records:\n        raise RuntimeError(\n            \"The first page contains no game records.\"\n        )\n\n    all_records.extend(\n        first_records\n    )\n\n    records_per_page = len(first_records)\n\n    logger.info(\n        \"Records on first page: %d\",\n        records_per_page,\n    )\n\n    # ---------------------------------------------------------------\n    # Determine number of pages\n    # ---------------------------------------------------------------\n\n    if total_results is not None:\n\n        total_pages = math.ceil(\n            total_results / records_per_page\n        )\n\n        logger.info(\n            \"Total results reported by website: %d\",\n            total_results,\n        )\n\n        logger.info(\n            \"Estimated pages: %d\",\n            total_pages,\n        )\n\n    else:\n        # Fallback mode:\n        # continue until a page returns no data or repeats the previous page.\n        logger.warning(\n            \"Could not determine total result count. \"\n            \"Using open-ended pagination.\"\n        )\n\n        total_pages = None\n\n    # Fingerprint used to detect accidental repeated pages.\n    previous_fingerprint = tuple(\n        record[\"GameURL\"]\n        for record in first_records\n    )\n\n    page = 2\n\n    while True:\n\n        if total_pages is not None and page > total_pages:\n            break\n\n        time.sleep(\n            REQUEST_DELAY_SECONDS\n        )\n\n        html = download_page(\n            session,\n            page=page,\n        )\n\n        records, _ = parse_table(\n            html\n        )\n\n        if not records:\n            logger.info(\n                \"No records found on page %d. Stopping.\",\n                page,\n            )\n            break\n\n        current_fingerprint = tuple(\n            record[\"GameURL\"]\n            for record in records\n        )\n\n        if current_fingerprint == previous_fingerprint:\n            logger.warning(\n                \"Page %d duplicates the previous page. \"\n                \"Stopping pagination.\",\n                page,\n            )\n            break\n\n        all_records.extend(\n            records\n        )\n\n        logger.info(\n            \"Collected %d records so far.\",\n            len(all_records),\n        )\n\n        previous_fingerprint = current_fingerprint\n\n        page += 1\n\n    return all_records\n\n\n# ---------------------------------------------------------------------------\n# Deduplication\n# ---------------------------------------------------------------------------\n\ndef remove_exact_duplicates(\n    records: list[dict],\n) -> list[dict]:\n    \"\"\"\n    Remove exact duplicate game-test records.\n\n    A game can legitimately appear multiple times because different\n    platforms, editions, regions, or tested hardware are separate tests.\n\n    Therefore the key contains all those fields.\n    \"\"\"\n    unique_records = []\n\n    seen = set()\n\n    for record in records:\n\n        key = (\n            record[\"Game\"],\n            record[\"Platform\"],\n            record[\"Version\"],\n            record[\"Region\"],\n            record[\"TestedOn\"],\n            record[\"OfflinePlay\"],\n            record[\"DownloadRequired\"],\n        )\n\n        if key in seen:\n            continue\n\n        seen.add(key)\n\n        unique_records.append(\n            record\n        )\n\n    return unique_records\n\n\n# ---------------------------------------------------------------------------\n# Output\n# ---------------------------------------------------------------------------\n\ndef save_json(\n    data: list[dict],\n    output_file: Path,\n) -> None:\n    \"\"\"\n    Save records to a UTF-8 JSON file.\n    \"\"\"\n    output_file.parent.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    with output_file.open(\n        \"w\",\n        encoding=\"utf-8\",\n    ) as file:\n\n        json.dump(\n            data,\n            file,\n            ensure_ascii=False,\n            indent=2,\n        )\n\n    logger.info(\n        \"Saved %d records to %s\",\n        len(data),\n        output_file,\n    )\n\n\n# ---------------------------------------------------------------------------\n# Main\n# ---------------------------------------------------------------------------\n\ndef main():\n\n    session = create_session()\n\n    records = scrape_all_games(\n        session\n    )\n\n    logger.info(\n        \"Raw records collected: %d\",\n        len(records),\n    )\n\n    records = remove_exact_duplicates(\n        records\n    )\n\n    logger.info(\n        \"Records after exact deduplication: %d\",\n        len(records),\n    )\n\n    save_json(\n        records,\n        OUTPUT_FILE,\n    )\n\n    if records:\n        print(\"\\nExample record:\\n\")\n\n        print(\n            json.dumps(\n                records[0],\n                indent=2,\n                ensure_ascii=False,\n            )\n        )\n\n\nif __name__ == \"__main__\":\n    main()"},{"path":"Scripts/sample_taxonomy_classification.py","group":"Scripts","text":"\"\"\"Draw a stratified random sample of unique titles and pre-classify them\nalong the seven taxonomy dimensions using dataset fields only.\n\nSample: n=196 unique normalized titles (95% CI, +/-7%, N=11,762),\nproportional allocation by source. A title present in several sources is\nassigned to its smallest source. Classification is judged on the platform\nlisted in the stratum source record. 'N/A' = dimension does not apply,\n'Unknown' = dataset carries no evidence.\n\nUsage: python Scripts/sample_taxonomy_classification.py\n\"\"\"\n\nimport re\nfrom pathlib import Path\n\nimport pandas as pd\n\nROOT = Path(__file__).resolve().parents[1]\nIN_CSV = ROOT / \"Analysis\" / \"unified_games.csv\"\nOUT_CSV = ROOT / \"Analysis\" / \"taxonomy_sample_classification.csv\"\nN, SEED = 196, 42\n\n# Platforms whose hardware is no longer manufactured.\nLEGACY = re.compile(\n    r\"ps1|psone|ps2|ps3|playstation[- ]?(1|2|3|portable)|psp|vita|xbox 360|\"\n    r\"xbox-360|^xbox$|wii|3ds|\\bds\\b|nintendo-ds|gamecube|dreamcast|saturn|\"\n    r\"n64|game ?boy|gba|neo ?geo|amiga|atari|arcade|ouya|ngage|n-gage|zeebo\",\n    re.I,\n)\n\n# Discontinued OS versions and runtimes on hardware that is still produced.\n# A title is Legacy OS only if every platform it lists is one of these.\nLEGACY_OS = re.compile(\n    r\"flash|shockwave|\\bjava\\b|unity web|web \\(unity\\)|ms-?dos|windows (3\\.|9[58]|me\\b)|mac ?os (9|classic)\",\n    re.I,\n)\n\n# Online play named in a source: the online part is the multiplayer modes.\nMULTIPLAYER = re.compile(\n    r\"multi-?player|\\bpvp\\b|\\bpve\\b|co-?op|versus|matchmaking|online (?:play|modes?|match(?:es)?|races?)\",\n    re.I,\n)\n\nCURRENT = \"Run on current hardware platform or OS\"\n\n\ndef is_legacy(platform):\n    return bool(platform) and bool(LEGACY.search(str(platform)))\n\n\ndef is_legacy_os(platform):\n    parts = [p.strip() for p in re.split(r\"[,;|\\n]+\", str(platform or \"\")) if p.strip()]\n    return bool(parts) and all(LEGACY_OS.search(p) for p in parts)\n\n\ndef platform_access(platform):\n    if is_legacy(platform):\n        return \"Legacy Hardware\"\n    return \"Legacy OS\" if is_legacy_os(platform) else CURRENT\n\n\ndef s(v):\n    return \"\" if pd.isna(v) else str(v).strip()\n\n\ndef classify(r):\n    \"\"\"Return dict of D1..D7 plus evidence for one record.\"\"\"\n    src = r[\"source\"]\n    plat = s(r[\"platforms\"])\n    c = {f\"D{i}\": \"Unknown\" for i in range(1, 8)}\n    ev = []\n\n    if src == \"steam_tracker\":\n        t = s(r[\"raw__steamtracker__Type\"])\n        c[\"D1\"] = \"Never Offered\" if t == \"Pre-order exclusive\" else \"Unavailable\"\n        if t == \"Retail only\":\n            c[\"D2\"] = \"Retail\"\n            c[\"D3\"] = \"Key or launcher only\"\n        c[\"D6\"] = CURRENT\n        ev.append(f\"SteamTracker type={t}\")\n        if s(r[\"raw__steamtracker__Keyshops\"]):\n            ev.append(f\"keyshop price={s(r['raw__steamtracker__Keyshops'])}\")\n\n    elif src == \"delisted_games\":\n        c[\"D1\"] = \"Unavailable\"\n        avail = s(r[\"raw__delistedgames__data__available_on\"])\n        if avail:\n            ev.append(\"available_on=\" + avail.replace(\"\\n\", \" | \"))\n        c[\"D6\"] = platform_access(plat)\n        if re.search(r\"\\bretail\\b\", avail, re.I):\n            c[\"D2\"] = \"Second-hand\" if is_legacy(plat) else \"Retail\"\n\n    elif src == \"doesitplay\":\n        off = s(r[\"raw__doesitplay__OfflinePlay\"])\n        dl = s(r[\"raw__doesitplay__DownloadRequired\"])\n        c[\"D4\"] = {\"Yes\": \"None\", \"Yes*\": \"Minor\", \"No\": \"Core Gameplay\"}.get(off, \"Unknown\")\n        c[\"D3\"] = {\"No\": \"Complete\", \"No*\": \"Partial\", \"Yes*\": \"Partial\",\n                   \"Yes\": \"Key or launcher only\"}.get(dl, \"Unknown\")\n        plat = s(r[\"raw__doesitplay__Platform\"]) or plat\n        c[\"D6\"] = platform_access(plat)\n        if c[\"D6\"] == \"Legacy Hardware\":\n            c[\"D2\"] = \"Second-hand\"\n        if c[\"D4\"] == \"None\":\n            c[\"D5\"] = \"N/A\"\n        ev.append(f\"doesitplay Offline={off}; Download={dl}; \"\n                  f\"version={s(r['raw__doesitplay__Version'])}\")\n\n    elif src == \"dead_game_list\":\n        state = s(r[\"raw__deadgamelist__State\"])\n        # List only tracks online-dependent games; if single-player survives\n        # the shutdown, only multiplayer (when the entry names it) or\n        # secondary features depend on the connection.\n        sp = s(r[\"raw__deadgamelist__Single_Player_at_risk\"])\n        if sp == \"No\":\n            text = f\"{s(r['game_name'])} {s(r['raw__deadgamelist__Notes'])}\"\n            c[\"D4\"] = \"Optional Multiplayer\" if MULTIPLAYER.search(text) else \"Minor\"\n        else:\n            c[\"D4\"] = \"Core Gameplay\"\n        c[\"D5\"] = {\"Dead\": \"Shut down\", \"At Risk\": \"Active\"}.get(state, \"Shut down\")\n        c[\"D7\"] = state if state in {\"Dev-Preserved\", \"Fan-Preserved\",\n                                     \"Fan-Resurrected\"} else \"None\"\n        c[\"D6\"] = platform_access(plat)\n        ev.append(f\"DeadGameWiki state={state}; \"\n                  f\"SP_at_risk={s(r['raw__deadgamelist__Single_Player_at_risk'])}; \"\n                  f\"subscription={s(r['raw__deadgamelist__Subscription_(Pay_to_Play)'])}\")\n\n    c[\"evidence\"] = \"; \".join(ev)\n    return c\n\n\n# Manual judgements from the free-text fields (DeadGameWiki Notes,\n# delistedGames info), keyed by game_name of the stratum record.\nOVERRIDES = {\n    \"The Punisher: No Mercy\": {\"D2\": \"Never released\", \"note\": \"dev: 'Too bad it's digital'\"},\n    \"Bloodlines of Prima\": {\"D4\": \"Core Gameplay\", \"D5\": \"Shut down\", \"note\": \"F2P MMO, servers offline 2020-12-29\"},\n    \"Lif\": {\"D4\": \"Optional Multiplayer\", \"D5\": \"Shut down\", \"note\": \"servers offline 2017; single-player unaffected\"},\n    \"Ride Out Heroes!\": {\"D4\": \"Core Gameplay\", \"D5\": \"Shut down\", \"note\": \"game operations terminated 2021-12-15\"},\n    \"Fish On 3D\": {\"D1\": \"Regionally Limited\", \"note\": \"delisted NA, available in EU per source (3DS eShop closed 2023, not in dataset)\"},\n    \"DuckTales: Remastered [RELISTED]\": {\"D1\": \"Available\", \"note\": \"relisted 2020\"},\n    \"Max Payne 2: The Fall of Max Payne [RELISTED]\": {\"D1\": \"Regionally Limited\", \"note\": \"delisted on Steam in select territories\"},\n    \"Cold Dreams\": {\"D1\": \"Available\", \"note\": \"still sold on itch.io (PC)\"},\n    \"Ricochet Infinity\": {\"D1\": \"Available\", \"D4\": \"Minor\", \"D5\": \"Shut down\", \"note\": \"sold on online portals; level-sharing servers closed 2017\"},\n    \"Game of Thrones\": {\"D1\": \"Regionally Limited\", \"note\": \"PS3 still available in AU/EU\"},\n    \"Days of Thunder: NASCAR Edition\": {\"D2\": \"Second-hand\", \"note\": \"only on PS3 Blu-ray combo pack\"},\n    \"Street Fighter X Tekken\": {\"D2\": \"Second-hand\", \"D4\": \"Launch Authentication\", \"D5\": \"Shut down\", \"note\": \"Games for Windows LIVE backend; PC retail marked unplayable\"},\n    \"The King of Fighters XIII [RELISTED]\": {\"D1\": \"Available\", \"note\": \"relisted on PS3 NA 2018\"},\n    \"IL-2 Sturmovik: Cliffs of Dover\": {\"D1\": \"Available\", \"note\": \"replaced on Steam by Blitz edition, free for owners\"},\n    \"Kingdom Under Fire: A War of Heroes\": {\"D1\": \"Available\", \"note\": \"notes link to Steam GOLD Edition page\"},\n    \"Dying Light (online multiplayer)\": {\"D4\": \"Optional Multiplayer\", \"note\": \"only PvP/co-op modes depend on servers\"},\n    \"LEGO Horizon Adventures\": {\"D4\": \"Launch Authentication\", \"note\": \"PSN account login required to start on Steam\"},\n    \"Fuser (online services)\": {\"D1\": \"Unavailable\", \"D4\": \"Optional Multiplayer\",\n                                \"note\": \"no longer purchasable digitally; single-player remains playable; fan resurrection in development\"},\n    \"Suicide Squad: Kill the Justice League\": {\"D4\": \"None\", \"note\": \"offline-mode update released\"},\n    \"Just Dance 2018 (Online Services)\": {\"D6\": \"Run on current hardware platform or OS\", \"note\": \"also on PS4/XB1/Switch\"},\n    \"Gigantic\": {\"D1\": \"Unavailable\", \"D5\": \"Active\", \"D7\": \"Dev-Preserved\",\n                 \"note\": \"officially relaunched 2024-04-10; Steam F2P (unavailable)\"},\n    # Corrections from the Haiku pilot (cross-source records on the same platform).\n    \"Danganronpa: Trigger Happy Havoc\": {\"D3\": \"Complete\", \"D4\": \"None\", \"D5\": \"N/A\",\n                                          \"note\": \"doesitplay PS Vita record: Offline=Yes, Download=No\"},\n    \"Might & Magic Heroes Online\": {\"D1\": \"Unavailable\", \"note\": \"Steam Tracker: F2P (unavailable)\"},\n    \"Highguard\": {\"D1\": \"Unavailable\", \"note\": \"Steam Tracker: F2P (unavailable); delisted on Steam\"},\n    \"The Golf Club 2 (online services)\": {\"D1\": \"Unavailable\", \"D2\": \"Retail\",\n                                          \"note\": \"Steam purchase disabled; retail on PS4/XB1/PC\"},\n    \"Madden NFL 06\": {\"D6\": \"Run on current hardware platform or OS\", \"note\": \"platform list includes PC\"},\n}\n\n\ndef main():\n    d = pd.read_csv(IN_CSV, low_memory=False)\n    size = d.groupby(\"source\")[\"normalized_title\"].nunique().sort_values()\n    rank = {src: i for i, src in enumerate(size.index)}\n\n    titles = (d.assign(_r=d[\"source\"].map(rank))\n                .sort_values([\"normalized_title\", \"_r\", \"source_record_id\"])\n                .groupby(\"normalized_title\")\n                .agg(stratum=(\"source\", \"first\"),\n                     all_sources=(\"source\", lambda x: \"|\".join(sorted(set(x))))))\n    alloc = (titles[\"stratum\"].value_counts() / len(titles) * N).round().astype(int)\n    alloc.iloc[0] += N - alloc.sum()\n\n    picked = pd.concat(\n        titles[titles[\"stratum\"] == st].sample(k, random_state=SEED)\n        for st, k in alloc.items()\n    ).reset_index()\n\n    rows = []\n    for _, t in picked.iterrows():\n        recs = d[(d[\"normalized_title\"] == t[\"normalized_title\"])]\n        prim = recs[recs[\"source\"] == t[\"stratum\"]].iloc[0]\n        c = classify(prim)\n        # Preservation state from DeadGameWiki applies regardless of stratum.\n        dgl = recs[recs[\"source\"] == \"dead_game_list\"]\n        if t[\"stratum\"] != \"dead_game_list\" and len(dgl):\n            st = s(dgl.iloc[0][\"raw__deadgamelist__State\"])\n            if st in {\"Dev-Preserved\", \"Fan-Preserved\", \"Fan-Resurrected\"}:\n                c[\"D7\"] = st\n        o = OVERRIDES.get(prim[\"game_name\"], {})\n        for k in (\"D1\", \"D2\", \"D3\", \"D4\", \"D5\", \"D6\", \"D7\"):\n            c[k] = o.get(k, c[k])\n        rows.append({\n            \"normalized_title\": t[\"normalized_title\"],\n            \"game_name\": prim[\"game_name\"],\n            \"stratum_source\": t[\"stratum\"],\n            \"all_sources\": t[\"all_sources\"],\n            \"source_record_id\": prim[\"source_record_id\"],\n            \"platform\": s(prim[\"raw__doesitplay__Platform\"]) or s(prim[\"platforms\"]),\n            \"release_year\": prim[\"release_year\"],\n            \"event_year\": prim[\"event_year\"],\n            \"D1_digital_availability\": c[\"D1\"],\n            \"D2_physical_availability\": c[\"D2\"],\n            \"D3_medium_completeness\": c[\"D3\"],\n            \"D4_online_dependency\": c[\"D4\"],\n            \"D5_service_status\": c[\"D5\"],\n            \"D6_platform_accessibility\": c[\"D6\"],\n            \"D7_preservation\": c[\"D7\"],\n            \"evidence\": c[\"evidence\"],\n            \"manual_note\": o.get(\"note\", \"\"),\n            \"free_text\": \" || \".join(filter(None, [\n                s(prim[\"raw__deadgamelist__Notes\"]),\n                s(prim[\"raw__delistedgames__data__info\"])[:1500],\n            ])),\n        })\n    out = pd.DataFrame(rows)\n    out.to_csv(OUT_CSV, index=False)\n    print(alloc.to_string())\n    print(f\"wrote {len(out)} rows -> {OUT_CSV}\")\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"Scripts/scraperDelistedGames.py","group":"Scripts","text":"import json\nimport time\nimport requests\nfrom bs4 import BeautifulSoup\n\nplatforms = [\"pc\",\"epic-games-store\",\"games-for-windows\",\"gog\",\"microsoft-store\",\"steam\",\"nintendo-switch\",\"nintendo-wii-u\",\"nintendo-wii\",\"nintendo-3ds\",\"nintendo-ds\",\"playstation-5\",\"playstation-4\",\"playstation-3\",\"playstation-2\",\"playstation-vita\",\"playstation-portable\",\"google-stadia\"] #.com/all-delisted-xxx-games/\n#platforms_xbox =[\"xbox-series-xs\",\"xbox-one\",\"xbox-360\"] #.com/xbox-series-xs-games/\n\nurl = \"https://www.delistedgames.com/all-delisted-pc-games/\"\n\ndef site_scraper():\n    for platform in platforms:#platform_xbox\n        game_scraper(\"https://www.delistedgames.com/all-delisted-\"+platform+\"-games/\",platform)\n\ndef game_scraper(url, platform):\n    game = {}\n    response = requests.get(url)\n    counter = 0\n    limit = 3000\n\n    soup = BeautifulSoup(response.text, 'html.parser')\n\n    upper_games = soup.find_all('h4', class_='pt-cv-title')\n    for upper_game in upper_games:\n        saved_games_data = load()\n        ##### utile per fare analisi quando si recupera il lavoro e riposizionarsi sul gioco giusto\n        saved_games_names = []\n        for saved_game in saved_games_data:\n            saved_games_names.append(saved_game[\"data\"][\"title\"])\n\n        game_info = {}\n        game_name = upper_game.contents[0].text\n        if game_name not in saved_games_names:\n            game_url = upper_game.find('a')['href']\n            game_response = requests.get(game_url)\n            soup = BeautifulSoup(game_response.text, 'html.parser')\n            game_infos_tables = soup.find('table')\n\n        #### Static Hardcoded Version ####\n            digital_release = \"\"\n            delisting = \"\"\n            developer = \"\"\n            publisher = \"\"\n            available_on = \"\"\n            links = \"\"\n\n            index = 0\n            if game_infos_tables is not None:\n                for row in game_infos_tables.find_all('tr'):\n                    columns = row.find_all('td')\n\n                    #Digital Release field\n                    if index == 0:\n                        digital_release = columns[2].text\n                    #Delisting field\n                    if index == 1:\n                        delisting = columns[1].text\n                    #Developer field\n                    if index == 2:\n                        developer = columns[1].text\n                    #Publisher field\n                    if index == 3:\n                        publisher =columns[1].text\n                    #Available on field\n                    if index == 4:\n                        available_on = columns[1].text\n                    #Links field\n                    if index == 5:\n                        a_elements = columns[1].find_all('a')\n                        for a_element in a_elements:\n                            href = a_element.get(\"href\")\n                            if href is not None:\n                                links = links + \"-\" + href #ahref links\n                            else:\n                                links = \"None\"\n\n                    index += 1\n\n\n            game_info[\"title\"] = game_name\n            game_info[\"platform\"] = platform #snellire\n            game_info[\"digital_release\"] = digital_release\n            game_info[\"delisting\"] = delisting\n            game_info[\"developer\"] = developer\n            game_info[\"publisher\"] = publisher\n            game_info[\"available_on\"] = available_on\n            game_info[\"links\"] = links\n\n            textual_infos = soup.find_all('p')\n            text_info = []\n            for textual_info in textual_infos:\n                text_info.append(textual_info.text)\n\n            game_info[\"info\"] = text_info\n\n            ##### save #####\n            if(len(saved_games_data) > 0):\n                last_game_index = saved_games_data[-1][\"id\"]\n            else:\n                last_game_index = -1\n            game[\"id\"] = last_game_index + 1\n            game[\"data\"] = game_info\n            saved_games_data.append(game)\n            save(saved_games_data)\n            ################\n\n        else:\n            continue\n\n        if counter > limit:\n            break\n        counter += 1\n\n        time.sleep(10)\n\ndef save(new_data):\n    with open(\"delistedgames.json\", \"w\") as outfile:\n        json.dump(new_data, outfile, indent=4, ensure_ascii=False)\n\ndef load():\n    with open(\"delistedgames.json\", \"r\") as file:\n        try:\n            data = json.load(file)\n        except Exception as e:\n            print(e)\n            data = []\n    return data\n\nsite_scraper()"},{"path":"IGDB_miner/config.py","group":"IGDB_miner","text":"# endpoints\nGAMES_URL = \"https://api.igdb.com/v4/games\"\n\n\n#error handling\n\nMAX_RETRIES = 3  # Maximum number of retries\n\n\n# auth config\n# Real values live in IGDB_miner/.env (local only, excluded via .git/info/exclude).\nfrom pathlib import Path\n\n_env = {}\n_env_file = Path(__file__).with_name(\".env\")\nif _env_file.exists():\n    for _line in _env_file.read_text().splitlines():\n        if \"=\" in _line and not _line.lstrip().startswith(\"#\"):\n            _key, _value = _line.split(\"=\", 1)\n            _env[_key.strip()] = _value.strip()\n\ntoken = _env.get(\"IGDB_TOKEN\", \"token here\")\nCLIENT_ID = _env.get(\"IGDB_CLIENT_ID\", \"client id here\")\n"},{"path":"IGDB_miner/igdb_game_metadata_miner.py","group":"IGDB_miner","text":"#!/usr/bin/env python3\n\n\"\"\"\nIGDB enrichment miner for the unified games dataset.\n\nThis script is intentionally limited to the same IGDB access pattern used by\nthe provided miner skeleton:\n\n    - requests.post\n    - pandas\n    - config.py\n    - IGDB endpoints already declared in config.py\n\nIt implements two workflows:\n\n1. match_genres_for_normalized_games(...)\n   Match every unique normalized game title in the unified dataset against\n   IGDB and export its IGDB genres.\n\n2. compute_games_released_by_year(...)\n   Count the number of IGDB games whose `first_release_date` falls in each\n   requested calendar year. These counts can later be used as a denominator\n   when studying historical delisting counts.\n\nNo OAuth/token creation is implemented here. The script expects CLIENT_ID and\ntoken to be supplied through the existing config.py file.\n\nInputs:\n    - ../Analysis/unified_games.csv\n    - genres.csv\n    - config.py\n\nOutputs (next to this script):\n    - igdb_genres_by_normalized_game.csv\n    - igdb_games_released_by_year.csv\n\"\"\"\n\nfrom requests import post\nimport pandas as pd\nimport config as cf\nimport ast\nimport os\nimport re\nimport unicodedata\nfrom pathlib import Path\n\n\n# ---------------------------------------------------------------------------\n# Configuration\n# ---------------------------------------------------------------------------\n\nBASE_DIR = Path(__file__).resolve().parent\n\nUNIFIED_GAMES_CSV = BASE_DIR.parent / \"Analysis\" / \"unified_games.csv\"\nGENRES_CSV = BASE_DIR / \"genres.csv\"\n\nGENRE_OUTPUT_CSV = BASE_DIR / \"igdb_genres_by_normalized_game.csv\"\nYEAR_OUTPUT_CSV = BASE_DIR / \"igdb_games_released_by_year.csv\"\n\nIGDB_SEARCH_LIMIT = 20\nIGDB_PAGE_SIZE = 500\n\nRELEASE_GAME_TYPE_IDS = (0, 8, 9, 10, 11)\n\n\n# ---------------------------------------------------------------------------\n# Shared IGDB helpers\n# ---------------------------------------------------------------------------\n\ndef build_igdb_headers(query: str) -> dict:\n    \"\"\"\n    Build the request payload using the same authentication mechanism as the\n    provided miner skeleton.\n\n    The token itself is NOT created by this script.\n    \"\"\"\n    return {\n        \"headers\": {\n            \"Client-ID\": cf.CLIENT_ID,\n            \"Authorization\": \"Bearer \" + cf.token,\n        },\n        \"data\": query,\n    }\n\n\ndef post_igdb(url: str, query: str):\n    \"\"\"\n    Execute one IGDB POST request.\n\n    Retries use the MAX_RETRIES value already provided by config.py.\n    No additional HTTP/client library is introduced.\n    \"\"\"\n    last_error = None\n\n    max_retries = getattr(\n        cf,\n        \"MAX_RETRIES\",\n        3,\n    )\n\n    for attempt in range(1, max_retries + 1):\n        try:\n            response = post(\n                url,\n                **build_igdb_headers(query),\n            )\n\n            response.raise_for_status()\n\n            return response\n\n        except Exception as exc:\n            last_error = exc\n\n            print(\n                f\"IGDB request failed \"\n                f\"(attempt {attempt}/{max_retries}): {exc}\"\n            )\n\n    raise RuntimeError(\n        \"IGDB request failed after all retries.\"\n    ) from last_error\n\n\ndef escape_igdb_search_text(value: str) -> str:\n    \"\"\"\n    Escape characters that would otherwise break an IGDB search string.\n    \"\"\"\n    value = str(value)\n\n    value = value.replace(\"\\\\\", \"\\\\\\\\\")\n    value = value.replace('\"', '\\\\\"')\n\n    return value\n\n\ndef normalize_for_match(value) -> str:\n    \"\"\"\n    Normalize an IGDB title in the same general form used by the unified\n    dataset's normalized_title field.\n\n    This normalization is used only to validate candidate matches.\n    \"\"\"\n    if value is None or pd.isna(value):\n        return \"\"\n\n    value = re.sub(\n        r\"[™®©]\",\n        \"\",\n        str(value),\n    )\n\n    value = unicodedata.normalize(\n        \"NFKC\",\n        value,\n    ).casefold()\n\n    value = re.sub(\n        r\"\\([^)]*\\)\",\n        \" \",\n        value,\n    )\n\n    value = re.sub(\n        r\"[^\\w]+\",\n        \" \",\n        value,\n        flags=re.UNICODE,\n    )\n\n    value = value.replace(\n        \"_\",\n        \" \",\n    )\n\n    value = re.sub(\n        r\"\\s+\",\n        \" \",\n        value,\n    )\n\n    return value.strip()\n\n\ndef parse_id_list(value) -> list[int]:\n    \"\"\"\n    Convert a genre/platform-style IGDB ID field into a list of integers.\n\n    Handles:\n        [4, 5]\n        \"[4, 5]\"\n        \"4,5\"\n        4\n    \"\"\"\n    if value is None:\n        return []\n\n    if isinstance(value, list):\n        result = []\n\n        for item in value:\n            try:\n                result.append(int(item))\n            except (TypeError, ValueError):\n                pass\n\n        return result\n\n    if pd.isna(value):\n        return []\n\n    if isinstance(value, str):\n        stripped = value.strip()\n\n        if not stripped:\n            return []\n\n        try:\n            parsed = ast.literal_eval(stripped)\n\n            if isinstance(parsed, list):\n                return [\n                    int(item)\n                    for item in parsed\n                    if str(item).strip()\n                ]\n\n        except (ValueError, SyntaxError):\n            pass\n\n        result = []\n\n        for item in stripped.split(\",\"):\n            item = item.strip()\n\n            if not item:\n                continue\n\n            try:\n                result.append(int(item))\n            except ValueError:\n                pass\n\n        return result\n\n    try:\n        return [int(value)]\n    except (TypeError, ValueError):\n        return []\n\n\ndef load_genre_mapping(\n    genres_csv: str = GENRES_CSV,\n) -> dict[int, str]:\n    \"\"\"\n    Load the local IGDB genre mapping supplied with the miner.\n\n    Expected columns:\n        genre_id\n        genre\n    \"\"\"\n    genres_df = pd.read_csv(\n        genres_csv\n    )\n\n    required_columns = {\n        \"genre_id\",\n        \"genre\",\n    }\n\n    missing = (\n        required_columns\n        - set(genres_df.columns)\n    )\n\n    if missing:\n        raise ValueError(\n            \"genres.csv is missing required columns: \"\n            + \", \".join(sorted(missing))\n        )\n\n    genres_df[\"genre_id\"] = pd.to_numeric(\n        genres_df[\"genre_id\"],\n        errors=\"coerce\",\n    )\n\n    genres_df = genres_df.dropna(\n        subset=[\"genre_id\"]\n    )\n\n    return {\n        int(row[\"genre_id\"]): safe_text(row[\"genre\"])\n        for _, row in genres_df.iterrows()\n        if safe_text(row[\"genre\"])\n    }\n\n\ndef genre_ids_to_names(\n    genre_ids,\n    genre_mapping: dict[int, str],\n) -> list[str]:\n    \"\"\"\n    Resolve IGDB genre IDs using the provided local genre table.\n    \"\"\"\n    ids = parse_id_list(\n        genre_ids\n    )\n\n    return [\n        safe_text(genre_mapping[genre_id])\n        for genre_id in ids\n        if genre_id in genre_mapping\n        and safe_text(genre_mapping[genre_id])\n    ]\n\n\n\ndef safe_text(value, fallback: str = \"\") -> str:\n    \"\"\"\n    Convert malformed/missing scalar values to a safe string.\n\n    In particular, pandas may represent missing game names as float NaN.\n    This helper prevents expressions such as:\n\n        NaN + \" | retry: ...\"\n\n    from raising TypeError.\n    \"\"\"\n    if value is None:\n        return fallback\n\n    try:\n        if pd.isna(value):\n            return fallback\n    except (TypeError, ValueError):\n        pass\n\n    value = str(value).strip()\n\n    if not value:\n        return fallback\n\n    return value\n\n\ndef first_valid_text(values, fallback: str = \"\") -> str:\n    \"\"\"\n    Return the first non-empty, non-null textual value from a pandas Series.\n    \"\"\"\n    for value in values:\n        cleaned = safe_text(value)\n\n        if cleaned:\n            return cleaned\n\n    return fallback\n\n\ndef write_genre_result_row(\n    row: dict,\n    output_csv: str,\n) -> None:\n    \"\"\"\n    Append one processed game immediately to the output CSV.\n\n    This acts as a checkpoint: even if a later record fails unexpectedly,\n    all previously processed rows remain available on disk.\n    \"\"\"\n    write_header = not os.path.exists(output_csv)\n\n    pd.DataFrame([row]).to_csv(\n        output_csv,\n        mode=\"a\",\n        header=write_header,\n        index=False,\n        encoding=\"utf-8\",\n    )\n\n\n# ---------------------------------------------------------------------------\n# IGDB game search\n# ---------------------------------------------------------------------------\n\ndef build_query_game_search(\n    game_name: str,\n    limit: int = IGDB_SEARCH_LIMIT,\n) -> str:\n    \"\"\"\n    Search IGDB's games endpoint for a title.\n\n    The fields are deliberately limited to those needed by the two analyses.\n    \"\"\"\n    escaped_name = escape_igdb_search_text(\n        game_name\n    )\n\n    return (\n        f'search \"{escaped_name}\"; '\n        \"fields id,name,genres,first_release_date; \"\n        f\"limit {limit};\"\n    )\n\n\ndef search_games(\n    game_name: str,\n) -> pd.DataFrame:\n    \"\"\"\n    Search the IGDB games endpoint and return the candidates as a DataFrame.\n    \"\"\"\n    query = build_query_game_search(\n        game_name\n    )\n\n    response = post_igdb(\n        cf.GAMES_URL,\n        query,\n    )\n\n    data = response.json()\n\n    if not data:\n        return pd.DataFrame()\n\n    return pd.DataFrame(\n        data\n    )\n\n\ndef select_exact_normalized_match(\n    candidates: pd.DataFrame,\n    normalized_title: str,\n):\n    \"\"\"\n    Return the first candidate whose IGDB name normalizes exactly to the\n    unified normalized title.\n\n    The function also returns the number of exact candidates found.\n    \"\"\"\n    if candidates.empty:\n        return None, 0\n\n    if \"name\" not in candidates.columns:\n        return None, 0\n\n    candidates = candidates.copy()\n\n    candidates[\"_normalized_igdb_name\"] = (\n        candidates[\"name\"]\n        .map(normalize_for_match)\n    )\n\n    exact = candidates[\n        candidates[\"_normalized_igdb_name\"].eq(\n            normalized_title\n        )\n    ]\n\n    if exact.empty:\n        return None, 0\n\n    return exact.iloc[0], len(exact)\n\n\n# ---------------------------------------------------------------------------\n# Workflow 1:\n# Match genres for all normalized games\n# ---------------------------------------------------------------------------\n\ndef build_unique_normalized_games(\n    unified_csv: str = UNIFIED_GAMES_CSV,\n) -> pd.DataFrame:\n    \"\"\"\n    Build one row per normalized title across ALL sources.\n\n    The output retains:\n        - one representative original title\n        - all source names containing that normalized title\n        - source row count\n    \"\"\"\n    df = pd.read_csv(\n        unified_csv,\n        low_memory=False,\n    )\n\n    required_columns = {\n        \"normalized_title\",\n        \"game_name\",\n        \"source\",\n    }\n\n    missing = (\n        required_columns\n        - set(df.columns)\n    )\n\n    if missing:\n        raise ValueError(\n            \"Unified CSV is missing required columns: \"\n            + \", \".join(sorted(missing))\n        )\n\n    df[\"normalized_title\"] = (\n        df[\"normalized_title\"]\n        .fillna(\"\")\n        .astype(str)\n        .str.strip()\n    )\n\n    df = df[\n        df[\"normalized_title\"].ne(\"\")\n    ].copy()\n\n    grouped = (\n        df.groupby(\n            \"normalized_title\",\n            as_index=False,\n        )\n        .agg(\n            representative_game_name=(\n                \"game_name\",\n                first_valid_text,\n            ),\n            sources=(\n                \"source\",\n                lambda values: \"|\".join(\n                    sorted(\n                        set(\n                            str(value)\n                            for value in values\n                            if pd.notna(value)\n                        )\n                    )\n                ),\n            ),\n            source_row_count=(\n                \"source\",\n                \"size\",\n            ),\n        )\n    )\n\n    return grouped\n\n\ndef match_genres_for_normalized_games(\n    unified_csv: str = UNIFIED_GAMES_CSV,\n    genres_csv: str = GENRES_CSV,\n    output_csv: str = GENRE_OUTPUT_CSV,\n) -> pd.DataFrame:\n    \"\"\"\n    Match every unique normalized title from ALL unified sources to IGDB.\n\n    Fault tolerance\n    ---------------\n    - Missing/malformed game names are converted to safe strings.\n    - If the representative name is missing, normalized_title is used.\n    - Each game is processed inside its own try/except block.\n    - Errors are recorded as rows with match_status='error'.\n    - Every completed/error row is appended to the CSV immediately, so\n      partial results survive later failures.\n\n    Matching strategy\n    -----------------\n    1. Query IGDB using a representative original game name.\n    2. Normalize IGDB candidate names.\n    3. Accept a genre assignment only when an IGDB candidate normalizes\n       exactly to the unified `normalized_title`.\n    4. If no exact candidate is found, retry using the normalized title.\n    5. If the retry still has no exact candidate, retain candidate names for\n       manual inspection but DO NOT assign genres.\n\n    Output\n    ------\n    One row per normalized title with:\n        normalized_title\n        representative_game_name\n        sources\n        source_row_count\n        igdb_id\n        igdb_name\n        first_release_year\n        genre_ids\n        genres\n        match_status\n        search_candidate_count\n        exact_candidate_count\n        search_used\n        candidate_names\n        error_type\n        error_message\n    \"\"\"\n    unique_games = build_unique_normalized_games(\n        unified_csv\n    )\n\n    genre_mapping = load_genre_mapping(\n        genres_csv\n    )\n\n    # Start a clean output file for this run.\n    if os.path.exists(output_csv):\n        os.remove(output_csv)\n\n    rows = []\n    total = len(unique_games)\n\n    for index, game in unique_games.iterrows():\n        normalized_title = safe_text(\n            game.get(\"normalized_title\", \"\")\n        )\n\n        representative_name = safe_text(\n            game.get(\"representative_game_name\", \"\"),\n            fallback=normalized_title,\n        )\n\n        sources = safe_text(\n            game.get(\"sources\", \"\")\n        )\n\n        source_row_count = game.get(\n            \"source_row_count\",\n            pd.NA,\n        )\n\n        print(\n            f\"[{index + 1}/{total}] \"\n            f\"Searching IGDB: {representative_name}\"\n        )\n\n        # Define a complete fallback row first.\n        # If anything fails, this row is written instead of stopping the run.\n        result_row = {\n            \"normalized_title\": normalized_title,\n            \"representative_game_name\": representative_name,\n            \"sources\": sources,\n            \"source_row_count\": source_row_count,\n            \"igdb_id\": pd.NA,\n            \"igdb_name\": pd.NA,\n            \"first_release_year\": pd.NA,\n            \"genre_ids\": \"\",\n            \"genres\": \"\",\n            \"match_status\": \"error\",\n            \"search_candidate_count\": 0,\n            \"exact_candidate_count\": 0,\n            \"search_used\": \"\",\n            \"candidate_names\": \"\",\n            \"error_type\": \"\",\n            \"error_message\": \"\",\n        }\n\n        try:\n            # If both values are somehow empty, record the malformed entry.\n            if not representative_name:\n                raise ValueError(\n                    \"No usable representative game name or normalized title.\"\n                )\n\n            candidates = search_games(\n                representative_name\n            )\n\n            match, exact_count = (\n                select_exact_normalized_match(\n                    candidates,\n                    normalized_title,\n                )\n            )\n\n            search_used = representative_name\n\n            # Retry with normalized_title when useful.\n            if (\n                match is None\n                and normalized_title\n                and normalize_for_match(\n                    representative_name\n                ) != normalized_title\n            ):\n                retry_candidates = search_games(\n                    normalized_title\n                )\n\n                if not retry_candidates.empty:\n                    if not candidates.empty:\n                        candidates = pd.concat(\n                            [\n                                candidates,\n                                retry_candidates,\n                            ],\n                            ignore_index=True,\n                        )\n\n                        if \"id\" in candidates.columns:\n                            candidates = (\n                                candidates\n                                .drop_duplicates(\n                                    subset=[\"id\"],\n                                    keep=\"first\",\n                                )\n                            )\n                    else:\n                        candidates = retry_candidates\n\n                match, exact_count = (\n                    select_exact_normalized_match(\n                        candidates,\n                        normalized_title,\n                    )\n                )\n\n                # safe_text guarantees string operands here.\n                search_used = (\n                    safe_text(representative_name)\n                    + \" | retry: \"\n                    + safe_text(normalized_title)\n                )\n\n            candidate_names = \"\"\n\n            if (\n                not candidates.empty\n                and \"name\" in candidates.columns\n            ):\n                candidate_names = \" | \".join(\n                    candidates[\"name\"]\n                    .dropna()\n                    .map(safe_text)\n                    .loc[lambda s: s.ne(\"\")]\n                    .drop_duplicates()\n                    .tolist()\n                )\n\n            if match is None:\n                result_row.update(\n                    {\n                        \"match_status\": (\n                            \"no_candidates\"\n                            if candidates.empty\n                            else \"no_exact_normalized_match\"\n                        ),\n                        \"search_candidate_count\": len(\n                            candidates\n                        ),\n                        \"exact_candidate_count\": 0,\n                        \"search_used\": safe_text(\n                            search_used\n                        ),\n                        \"candidate_names\": candidate_names,\n                    }\n                )\n\n            else:\n                genre_ids = parse_id_list(\n                    match.get(\n                        \"genres\",\n                        [],\n                    )\n                )\n\n                genre_names = genre_ids_to_names(\n                    genre_ids,\n                    genre_mapping,\n                )\n\n                release_timestamp = match.get(\n                    \"first_release_date\",\n                    pd.NA,\n                )\n\n                first_release_year = pd.NA\n\n                if pd.notna(release_timestamp):\n                    try:\n                        first_release_year = (\n                            pd.to_datetime(\n                                int(release_timestamp),\n                                unit=\"s\",\n                                utc=True,\n                            ).year\n                        )\n                    except (\n                        TypeError,\n                        ValueError,\n                        OverflowError,\n                    ):\n                        # Malformed release dates should not invalidate\n                        # an otherwise valid title/genre match.\n                        first_release_year = pd.NA\n\n                result_row.update(\n                    {\n                        \"igdb_id\": match.get(\n                            \"id\",\n                            pd.NA,\n                        ),\n                        \"igdb_name\": safe_text(\n                            match.get(\n                                \"name\",\n                                pd.NA,\n                            )\n                        ),\n                        \"first_release_year\": (\n                            first_release_year\n                        ),\n                        \"genre_ids\": \"|\".join(\n                            str(value)\n                            for value in genre_ids\n                        ),\n                        \"genres\": \"|\".join(\n                            safe_text(value)\n                            for value in genre_names\n                            if safe_text(value)\n                        ),\n                        \"match_status\": (\n                            \"exact_normalized_match\"\n                        ),\n                        \"search_candidate_count\": len(\n                            candidates\n                        ),\n                        \"exact_candidate_count\": exact_count,\n                        \"search_used\": safe_text(\n                            search_used\n                        ),\n                        \"candidate_names\": candidate_names,\n                    }\n                )\n\n        except Exception as exc:\n            # Do not stop the complete mining process for one malformed row\n            # or one failed request.\n            result_row.update(\n                {\n                    \"match_status\": \"error\",\n                    \"error_type\": type(exc).__name__,\n                    \"error_message\": safe_text(exc),\n                }\n            )\n\n            print(\n                f\"  ERROR for '{representative_name}': \"\n                f\"{type(exc).__name__}: {exc}\"\n            )\n\n        # Keep the in-memory result.\n        rows.append(\n            result_row\n        )\n\n        # And checkpoint immediately to disk.\n        write_genre_result_row(\n            result_row,\n            output_csv,\n        )\n\n    result = pd.DataFrame(\n        rows\n    )\n\n    # Re-write once at the end to guarantee stable column order.\n    result.to_csv(\n        output_csv,\n        index=False,\n        encoding=\"utf-8\",\n    )\n\n    print(\n        f\"\\nSaved {len(result)} normalized-game \"\n        f\"genre records to {output_csv}\"\n    )\n\n    print(\"\\nMatch status:\")\n    print(\n        result[\"match_status\"]\n        .value_counts(\n            dropna=False\n        )\n        .to_string()\n    )\n\n    error_count = int(\n        result[\"match_status\"]\n        .eq(\"error\")\n        .sum()\n    )\n\n    print(\n        f\"\\nRows completed with recoverable errors: \"\n        f\"{error_count}\"\n    )\n\n    return result\n\n\n# ---------------------------------------------------------------------------\n# Workflow 2:\n# Count IGDB game releases by year\n# ---------------------------------------------------------------------------\n\ndef year_to_unix_timestamp(\n    year: int,\n) -> int:\n    \"\"\"\n    Convert January 1 of a year to an IGDB-compatible Unix timestamp.\n    \"\"\"\n    timestamp = pd.Timestamp(\n        year=year,\n        month=1,\n        day=1,\n        tz=\"UTC\",\n    )\n\n    return int(\n        timestamp.timestamp()\n    )\n\n\ndef build_query_games_for_year(\n    year: int,\n    offset: int = 0,\n    limit: int = IGDB_PAGE_SIZE,\n) -> str:\n    \"\"\"\n    Query game IDs whose first_release_date falls inside one calendar year.\n    \"\"\"\n    start_timestamp = (\n        year_to_unix_timestamp(\n            year\n        )\n    )\n\n    end_timestamp = (\n        year_to_unix_timestamp(\n            year + 1\n        )\n    )\n\n    return (\n        \"fields id; \"\n        \"where \"\n        f\"first_release_date >= {start_timestamp} \"\n        \"& \"\n        f\"first_release_date < {end_timestamp} \"\n        \"& \"\n        \"game_type = (\"\n        + \",\".join(str(type_id) for type_id in RELEASE_GAME_TYPE_IDS)\n        + \"); \"\n        \"sort id asc; \"\n        f\"limit {limit}; \"\n        f\"offset {offset};\"\n    )\n\n\ndef get_game_ids_released_in_year(\n    year: int,\n) -> set[int]:\n    \"\"\"\n    Fetch all IGDB game IDs released in the requested year.\n\n    Pagination uses the games endpoint and a maximum page size of 500.\n    \"\"\"\n    game_ids = set()\n\n    offset = 0\n\n    while True:\n        query = build_query_games_for_year(\n            year=year,\n            offset=offset,\n            limit=IGDB_PAGE_SIZE,\n        )\n\n        response = post_igdb(\n            cf.GAMES_URL,\n            query,\n        )\n\n        data = response.json()\n\n        if not data:\n            break\n\n        for record in data:\n            game_id = record.get(\n                \"id\"\n            )\n\n            if game_id is not None:\n                game_ids.add(\n                    int(game_id)\n                )\n\n        batch_size = len(data)\n\n        print(\n            f\"  {year}: offset={offset}, \"\n            f\"received={batch_size}, \"\n            f\"unique_total={len(game_ids)}\"\n        )\n\n        if batch_size < IGDB_PAGE_SIZE:\n            break\n\n        offset += IGDB_PAGE_SIZE\n\n    return game_ids\n\n\ndef compute_games_released_by_year(\n    start_year: int,\n    end_year: int,\n    output_csv: str = YEAR_OUTPUT_CSV,\n) -> pd.DataFrame:\n    \"\"\"\n    Count IGDB games by first-release year.\n\n    Parameters\n    ----------\n    start_year:\n        First calendar year to include.\n\n    end_year:\n        Last calendar year to include, inclusive.\n\n    output_csv:\n        Destination CSV.\n\n    Output columns\n    --------------\n    year\n        Calendar year.\n\n    igdb_games_released\n        Number of unique IGDB game IDs whose first_release_date falls in\n        that year.\n\n    Notes\n    -----\n    This provides a release-volume denominator. It should not automatically\n    be interpreted as the number of games actively available in that year.\n    \"\"\"\n    if start_year > end_year:\n        raise ValueError(\n            \"start_year must be <= end_year\"\n        )\n\n    rows = []\n\n    for year in range(\n        start_year,\n        end_year + 1,\n    ):\n        print(\n            f\"\\nCounting IGDB releases for {year}\"\n        )\n\n        game_ids = (\n            get_game_ids_released_in_year(\n                year\n            )\n        )\n\n        rows.append(\n            {\n                \"year\": year,\n                \"igdb_games_released\": len(\n                    game_ids\n                ),\n            }\n        )\n\n    result = pd.DataFrame(\n        rows\n    )\n\n    result.to_csv(\n        output_csv,\n        index=False,\n        encoding=\"utf-8\",\n    )\n\n    print(\n        f\"\\nSaved yearly IGDB release counts \"\n        f\"to {output_csv}\"\n    )\n\n    return result\n\n\n# ---------------------------------------------------------------------------\n# Optional helper:\n# derive the event-year interval from the unified dataset\n# ---------------------------------------------------------------------------\n\ndef get_historical_event_year_range(\n    unified_csv: str = UNIFIED_GAMES_CSV,\n) -> tuple[int, int]:\n    \"\"\"\n    Return the min/max historical event year present in the unified dataset.\n\n    Future years are excluded.\n\n    This helper can be used to choose the same year interval for the IGDB\n    release-count denominator and the historical delisting analysis.\n    \"\"\"\n    df = pd.read_csv(\n        unified_csv,\n        low_memory=False,\n    )\n\n    if \"event_year\" not in df.columns:\n        raise ValueError(\n            \"Unified CSV does not contain event_year.\"\n        )\n\n    years = pd.to_numeric(\n        df[\"event_year\"],\n        errors=\"coerce\",\n    )\n\n    current_year = (\n        pd.Timestamp.utcnow().year\n    )\n\n    years = years[\n        years.notna()\n        & years.le(current_year)\n    ]\n\n    if years.empty:\n        raise ValueError(\n            \"No historical event years were found.\"\n        )\n\n    return (\n        int(years.min()),\n        int(years.max()),\n    )\n\n\n# ---------------------------------------------------------------------------\n# Example execution\n# ---------------------------------------------------------------------------\n\nif __name__ == \"__main__\":\n\n    # ---------------------------------------------------------------\n    # 1. Genre enrichment for every normalized title across all sources\n    # ---------------------------------------------------------------\n\n    match_genres_for_normalized_games(\n        unified_csv=UNIFIED_GAMES_CSV,\n        genres_csv=GENRES_CSV,\n        output_csv=GENRE_OUTPUT_CSV,\n    )\n\n    # ---------------------------------------------------------------\n    # 2. Number of IGDB games released per year\n    #\n    # Use the historical event-year interval already present in the\n    # unified dataset. If you prefer a fixed interval, replace these\n    # two values manually.\n    # ---------------------------------------------------------------\n\n    start_year, end_year = (\n        get_historical_event_year_range(\n            UNIFIED_GAMES_CSV\n        )\n    )\n\n    compute_games_released_by_year(\n        start_year=start_year,\n        end_year=end_year,\n        output_csv=YEAR_OUTPUT_CSV,\n    )\n"},{"path":"RQ2_package/export_doesitplay_overlaps.py","group":"RQ2_package","text":"#!/usr/bin/env python3\n\n\"\"\"\nExport title-overlap datasets between DoesItPlay and each outcome source.\n\nThe script reads the unified CSV generated by the aggregation pipeline and\ncreates three manual-review datasets:\n\n    - DoesItPlay x Steam Tracker\n    - DoesItPlay x Delisted Games\n    - DoesItPlay x Dead Game List\n\nOnly outcome-source rows flagged `is_historically_unavailable` are used, so\n\"At Risk\" games that are still running are excluded.\n\nMatching is intentionally conservative: rows are joined only when\n`normalized_title` is exactly equal. The exports preserve the original title\nfrom both sources and source-specific/raw fields so that each match can be\nmanually validated.\n\nThe output includes blank `manual_match` and `manual_notes` columns to support\nhuman review.\n\nExpected input:\n    ../Analysis/unified_games.csv\n\nOutputs:\n    ./\n        overlap_doesitplay_steam_tracker.csv\n        overlap_doesitplay_delisted_games.csv\n        overlap_doesitplay_dead_game_list.csv\n        overlap_export_summary.csv\n\"\"\"\n\nimport logging\nfrom pathlib import Path\n\nimport pandas as pd\n\n\n# ---------------------------------------------------------------------------\n# Configuration\n# ---------------------------------------------------------------------------\n\nBASE_DIR = Path(__file__).resolve().parent\n\nUNIFIED_CSV = (\n    BASE_DIR.parent\n    / \"Analysis\"\n    / \"unified_games.csv\"\n)\n\nOUTPUT_DIR = BASE_DIR\n\nTARGET_SOURCES = {\n    \"steam_tracker\": \"overlap_doesitplay_steam_tracker.csv\",\n    \"delisted_games\": \"overlap_doesitplay_delisted_games.csv\",\n    \"dead_game_list\": \"overlap_doesitplay_dead_game_list.csv\",\n}\n\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format=\"%(asctime)s - %(levelname)s - %(message)s\",\n)\n\nlogger = logging.getLogger(__name__)\n\n\n# ---------------------------------------------------------------------------\n# Helpers\n# ---------------------------------------------------------------------------\n\ndef load_unified_csv(path: Path) -> pd.DataFrame:\n    \"\"\"\n    Load and minimally validate the unified CSV.\n    \"\"\"\n    logger.info(\"Loading unified dataset: %s\", path)\n\n    df = pd.read_csv(\n        path,\n        low_memory=False,\n    )\n\n    required_columns = {\n        \"source\",\n        \"source_record_id\",\n        \"game_name\",\n        \"normalized_title\",\n    }\n\n    missing = required_columns - set(df.columns)\n\n    if missing:\n        raise ValueError(\n            \"Unified CSV is missing required columns: \"\n            + \", \".join(sorted(missing))\n        )\n\n    # Empty normalized titles cannot be matched meaningfully.\n    df[\"normalized_title\"] = (\n        df[\"normalized_title\"]\n        .fillna(\"\")\n        .astype(str)\n        .str.strip()\n    )\n\n    return df\n\n\ndef existing_columns(\n    df: pd.DataFrame,\n    columns: list[str],\n) -> list[str]:\n    \"\"\"\n    Return only columns that actually exist in the dataframe.\n    \"\"\"\n    return [\n        column\n        for column in columns\n        if column in df.columns\n    ]\n\n\ndef raw_columns_for_source(\n    df: pd.DataFrame,\n    source_name: str,\n) -> list[str]:\n    \"\"\"\n    Return raw source-specific columns for one source.\n    \"\"\"\n    prefix_map = {\n        \"steam_tracker\": [\n            \"raw__steamtracker__\",\n        ],\n        \"delisted_games\": [\n            \"raw__delistedgames__\",\n        ],\n        \"dead_game_list\": [\n            \"raw__deadgamelist__\",\n        ],\n        \"doesitplay\": [\n            \"raw__doesitplay__\",\n        ],\n    }\n\n    prefixes = prefix_map[source_name]\n\n    return [\n        column\n        for column in df.columns\n        if any(\n            column.startswith(prefix)\n            for prefix in prefixes\n        )\n    ]\n\n\ndef prepare_source_side(\n    df: pd.DataFrame,\n    source_name: str,\n) -> pd.DataFrame:\n    \"\"\"\n    Select canonical and raw fields for one non-DoesItPlay source.\n\n    All fields except normalized_title are renamed with a `source_` prefix\n    so that the resulting review CSV is easy to inspect.\n    \"\"\"\n    canonical_columns = [\n        \"normalized_title\",\n        \"source_record_id\",\n        \"game_name\",\n        \"publisher\",\n        \"developer\",\n        \"platforms\",\n        \"release_info\",\n        \"event_info\",\n        \"release_year\",\n        \"event_year\",\n        \"source_status\",\n        \"is_explicitly_delisted\",\n        \"is_historically_unavailable\",\n        \"is_dead\",\n        \"is_at_risk\",\n    ]\n\n    columns = existing_columns(\n        df,\n        canonical_columns,\n    )\n\n    columns += raw_columns_for_source(\n        df,\n        source_name,\n    )\n\n    # Keep only games that are already unavailable (e.g. drop \"At Risk\"\n    # Dead Game List entries), matching the historical event analysis.\n    source_df = (\n        df.loc[\n            df[\"source\"].eq(source_name)\n            & df[\"normalized_title\"].ne(\"\")\n            & df[\"is_historically_unavailable\"].eq(True),\n            columns,\n        ]\n        .copy()\n    )\n\n    rename_map = {\n        column: f\"source_{column}\"\n        for column in source_df.columns\n        if column != \"normalized_title\"\n    }\n\n    source_df = source_df.rename(\n        columns=rename_map\n    )\n\n    return source_df\n\n\ndef prepare_doesitplay_side(\n    df: pd.DataFrame,\n) -> pd.DataFrame:\n    \"\"\"\n    Select canonical and raw DoesItPlay fields for manual comparison.\n    \"\"\"\n    canonical_columns = [\n        \"normalized_title\",\n        \"source_record_id\",\n        \"game_name\",\n        \"platforms\",\n        \"source_status\",\n        \"offline_play\",\n        \"offline_play_bool\",\n        \"download_required\",\n        \"download_required_bool\",\n    ]\n\n    columns = existing_columns(\n        df,\n        canonical_columns,\n    )\n\n    columns += raw_columns_for_source(\n        df,\n        \"doesitplay\",\n    )\n\n    doesitplay_df = (\n        df.loc[\n            df[\"source\"].eq(\"doesitplay\")\n            & df[\"normalized_title\"].ne(\"\"),\n            columns,\n        ]\n        .copy()\n    )\n\n    rename_map = {\n        column: f\"doesitplay_{column}\"\n        for column in doesitplay_df.columns\n        if column != \"normalized_title\"\n    }\n\n    doesitplay_df = doesitplay_df.rename(\n        columns=rename_map\n    )\n\n    return doesitplay_df\n\n\ndef export_overlap(\n    unified: pd.DataFrame,\n    source_name: str,\n    doesitplay_df: pd.DataFrame,\n    output_file: Path,\n) -> dict:\n    \"\"\"\n    Export all exact normalized-title matches between one source and DoesItPlay.\n\n    Multiple rows are deliberately preserved. For example, a single game can\n    have more than one DoesItPlay test because platform, version, region, or\n    tested hardware differs.\n    \"\"\"\n    source_df = prepare_source_side(\n        unified,\n        source_name,\n    )\n\n    overlap = source_df.merge(\n        doesitplay_df,\n        on=\"normalized_title\",\n        how=\"inner\",\n        validate=\"many_to_many\",\n    )\n\n    overlap.insert(\n        0,\n        \"matched_source\",\n        source_name,\n    )\n\n    overlap.insert(\n        1,\n        \"match_type\",\n        \"exact_normalized_title\",\n    )\n\n    # Blank fields intentionally included for manual checking.\n    overlap.insert(\n        2,\n        \"manual_match\",\n        \"\",\n    )\n\n    overlap.insert(\n        3,\n        \"manual_notes\",\n        \"\",\n    )\n\n    sort_columns = existing_columns(\n        overlap,\n        [\n            \"normalized_title\",\n            \"source_source_record_id\",\n            \"doesitplay_source_record_id\",\n        ],\n    )\n\n    if sort_columns:\n        overlap = overlap.sort_values(\n            sort_columns,\n            kind=\"stable\",\n        )\n\n    overlap = overlap.reset_index(\n        drop=True,\n    )\n\n    output_file.parent.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    overlap.to_csv(\n        output_file,\n        index=False,\n    )\n\n    unique_titles = (\n        overlap[\"normalized_title\"].nunique()\n        if not overlap.empty\n        else 0\n    )\n\n    logger.info(\n        \"%s x DoesItPlay: %d review rows, %d unique matched titles -> %s\",\n        source_name,\n        len(overlap),\n        unique_titles,\n        output_file,\n    )\n\n    return {\n        \"source\": source_name,\n        \"review_rows\": int(len(overlap)),\n        \"unique_matched_titles\": int(unique_titles),\n        \"output_file\": output_file.name,\n    }\n\n\n# ---------------------------------------------------------------------------\n# Main\n# ---------------------------------------------------------------------------\n\ndef main():\n    unified = load_unified_csv(\n        UNIFIED_CSV\n    )\n\n    doesitplay_df = prepare_doesitplay_side(\n        unified\n    )\n\n    if doesitplay_df.empty:\n        raise RuntimeError(\n            \"No DoesItPlay rows found in the unified dataset.\"\n        )\n\n    summary_rows = []\n\n    for source_name, filename in TARGET_SOURCES.items():\n        if not unified[\"source\"].eq(source_name).any():\n            raise RuntimeError(\n                f\"No rows found for source '{source_name}'.\"\n            )\n\n        summary = export_overlap(\n            unified=unified,\n            source_name=source_name,\n            doesitplay_df=doesitplay_df,\n            output_file=OUTPUT_DIR / filename,\n        )\n\n        summary_rows.append(\n            summary\n        )\n\n    summary_df = pd.DataFrame(\n        summary_rows\n    )\n\n    summary_path = (\n        OUTPUT_DIR\n        / \"overlap_export_summary.csv\"\n    )\n\n    summary_df.to_csv(\n        summary_path,\n        index=False,\n    )\n\n    print(\"\\n=== DOESITPLAY OVERLAP EXPORT SUMMARY ===\")\n    print(\n        summary_df.to_string(\n            index=False\n        )\n    )\n\n    print(\"\\nFiles written:\")\n    for filename in TARGET_SOURCES.values():\n        print(f\"  - {OUTPUT_DIR / filename}\")\n\n    print(f\"  - {summary_path}\")\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"RQ3_package/figure_style.py","group":"RQ3_package","text":"import textwrap\n\nimport matplotlib.pyplot as plt\nfrom matplotlib.ticker import MaxNLocator, MultipleLocator, StrMethodFormatter\n\nSHOW_TITLES = False\n\nSINGLE_COLUMN = 3.5\nDOUBLE_COLUMN = 7.16\nLINE_HEIGHT = 2.8\n\nWIDE_MARGINS = {\"left\": 0.62, \"right\": 0.62, \"bottom\": 0.42, \"top\": 0.16}\nTITLE_SPACE = 0.3\n\nBAR_THICKNESS = 0.62\nBAR_ROW_HEIGHT = 0.3\n\nINK = \"#1f1f1f\"\nMUTED = \"#5c5c5c\"\nGRID = \"#e5e5e5\"\n\nSOURCE_STYLE = {\n    \"steam_tracker\": {\"label\": \"Steam Tracker\", \"color\": \"#2a78d6\", \"marker\": \"o\"},\n    \"delisted_games\": {\"label\": \"Delisted Games\", \"color\": \"#eb6834\", \"marker\": \"s\"},\n    \"dead_game_list\": {\"label\": \"Dead Game List\", \"color\": \"#199e70\", \"marker\": \"^\"},\n    \"doesitplay\": {\"label\": \"DoesItPlay\", \"color\": \"#4a3aa7\", \"marker\": \"D\"},\n}\n\nCAUSE_STYLE = {\n    \"licensing\": {\"label\": \"Licensing\", \"color\": \"#2a78d6\", \"marker\": \"o\"},\n    \"ip_change\": {\"label\": \"IP change\", \"color\": \"#eb6834\", \"marker\": \"s\"},\n    \"server\": {\"label\": \"Service shut down\", \"color\": \"#1baf7a\", \"marker\": \"^\"},\n    \"store_closure\": {\"label\": \"Store closure\", \"color\": \"#eda100\", \"marker\": \"D\"},\n    \"publisher_exit\": {\"label\": \"Publisher exit\", \"color\": \"#e87ba4\", \"marker\": \"v\"},\n    \"other\": {\"label\": \"Other reason\", \"color\": \"#8a8a8a\", \"marker\": \"x\"},\n    \"not_stated\": {\"label\": \"Not stated\", \"color\": \"#b5b5b5\", \"marker\": \"+\"},\n}\n\nTOTAL_STYLE = {\"color\": INK, \"marker\": \"o\"}\nIGDB_STYLE = {\"color\": \"#8a8a8a\", \"marker\": \"s\", \"linestyle\": (0, (4, 2))}\n\n\ndef apply_style():\n    plt.rcParams.update({\n        \"font.family\": \"STIXGeneral\",\n        \"mathtext.fontset\": \"stix\",\n        \"font.size\": 8.5,\n        \"axes.titlesize\": 9.5,\n        \"axes.titlelocation\": \"left\",\n        \"axes.titlepad\": 8,\n        \"axes.labelsize\": 8.5,\n        \"axes.labelpad\": 4,\n        \"xtick.labelsize\": 8,\n        \"ytick.labelsize\": 8,\n        \"legend.fontsize\": 8,\n        \"text.color\": INK,\n        \"axes.labelcolor\": INK,\n        \"axes.edgecolor\": MUTED,\n        \"axes.linewidth\": 0.6,\n        \"axes.spines.top\": False,\n        \"axes.spines.right\": False,\n        \"axes.grid\": True,\n        \"axes.grid.axis\": \"y\",\n        \"axes.axisbelow\": True,\n        \"grid.color\": GRID,\n        \"grid.linewidth\": 0.6,\n        \"xtick.color\": MUTED,\n        \"ytick.color\": MUTED,\n        \"xtick.labelcolor\": INK,\n        \"ytick.labelcolor\": INK,\n        \"xtick.major.size\": 3,\n        \"xtick.major.width\": 0.6,\n        \"xtick.minor.size\": 1.5,\n        \"xtick.minor.width\": 0.5,\n        \"ytick.major.size\": 0,\n        \"ytick.major.pad\": 4,\n        \"lines.linewidth\": 1.4,\n        \"lines.markersize\": 3.5,\n        \"legend.frameon\": False,\n        \"legend.handlelength\": 2.2,\n        \"legend.borderaxespad\": 0.2,\n        \"figure.dpi\": 150,\n        \"savefig.dpi\": 300,\n        \"savefig.bbox\": None,\n        \"savefig.facecolor\": \"white\",\n        \"pdf.fonttype\": 42,\n        \"ps.fonttype\": 42,\n    })\n\n\ndef source_label(source: str, wrap: int = None) -> str:\n    label = SOURCE_STYLE.get(source, {}).get(\"label\", source)\n    return \"\\n\".join(textwrap.wrap(label, wrap)) if wrap else label\n\n\ndef set_title(ax, title: str):\n    if not SHOW_TITLES:\n        return\n    width = int(ax.figure.get_figwidth() * 13)\n    ax.set_title(\"\\n\".join(textwrap.wrap(title, width)))\n\n\ndef wide_figure():\n    fig = plt.figure(figsize=(DOUBLE_COLUMN, LINE_HEIGHT))\n    m = WIDE_MARGINS\n    top = m[\"top\"] + (TITLE_SPACE if SHOW_TITLES else 0)\n    w, h = DOUBLE_COLUMN, LINE_HEIGHT\n    ax = fig.add_axes([\n        m[\"left\"] / w,\n        m[\"bottom\"] / h,\n        1 - (m[\"left\"] + m[\"right\"]) / w,\n        1 - (m[\"bottom\"] + top) / h,\n    ])\n    return fig, ax\n\n\ndef style_count_axis(ax):\n    locator = MaxNLocator(nbins=5, integer=True)\n    top = ax.dataLim.y1\n    ax.set_ylim(0, max(t for t in locator.tick_values(0, top) if t >= top))\n    ax.yaxis.set_major_locator(locator)\n    ax.yaxis.set_major_formatter(StrMethodFormatter(\"{x:,.0f}\"))\n\n\ndef style_year_axis(ax, years):\n    ax.set_xlim(min(years) - 0.5, max(years) + 0.5)\n    ax.xaxis.set_major_locator(MultipleLocator(5))\n    ax.xaxis.set_minor_locator(MultipleLocator(1))\n    ax.xaxis.set_major_formatter(StrMethodFormatter(\"{x:.0f}\"))\n\n\ndef plot_bars(labels, values, colors, title, value_label=None, value_format=\"{:,}\".format):\n    rows = sorted(\n        zip(labels, values, colors if isinstance(colors, list) else [colors] * len(labels)),\n        key=lambda row: row[1],\n    )\n    labels, values, colors = zip(*rows)\n\n    height = 0.55 + BAR_ROW_HEIGHT * len(labels) + (TITLE_SPACE if SHOW_TITLES else 0)\n    fig, ax = plt.subplots(figsize=(SINGLE_COLUMN, height))\n    ax.barh(labels, values, height=BAR_THICKNESS, color=colors, zorder=2)\n\n    largest = max(values)\n    for i, value in enumerate(values):\n        ax.text(\n            value + largest * 0.015, i, value_format(value),\n            va=\"center\", ha=\"left\",\n            fontsize=plt.rcParams[\"xtick.labelsize\"], color=INK,\n        )\n\n    ax.set_xlim(0, largest * 1.14)\n    ax.set_xticks([])\n    ax.grid(False)\n    ax.spines[\"bottom\"].set_visible(False)\n    ax.spines[\"left\"].set_color(INK)\n    ax.tick_params(axis=\"y\", length=0, pad=5)\n    if value_label:\n        ax.set_xlabel(value_label)\n    set_title(ax, title)\n    fig.tight_layout(pad=0.3)\n    return fig, ax\n\n\ndef plot_source_lines(pivot, title, xlabel, ylabel, year_range):\n    fig, ax = wide_figure()\n    years = pivot.index.astype(int)\n    ordered = [s for s in SOURCE_STYLE if s in pivot.columns]\n    ordered += [s for s in pivot.columns if s not in SOURCE_STYLE]\n    for source in ordered:\n        style = SOURCE_STYLE.get(source, {})\n        ax.plot(\n            years,\n            pivot[source],\n            color=style.get(\"color\"),\n            marker=style.get(\"marker\", \"o\"),\n            markeredgecolor=\"white\",\n            markeredgewidth=0.4,\n            label=source_label(source),\n            clip_on=False,\n            zorder=3,\n        )\n    ax.set_xlabel(xlabel)\n    ax.set_ylabel(ylabel)\n    style_year_axis(ax, year_range)\n    style_count_axis(ax)\n    ax.legend(loc=\"upper left\")\n    set_title(ax, title)\n    return fig, ax\n"},{"path":"RQ3_package/historical_analysis/game_delisting_statistics_with_igdb_correlation.ipynb","group":"RQ3_package/historical_analysis","text":"# %% [markdown]\n# # Unified game delisting statistics\n#\n# This notebook analyzes the unified game dataset built from:\n#\n# - **Delisted Games**\n# - **Steam Tracker**\n# - **Dead Game List** (Stop Killing Games wiki)\n# - **DoesItPlay**\n#\n# ## Main analyses\n#\n# 1. **Time evolution** of removal/delisting-like events by year, compared with IGDB release volume.\n# 2. The same yearly analysis restricted to games that **overlap with DoesItPlay**.\n# 3. Additional descriptive statistics for DoesItPlay offline-play and download-dependency information.\n#\n# ### Event definition\n#\n# The unified dataset already contains the field `is_historically_unavailable`.  \n# This notebook treats rows where that field is `True` as a comparable **historical event-like subset**:\n#\n# - Delisted Games → historically delisted records.\n# - Steam Tracker → delisted / purchase-disabled / unavailable-like records according to the aggregation pipeline.\n# - Dead Game List → dead/preserved/resurrected historical cases.\n# - DoesItPlay → **not used as an outcome source**, because it supplies playability/dependency observations rather than delisting labels.\n#\n# `At Risk` records are therefore not counted as historical removals.\n\n# %%\nfrom pathlib import Path\n\nimport pandas as pd\nimport matplotlib.pyplot as plt\n\nfrom IPython.display import display\n\npd.set_option(\"display.max_columns\", 100)\npd.set_option(\"display.max_rows\", 100)\n\n# ---------------------------------------------------------------------\n# Configuration\n# ---------------------------------------------------------------------\n\n# Paths are relative to this notebook's directory.\nDATA_FILE = Path(\"../../Analysis/unified_games.csv\")\nIGDB_RELEASES_FILE = Path(\"../../IGDB_miner/igdb_games_released_by_year.csv\")\n\nOUTPUT_DIR = Path(\".\")\n\nCURRENT_YEAR = pd.Timestamp.now().year\n\n# Last year fully covered by the committed snapshots (mined during 2026).\n# Later years are partial and are left out of every yearly series.\nLAST_COMPLETE_YEAR = 2025\n\nprint(\"Data file:\", DATA_FILE)\nprint(\"Output directory:\", OUTPUT_DIR.resolve())\nprint(\"Last complete year in the yearly series:\", LAST_COMPLETE_YEAR)\n\n# %%\n# ---------------------------------------------------------------------\n# Figure style\n# ---------------------------------------------------------------------\n# Shared with the other RQ3 analyses: see ../figure_style.py.\n\nimport sys\nimport textwrap\n\nsys.path.insert(0, str(Path(\"..\").resolve()))\n\nfrom figure_style import (\n    IGDB_STYLE,\n    SOURCE_STYLE,\n    TOTAL_STYLE,\n    apply_style,\n    plot_bars,\n    plot_source_lines,\n    set_title,\n    source_label,\n    style_count_axis,\n    style_year_axis,\n    wide_figure,\n)\n\napply_style()\n\n# %%\n# Load the unified dataset\n\ndf = pd.read_csv(DATA_FILE, low_memory=False)\n\nprint(f\"Rows: {len(df):,}\")\nprint(f\"Columns: {len(df.columns):,}\")\nprint()\nprint(\"Rows by source:\")\ndisplay(\n    df[\"source\"]\n    .value_counts()\n    .rename_axis(\"source\")\n    .reset_index(name=\"rows\")\n)\n\n# %%\n# ---------------------------------------------------------------------\n# Helper functions\n# ---------------------------------------------------------------------\n\ndef coerce_nullable_bool(series: pd.Series) -> pd.Series:\n    \"\"\"Convert common CSV boolean representations into pandas BooleanDtype.\"\"\"\n    mapping = {\n        True: True,\n        False: False,\n        \"True\": True,\n        \"False\": False,\n        \"true\": True,\n        \"false\": False,\n        \"1\": True,\n        \"0\": False,\n        1: True,\n        0: False,\n    }\n\n    return series.map(mapping).astype(\"boolean\")\n\n\ndef save_current_figure(filename: str):\n    \"\"\"Save the active figure as PNG and as vector PDF.\"\"\"\n    path = OUTPUT_DIR / filename\n    plt.savefig(path)\n    plt.savefig(path.with_suffix(\".pdf\"))\n    print(\"Saved:\", path)\n\n\ndef count_unique_titles_by_source(data: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"Count unique normalized titles for each source.\"\"\"\n    return (\n        data.dropna(subset=[\"normalized_title\"])\n        .groupby(\"source\")[\"normalized_title\"]\n        .nunique()\n        .sort_values(ascending=False)\n        .rename(\"unique_titles\")\n        .reset_index()\n    )\n\n# %%\n# ---------------------------------------------------------------------\n# Prepare canonical analysis fields\n# ---------------------------------------------------------------------\n\nbool_columns = [\n    \"is_explicitly_delisted\",\n    \"is_historically_unavailable\",\n    \"is_dead\",\n    \"is_at_risk\",\n    \"offline_play_bool\",\n    \"download_required_bool\",\n]\n\nfor column in bool_columns:\n    if column in df.columns:\n        df[column] = coerce_nullable_bool(df[column])\n\ndf[\"event_year\"] = pd.to_numeric(\n    df[\"event_year\"],\n    errors=\"coerce\",\n).astype(\"Int64\")\n\n# Historical event-like records.\nevent_df = df[\n    df[\"is_historically_unavailable\"].fillna(False)\n].copy()\n\n# DoesItPlay is a reference/enrichment source.\ndoesitplay_df = df[\n    df[\"source\"].eq(\"doesitplay\")\n].copy()\n\ndoesitplay_titles = set(\n    doesitplay_df[\"normalized_title\"]\n    .dropna()\n    .loc[lambda s: s.ne(\"\")]\n)\n\nevent_df[\"overlaps_doesitplay\"] = (\n    event_df[\"normalized_title\"].isin(doesitplay_titles)\n)\n\noverlap_event_df = event_df[\n    event_df[\"overlaps_doesitplay\"]\n].copy()\n\n# Separate complete historical years from partial and future years.\nhistorical_event_df = event_df[\n    event_df[\"event_year\"].notna()\n    & event_df[\"event_year\"].le(LAST_COMPLETE_YEAR)\n].copy()\n\nfuture_event_df = event_df[\n    event_df[\"event_year\"].notna()\n    & event_df[\"event_year\"].gt(CURRENT_YEAR)\n].copy()\n\nhistorical_overlap_event_df = overlap_event_df[\n    overlap_event_df[\"event_year\"].notna()\n    & overlap_event_df[\"event_year\"].le(LAST_COMPLETE_YEAR)\n].copy()\n\n# Every yearly figure shares this range so their year axes line up.\nYEAR_RANGE = (\n    int(historical_event_df[\"event_year\"].min()),\n    LAST_COMPLETE_YEAR,\n)\n\nprint(f\"Historical event-like rows: {len(event_df):,}\")\nprint(\n    \"Unique historical event-like titles:\",\n    f\"{event_df['normalized_title'].nunique():,}\",\n)\nprint(\n    \"Unique DoesItPlay titles:\",\n    f\"{doesitplay_df['normalized_title'].nunique():,}\",\n)\nprint(\n    \"Event-like titles overlapping DoesItPlay:\",\n    f\"{overlap_event_df['normalized_title'].nunique():,}\",\n)\n\n# %% [markdown]\n# ## 1. Dataset overview\n#\n# The first plot shows the number of **unique normalized game titles** represented by each source.  \n# This is preferable to raw row counts because DoesItPlay may contain multiple tests for the same game across platform/version/hardware combinations.\n\n# %%\nsource_title_counts = count_unique_titles_by_source(df)\n\ndisplay(source_title_counts)\n\nplot_bars(\n    [source_label(s) for s in source_title_counts[\"source\"]],\n    source_title_counts[\"unique_titles\"],\n    [SOURCE_STYLE[s][\"color\"] for s in source_title_counts[\"source\"]],\n    title=\"Unique game titles by source\",\n    value_label=\"Unique normalized titles\",\n)\n\nsave_current_figure(\"01_unique_titles_by_source.png\")\nplt.show()\n\n# %% [markdown]\n# ## 2. Historical event-like games by source\n#\n# This plot counts unique titles marked as historically unavailable/dead/delisted-like by the unified pipeline.\n#\n# DoesItPlay does not appear here because it is not used as an outcome source.\n\n# %%\nevent_source_counts = count_unique_titles_by_source(event_df)\n\ndisplay(event_source_counts)\n\nplot_bars(\n    [source_label(s) for s in event_source_counts[\"source\"]],\n    event_source_counts[\"unique_titles\"],\n    [SOURCE_STYLE[s][\"color\"] for s in event_source_counts[\"source\"]],\n    title=\"Historical delisting / unavailability-like titles by source\",\n    value_label=\"Unique normalized titles\",\n)\n\nsave_current_figure(\"02_event_titles_by_source.png\")\nplt.show()\n\n# %% [markdown]\n# # 3. Time evolution of removals\n#\n# The yearly series counts **unique normalized titles within each source/year**.\n#\n# Only complete years (up to `LAST_COMPLETE_YEAR`) are plotted; the partial current year is left out.  \n# Future announced event years are reported separately below.\n\n# %%\n# ---------------------------------------------------------------------\n# Plot 2 requested:\n# Time evolution of event-like removals per year\n# ---------------------------------------------------------------------\n\nyearly_by_source = (\n    historical_event_df\n    .dropna(subset=[\"normalized_title\", \"event_year\"])\n    .groupby([\"event_year\", \"source\"])[\"normalized_title\"]\n    .nunique()\n    .rename(\"unique_event_titles\")\n    .reset_index()\n)\n\nyearly_pivot = (\n    yearly_by_source\n    .pivot(\n        index=\"event_year\",\n        columns=\"source\",\n        values=\"unique_event_titles\",\n    )\n    .fillna(0)\n    .sort_index()\n)\n\ndisplay(yearly_pivot.tail(15))\n\nplot_source_lines(\n    yearly_pivot,\n    title=\"Historical delisting / unavailability-like events by year\",\n    xlabel=\"Event year\",\n    ylabel=\"Unique normalized titles\",\n    year_range=YEAR_RANGE,\n)\n\nsave_current_figure(\"04_event_evolution_by_year_and_source.png\")\nplt.show()\n\nyearly_by_source.to_csv(\n    OUTPUT_DIR / \"event_counts_by_year_and_source.csv\",\n    index=False,\n)\n\n# %%\n# Total unique event-like titles by year across all outcome sources.\n#\n# A title appearing in more than one source in the same year is counted once.\n# This cell also integrates the IGDB yearly release counts and evaluates\n# whether yearly release volume is statistically associated with the number\n# of historical delisting / unavailability-like events.\n\nfrom scipy.stats import pearsonr, spearmanr\n\nyearly_total = (\n    historical_event_df\n    .dropna(subset=[\"normalized_title\", \"event_year\"])\n    .groupby(\"event_year\")[\"normalized_title\"]\n    .nunique()\n    .rename(\"unique_event_titles\")\n    .reset_index()\n)\n\nyearly_total[\"event_year\"] = pd.to_numeric(\n    yearly_total[\"event_year\"],\n    errors=\"coerce\",\n).astype(\"Int64\")\n\n# ---------------------------------------------------------------------\n# Load IGDB release-volume denominator\n# ---------------------------------------------------------------------\n\nigdb_releases = pd.read_csv(IGDB_RELEASES_FILE)\n\nrequired_igdb_columns = {\"year\", \"igdb_games_released\"}\nmissing_igdb_columns = required_igdb_columns - set(igdb_releases.columns)\n\nif missing_igdb_columns:\n    raise ValueError(\n        \"IGDB yearly-release file is missing required columns: \"\n        + \", \".join(sorted(missing_igdb_columns))\n    )\n\nigdb_releases[\"year\"] = pd.to_numeric(\n    igdb_releases[\"year\"],\n    errors=\"coerce\",\n).astype(\"Int64\")\n\nigdb_releases[\"igdb_games_released\"] = pd.to_numeric(\n    igdb_releases[\"igdb_games_released\"],\n    errors=\"coerce\",\n)\n\n# Keep only years present in both sources.\nyearly_with_igdb = (\n    yearly_total\n    .merge(\n        igdb_releases,\n        left_on=\"event_year\",\n        right_on=\"year\",\n        how=\"inner\",\n        validate=\"one_to_one\",\n    )\n    .drop(columns=\"year\")\n    .dropna(subset=[\"unique_event_titles\", \"igdb_games_released\"])\n    .sort_values(\"event_year\")\n    .reset_index(drop=True)\n)\n\ndisplay(yearly_with_igdb.tail(15))\n\n# ---------------------------------------------------------------------\n# Combined historical plot\n# ---------------------------------------------------------------------\n# Counts have very different magnitudes, therefore two y-axes are used.\n\nfig, ax_delisted = wide_figure()\n\nplot_years = yearly_with_igdb[\"event_year\"].astype(int)\n\nax_released = ax_delisted.twinx()\n\nline_released = ax_released.plot(\n    plot_years,\n    yearly_with_igdb[\"igdb_games_released\"],\n    **IGDB_STYLE,\n    markeredgecolor=\"white\",\n    markeredgewidth=0.4,\n    label=\"IGDB games released\",\n    clip_on=False,\n)\n\nline_delisted = ax_delisted.plot(\n    plot_years,\n    yearly_with_igdb[\"unique_event_titles\"],\n    **TOTAL_STYLE,\n    markeredgecolor=\"white\",\n    markeredgewidth=0.4,\n    label=\"Historical delisting / unavailability-like titles\",\n    clip_on=False,\n)\n\n# Draw the event-like series above the IGDB series.\nax_delisted.set_zorder(ax_released.get_zorder() + 1)\nax_delisted.patch.set_visible(False)\n\nax_delisted.set_xlabel(\"Year\")\nax_delisted.set_ylabel(\"Unique historical event-like titles\")\nstyle_year_axis(ax_delisted, YEAR_RANGE)\nstyle_count_axis(ax_delisted)\n\nax_released.set_ylabel(\"IGDB games released\")\nax_released.grid(False)\nax_released.spines[\"right\"].set_visible(True)\nstyle_count_axis(ax_released)\n\nlines = line_delisted + line_released\nlabels = [line.get_label() for line in lines]\nax_delisted.legend(lines, labels, loc=\"upper left\")\n\nset_title(\n    ax_delisted,\n    \"Historical event-like titles and IGDB game releases by year\",\n)\n\nsave_current_figure(\n    \"05_event_evolution_total_with_igdb_releases.png\"\n)\nplt.show()\n\n# ---------------------------------------------------------------------\n# Correlation analysis\n# ---------------------------------------------------------------------\n# Raw time-series levels can show a large correlation simply because both\n# variables trend over time. Therefore we report:\n#\n# 1. Pearson correlation on annual levels: linear association.\n# 2. Spearman correlation on annual levels: monotonic association.\n# 3. Pearson correlation on first differences: linear association between\n#    year-to-year changes after removing the common level/trend component.\n# 4. Spearman correlation on first differences: monotonic association between\n#    year-to-year changes.\n#\n# Only complete years (up to LAST_COMPLETE_YEAR) enter the tests, as in the\n# plot above.\n\ncorrelation_df = yearly_with_igdb[\n    yearly_with_igdb[\"event_year\"] <= LAST_COMPLETE_YEAR\n].copy()\n\nif len(correlation_df) < 4:\n    raise ValueError(\n        \"Too few complete overlapping years for correlation analysis.\"\n    )\n\nx = correlation_df[\"igdb_games_released\"].astype(float)\ny = correlation_df[\"unique_event_titles\"].astype(float)\n\npearson_levels = pearsonr(x, y)\nspearman_levels = spearmanr(x, y)\n\n# First differences: year-to-year changes.\ndiff_df = correlation_df[\n    [\"event_year\", \"igdb_games_released\", \"unique_event_titles\"]\n].copy()\n\ndiff_df[\"delta_igdb_games_released\"] = (\n    diff_df[\"igdb_games_released\"].diff()\n)\n\ndiff_df[\"delta_event_titles\"] = (\n    diff_df[\"unique_event_titles\"].diff()\n)\n\ndiff_df = diff_df.dropna(\n    subset=[\"delta_igdb_games_released\", \"delta_event_titles\"]\n)\n\npearson_diff = pearsonr(\n    diff_df[\"delta_igdb_games_released\"],\n    diff_df[\"delta_event_titles\"],\n)\n\nspearman_diff = spearmanr(\n    diff_df[\"delta_igdb_games_released\"],\n    diff_df[\"delta_event_titles\"],\n)\n\nALPHA = 0.05\n\ncorrelation_results = pd.DataFrame(\n    [\n        {\n            \"series\": \"annual levels\",\n            \"test\": \"Pearson\",\n            \"correlation\": pearson_levels.statistic,\n            \"p_value\": pearson_levels.pvalue,\n            \"n\": len(correlation_df),\n        },\n        {\n            \"series\": \"annual levels\",\n            \"test\": \"Spearman\",\n            \"correlation\": spearman_levels.statistic,\n            \"p_value\": spearman_levels.pvalue,\n            \"n\": len(correlation_df),\n        },\n        {\n            \"series\": \"first differences\",\n            \"test\": \"Pearson\",\n            \"correlation\": pearson_diff.statistic,\n            \"p_value\": pearson_diff.pvalue,\n            \"n\": len(diff_df),\n        },\n        {\n            \"series\": \"first differences\",\n            \"test\": \"Spearman\",\n            \"correlation\": spearman_diff.statistic,\n            \"p_value\": spearman_diff.pvalue,\n            \"n\": len(diff_df),\n        },\n    ]\n)\n\ncorrelation_results[\"significant_at_0.05\"] = (\n    correlation_results[\"p_value\"] < ALPHA\n)\n\ncorrelation_results[\"correlation\"] = (\n    correlation_results[\"correlation\"].round(4)\n)\ncorrelation_results[\"p_value\"] = (\n    correlation_results[\"p_value\"].map(lambda value: f\"{value:.4g}\")\n)\n\nprint(\n    f\"Correlation tests use complete years \"\n    f\"{int(correlation_df['event_year'].min())}-\"\n    f\"{int(correlation_df['event_year'].max())}; \"\n    f\"partial years after {LAST_COMPLETE_YEAR} are excluded.\"\n)\n\ndisplay(correlation_results)\n\n# Interpretation focused on the de-trended / first-difference result.\npearson_diff_significant = pearson_diff.pvalue < ALPHA\nspearman_diff_significant = spearman_diff.pvalue < ALPHA\n\nif pearson_diff_significant or spearman_diff_significant:\n    print(\n        \"At least one first-difference test is statistically significant \"\n        f\"at alpha={ALPHA}. This provides evidence that year-to-year \"\n        \"changes in IGDB release volume and event-like counts co-vary.\"\n    )\nelse:\n    print(\n        \"The first-difference correlations are not statistically significant \"\n        f\"at alpha={ALPHA}. A significant correlation in the raw annual \"\n        \"levels should therefore be interpreted cautiously: it is consistent \"\n        \"with a shared long-term time trend and does not by itself demonstrate \"\n        \"that yearly changes in release volume are associated with yearly \"\n        \"changes in delisting / unavailability-like events.\"\n    )\n\n# ---------------------------------------------------------------------\n# Exports\n# ---------------------------------------------------------------------\n\nyearly_total.to_csv(\n    OUTPUT_DIR / \"event_counts_by_year_total.csv\",\n    index=False,\n)\n\nyearly_with_igdb.to_csv(\n    OUTPUT_DIR / \"event_counts_and_igdb_releases_by_year.csv\",\n    index=False,\n)\n\ncorrelation_results.to_csv(\n    OUTPUT_DIR / \"event_release_correlation_tests.csv\",\n    index=False,\n)\n\n# %%\n# Check for event dates later than the current calendar year.\n\nif future_event_df.empty:\n    print(\"No future event years are present.\")\nelse:\n    future_summary = (\n        future_event_df[\n            [\n                \"source\",\n                \"game_name\",\n                \"normalized_title\",\n                \"event_year\",\n                \"source_status\",\n            ]\n        ]\n        .drop_duplicates()\n        .sort_values([\"event_year\", \"source\", \"game_name\"])\n    )\n\n    print(\n        \"These rows have future event years and are excluded from \"\n        \"historical-removal plots:\"\n    )\n    display(future_summary)\n\n    future_summary.to_csv(\n        OUTPUT_DIR / \"future_announced_events.csv\",\n        index=False,\n    )\n\n# %% [markdown]\n# # 4. Games overlapping DoesItPlay\n#\n# An overlap is defined by an exact match on the existing `normalized_title`.\n#\n# This is useful for combining a historical outcome-like record with DoesItPlay's physical/offline-play observations, but title matching is still only an exploratory entity-resolution method.\n\n# %%\n# ---------------------------------------------------------------------\n# Overall overlap statistics\n# ---------------------------------------------------------------------\n\noverlap_summary = (\n    event_df\n    .groupby(\"source\")\n    .agg(\n        event_titles=(\"normalized_title\", \"nunique\"),\n        doesitplay_overlap_titles=(\n            \"overlaps_doesitplay\",\n            lambda x: event_df.loc[x.index]\n            .loc[x, \"normalized_title\"]\n            .nunique()\n        ),\n    )\n    .reset_index()\n)\n\noverlap_summary[\"overlap_percent\"] = (\n    100\n    * overlap_summary[\"doesitplay_overlap_titles\"]\n    / overlap_summary[\"event_titles\"]\n)\n\ndisplay(overlap_summary)\n\nplot_bars(\n    [source_label(s) for s in overlap_summary[\"source\"]],\n    overlap_summary[\"doesitplay_overlap_titles\"],\n    [SOURCE_STYLE[s][\"color\"] for s in overlap_summary[\"source\"]],\n    title=\"Historical event-like titles also represented in DoesItPlay\",\n    value_label=\"Unique overlapping titles\",\n)\n\nsave_current_figure(\"06_doesitplay_overlap_by_source.png\")\nplt.show()\n\noverlap_summary.to_csv(\n    OUTPUT_DIR / \"doesitplay_overlap_summary.csv\",\n    index=False,\n)\n\n# %% [markdown]\n# ## 4.1 Time evolution for event-like games overlapping DoesItPlay\n#\n# Only complete years (up to `LAST_COMPLETE_YEAR`) are included.\n\n# %%\n# ---------------------------------------------------------------------\n# Requested overlap yearly evolution\n# ---------------------------------------------------------------------\n\noverlap_yearly_by_source = (\n    historical_overlap_event_df\n    .dropna(subset=[\"normalized_title\", \"event_year\"])\n    .groupby([\"event_year\", \"source\"])[\"normalized_title\"]\n    .nunique()\n    .rename(\"unique_overlap_event_titles\")\n    .reset_index()\n)\n\noverlap_yearly_pivot = (\n    overlap_yearly_by_source\n    .pivot(\n        index=\"event_year\",\n        columns=\"source\",\n        values=\"unique_overlap_event_titles\",\n    )\n    .fillna(0)\n    .sort_index()\n)\n\ndisplay(overlap_yearly_pivot.tail(15))\n\nplot_source_lines(\n    overlap_yearly_pivot,\n    title=\"Historical events by year for games also represented in DoesItPlay\",\n    xlabel=\"Event year\",\n    ylabel=\"Unique overlapping titles\",\n    year_range=YEAR_RANGE,\n)\n\nsave_current_figure(\n    \"08_doesitplay_overlap_event_evolution.png\"\n)\nplt.show()\n\noverlap_yearly_by_source.to_csv(\n    OUTPUT_DIR / \"doesitplay_overlap_event_counts_by_year.csv\",\n    index=False,\n)\n\n# %% [markdown]\n# # 5. DoesItPlay dependency characteristics for overlap games\n#\n# DoesItPlay can contain several observations for one title.\n#\n# For each title, the notebook derives:\n#\n# - number of DoesItPlay test rows,\n# - whether **any** test says offline play is unavailable,\n# - whether **any** test says a download is required.\n#\n# These are descriptive indicators only; they should not yet be interpreted as causal predictors of delisting.\n\n# %%\n# ---------------------------------------------------------------------\n# Aggregate DoesItPlay observations per normalized title\n# ---------------------------------------------------------------------\n\ndip = doesitplay_df.copy()\n\ndip[\"offline_play_bool\"] = coerce_nullable_bool(\n    dip[\"offline_play_bool\"]\n)\n\ndip[\"download_required_bool\"] = coerce_nullable_bool(\n    dip[\"download_required_bool\"]\n)\n\ndip_title_features = (\n    dip.dropna(subset=[\"normalized_title\"])\n    .groupby(\"normalized_title\")\n    .agg(\n        doesitplay_test_rows=(\"normalized_title\", \"size\"),\n        any_offline_unavailable=(\n            \"offline_play_bool\",\n            lambda s: bool((s == False).any()),\n        ),\n        any_download_required=(\n            \"download_required_bool\",\n            lambda s: bool((s == True).any()),\n        ),\n    )\n    .reset_index()\n)\n\noverlap_titles = (\n    overlap_event_df[\n        [\"normalized_title\", \"game_name\"]\n    ]\n    .drop_duplicates(subset=[\"normalized_title\"])\n)\n\noverlap_dependency = overlap_titles.merge(\n    dip_title_features,\n    on=\"normalized_title\",\n    how=\"left\",\n)\n\ndisplay(overlap_dependency.head(20))\n\ndependency_counts = pd.DataFrame(\n    {\n        \"indicator\": [\n            \"At least one test cannot play offline\",\n            \"At least one test requires download\",\n        ],\n        \"titles\": [\n            int(overlap_dependency[\"any_offline_unavailable\"].sum()),\n            int(overlap_dependency[\"any_download_required\"].sum()),\n        ],\n    }\n)\n\ndisplay(dependency_counts)\n\nplot_bars(\n    [textwrap.fill(i, 22) for i in dependency_counts[\"indicator\"]],\n    dependency_counts[\"titles\"],\n    SOURCE_STYLE[\"doesitplay\"][\"color\"],\n    title=\"DoesItPlay dependency indicators among overlapping event-like games\",\n    value_label=\"Unique normalized titles\",\n)\n\nsave_current_figure(\n    \"09_doesitplay_overlap_dependency_indicators.png\"\n)\nplt.show()\n\noverlap_dependency.to_csv(\n    OUTPUT_DIR / \"doesitplay_overlap_dependency_features.csv\",\n    index=False,\n)\n\n# %% [markdown]\n# # 6. Export compact analysis tables\n#\n# The notebook already saves plot-specific tables as it runs.  \n# This final cell exports the main analysis subsets for downstream inspection.\n\n# %%\nevent_export_columns = [\n    \"source\",\n    \"source_record_id\",\n    \"game_name\",\n    \"normalized_title\",\n    \"publisher\",\n    \"developer\",\n    \"platforms\",\n    \"event_info\",\n    \"event_year\",\n    \"source_status\",\n    \"is_historically_unavailable\",\n    \"overlaps_doesitplay\",\n]\n\nevent_df[\n    [c for c in event_export_columns if c in event_df.columns]\n].to_csv(\n    OUTPUT_DIR / \"historical_event_like_records.csv\",\n    index=False,\n)\n\noverlap_event_df[\n    [c for c in event_export_columns if c in overlap_event_df.columns]\n].to_csv(\n    OUTPUT_DIR / \"historical_event_like_records_overlapping_doesitplay.csv\",\n    index=False,\n)\n\nprint(\"Analysis completed.\")\nprint(\"Outputs written to:\", OUTPUT_DIR.resolve())\n"},{"path":"RQ3_package/delisting_causes/analyze_delisting_causes.py","group":"RQ3_package/delisting_causes","text":"#!/usr/bin/env python3\n\n\"\"\"\nWhy do games disappear? Descriptive analysis of the explicitly stated\ndelisting causes in delistedGames.\n\nWorks WITHIN delistedGames (every entry was delisted), so there is no\nPC-vs-console control-group confound as in the old genre comparison.\nCauses are multi-label: shares can sum to more than 100%.\n\nInputs:\n    - delisting_cause_labels.csv                     (validate_delisting_causes.py)\n    - RawData/DelistedGames/delistedgames.json       release / delisting dates\n    - Analysis/unified_games.csv                     normalized_title\n    - IGDB_miner/igdb_genres_by_normalized_game.csv  genres (exact matches only)\n\nOutputs (in figures/, as PNG + PDF; test results go to the log):\n    A. 01_cause_counts, 02_cause_share_by_platform\n    B. 03_cause_share_by_genre\n    C. 04_age_at_delisting_ecdf\n    D. 05_causes_by_year\n    E. 06_relisting_rate_by_cause\n\"\"\"\n\nimport json\nimport logging\nimport re\nimport sys\nfrom pathlib import Path\n\nimport matplotlib.pyplot as plt\nimport numpy as np\nimport pandas as pd\nfrom scipy import stats\n\nBASE_DIR = Path(__file__).resolve().parent\nsys.path.insert(0, str(BASE_DIR.parent))\n\nfrom figure_style import (  # noqa: E402\n    CAUSE_STYLE,\n    INK,\n    MUTED,\n    SINGLE_COLUMN,\n    apply_style,\n    plot_bars,\n    set_title,\n    style_count_axis,\n    style_year_axis,\n    wide_figure,\n)\n\n\n# ---------------------------------------------------------------------------\n# Configuration\n# ---------------------------------------------------------------------------\n\nREPO_DIR = BASE_DIR.parent.parent\n\nLABELS_CSV = BASE_DIR / \"delisting_cause_labels.csv\"\nFIGURES_DIR = BASE_DIR / \"figures\"\nRAW_JSON = REPO_DIR / \"RawData\" / \"DelistedGames\" / \"delistedgames.json\"\nUNIFIED_CSV = REPO_DIR / \"Analysis\" / \"unified_games.csv\"\nIGDB_GENRES_CSV = REPO_DIR / \"IGDB_miner\" / \"igdb_genres_by_normalized_game.csv\"\n\nCAUSES = [\"licensing\", \"ip_change\", \"server\", \"store_closure\", \"publisher_exit\"]\nFALLBACKS = [\"other\", \"not_stated\"]\nLABELS = CAUSES + FALLBACKS\n\nLAST_COMPLETE_YEAR = 2025\nFIRST_PLOT_YEAR = 2008      # fewer than a handful of delistings per year before this\n\nMIN_PLATFORM_ENTRIES = 50\nMIN_GENRE_ENTRIES = 25\nFDR_ALPHA = 0.05\n\nEARLY_AGE_YEARS = 2         # \"pulled in the first two years\"\nMAX_PLOT_AGE = 15\n\nCAUSE_BAR_COLOR = CAUSE_STYLE[\"licensing\"][\"color\"]\nFALLBACK_BAR_COLOR = CAUSE_STYLE[\"other\"][\"color\"]\n\nPLATFORM_NAMES = {\n    \"pc\": \"PC\", \"gog\": \"GOG\", \"steam\": \"Steam\", \"ios\": \"iOS\",\n    \"playstation-3\": \"PlayStation 3\", \"playstation-4\": \"PlayStation 4\",\n    \"playstation-vita\": \"PS Vita\", \"playstation-portable\": \"PSP\",\n    \"nintendo-3ds\": \"Nintendo 3DS\", \"nintendo-wii-u\": \"Wii U\",\n    \"nintendo-wii\": \"Wii\", \"nintendo-switch\": \"Switch\", \"nintendo-ds\": \"Nintendo DS\",\n    \"xbox-360\": \"Xbox 360\", \"xbox-one\": \"Xbox One\",\n}\n\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format=\"%(asctime)s - %(levelname)s - %(message)s\",\n)\n\nlogger = logging.getLogger(__name__)\n\n# matplotlib's PDF font subsetting logs every glyph at INFO.\nlogging.getLogger(\"fontTools\").setLevel(logging.WARNING)\n\n\n# ---------------------------------------------------------------------------\n# Helpers\n# ---------------------------------------------------------------------------\n\ndef label_name(label: str) -> str:\n    return CAUSE_STYLE[label][\"label\"]\n\n\ndef platform_name(slug: str) -> str:\n    return PLATFORM_NAMES.get(slug, slug.replace(\"-\", \" \").title())\n\n\ndef save_figure(fig, name: str) -> None:\n    FIGURES_DIR.mkdir(exist_ok=True)\n    for suffix in (\".png\", \".pdf\"):\n        fig.savefig(FIGURES_DIR / f\"{name}{suffix}\")\n    plt.close(fig)\n    logger.info(\"Saved %s.png/.pdf\", name)\n\n\ndef bh_qvalues(p_values: pd.Series) -> pd.Series:\n    \"\"\"Benjamini-Hochberg adjusted p-values, NaNs left out.\"\"\"\n    q = pd.Series(np.nan, index=p_values.index)\n    valid = p_values.dropna()\n    if len(valid):\n        q[valid.index] = stats.false_discovery_control(valid.values, method=\"bh\")\n    return q\n\n\nMONTHS = {\n    month: number\n    for number, month in enumerate(\n        [\"jan\", \"feb\", \"mar\", \"apr\", \"may\", \"jun\", \"jul\", \"aug\", \"sep\", \"oct\", \"nov\", \"dec\"],\n        start=1,\n    )\n}\n\nDATE_PATTERN = re.compile(\n    r\"(?:\\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\\.?\\s+\"\n    r\"(?:\\d{1,2}(?:st|nd|rd|th)?,?\\s+)?)?\"\n    r\"\\b((?:19|20)\\d\\d)\\b\",\n    re.I,\n)\n\n\ndef earliest_date(text) -> tuple:\n    \"\"\"\n    Earliest date in a free-text date block, as (fractional year, has_month).\n    Year-only dates are placed mid-year.\n    \"\"\"\n    if not isinstance(text, str):\n        return np.nan, False\n\n    dates = []\n    for month, year in DATE_PATTERN.findall(text):\n        if month:\n            dates.append((int(year) + (MONTHS[month.lower()[:3]] - 1) / 12, True))\n        else:\n            dates.append((int(year) + 0.5, False))\n\n    return min(dates) if dates else (np.nan, False)\n\n\n# ---------------------------------------------------------------------------\n# Data\n# ---------------------------------------------------------------------------\n\ndef load_data() -> pd.DataFrame:\n    labels = pd.read_csv(LABELS_CSV)\n    for column in LABELS + [f\"{c}_agree\" for c in CAUSES] + [\"speculative\", \"relisted\", \"is_bundle\"]:\n        labels[column] = labels[column].astype(bool)\n\n    with open(RAW_JSON, encoding=\"utf-8\") as handle:\n        raw = pd.DataFrame(\n            {\n                \"id\": record[\"id\"],\n                \"digital_release\": record[\"data\"].get(\"digital_release\"),\n                \"delisting\": record[\"data\"].get(\"delisting\"),\n            }\n            for record in json.load(handle)\n        )\n\n    for column in (\"digital_release\", \"delisting\"):\n        parsed = raw[column].apply(earliest_date)\n        raw[f\"{column}_date\"] = parsed.str[0]\n        raw[f\"{column}_has_month\"] = parsed.str[1]\n\n    raw[\"age_years\"] = raw[\"delisting_date\"] - raw[\"digital_release_date\"]\n    raw[\"delisting_year\"] = np.floor(raw[\"delisting_date\"])\n\n    unified = pd.read_csv(\n        UNIFIED_CSV, usecols=[\"source\", \"source_record_id\", \"normalized_title\"], low_memory=False,\n    )\n    unified = unified[unified[\"source\"] == \"delisted_games\"].rename(columns={\"source_record_id\": \"id\"})\n\n    data = (\n        labels\n        .merge(raw.drop(columns=[\"digital_release\", \"delisting\"]), on=\"id\", how=\"left\")\n        .merge(unified[[\"id\", \"normalized_title\"]], on=\"id\", how=\"left\")\n    )\n\n    logger.info(\"Loaded %d labelled entries.\", len(data))\n\n    return data\n\n\n# ---------------------------------------------------------------------------\n# A. Headline counts and platforms\n# ---------------------------------------------------------------------------\n\ndef cause_counts(data: pd.DataFrame) -> pd.DataFrame:\n    total = len(data)\n    rows = []\n\n    for label in LABELS:\n        mask = data[label]\n        rows.append({\n            \"label\": label,\n            \"name\": label_name(label),\n            \"entries\": int(mask.sum()),\n            \"share_pct\": round(100 * mask.mean(), 2),\n            \"entries_both_models\": int(data[f\"{label}_agree\"].sum()) if label in CAUSES else np.nan,\n            \"speculative\": int((mask & data[\"speculative\"]).sum()),\n            \"bundles\": int((mask & data[\"is_bundle\"]).sum()),\n            \"total_entries\": total,\n        })\n\n    counts = pd.DataFrame(rows)\n\n    n_any = int(data[CAUSES].any(axis=1).sum())\n    n_multi = int((data[CAUSES].sum(axis=1) > 1).sum())\n    logger.info(\n        \"Out of %d entries: %d (%.1f%%) state at least one of the five causes, \"\n        \"%d have more than one.\\n%s\",\n        total, n_any, 100 * n_any / total, n_multi, counts.to_string(index=False),\n    )\n\n    fig, ax = plot_bars(\n        [label_name(label) for label in LABELS],\n        counts[\"entries\"].tolist(),\n        [CAUSE_BAR_COLOR if label in CAUSES else FALLBACK_BAR_COLOR for label in LABELS],\n        f\"Stated delisting causes (n = {total:,}, multi-label)\",\n        value_format=lambda value: f\"{value:,} ({100 * value / total:.0f}%)\",\n    )\n    ax.set_xlim(0, counts[\"entries\"].max() * 1.32)\n    save_figure(fig, \"01_cause_counts\")\n\n    return counts\n\n\ndef plot_share_heatmap(shares: pd.DataFrame, row_labels: list, title: str, name: str) -> None:\n    \"\"\"Rows x labels heatmap of % shares, one sequential hue, values in the cells.\"\"\"\n    n_rows, n_cols = shares.shape\n    fig, ax = plt.subplots(figsize=(SINGLE_COLUMN, 0.75 + 0.22 * n_rows))\n\n    ax.imshow(shares.values, cmap=\"Blues\", vmin=0, vmax=max(60, np.nanmax(shares.values)), aspect=\"auto\")\n\n    for i in range(n_rows):\n        for j in range(n_cols):\n            value = shares.iat[i, j]\n            ax.text(\n                j, i, f\"{value:.0f}\", ha=\"center\", va=\"center\", fontsize=7,\n                color=\"white\" if value > 40 else INK,\n            )\n\n    ax.set_xticks(range(n_cols))\n    ax.set_xticklabels([label_name(c).replace(\" \", \"\\n\", 1) for c in shares.columns], fontsize=7)\n    ax.xaxis.tick_top()\n    ax.set_yticks(range(n_rows))\n    ax.set_yticklabels(row_labels, fontsize=7)\n    ax.tick_params(length=0)\n    ax.grid(False)\n    for spine in ax.spines.values():\n        spine.set_visible(False)\n\n    set_title(ax, title)\n    fig.tight_layout(pad=0.3)\n    save_figure(fig, name)\n\n\ndef platform_split(data: pd.DataFrame) -> None:\n    counts = data[\"platform\"].value_counts()\n    big = counts[counts >= MIN_PLATFORM_ENTRIES].index\n    grouped = data.assign(platform_group=data[\"platform\"].where(data[\"platform\"].isin(big), \"other platforms\"))\n\n    table = grouped.groupby(\"platform_group\")[LABELS].mean().mul(100).round(2)\n    table.insert(0, \"entries\", grouped[\"platform_group\"].value_counts())\n    table = table.sort_values(\"entries\", ascending=False)\n\n    rows = [p for p in table.index if p != \"other platforms\"]\n    plot_share_heatmap(\n        table.loc[rows, LABELS],\n        [f\"{platform_name(p)} ({table.at[p, 'entries']})\" for p in rows],\n        \"Share of entries per stated cause, by platform (%)\",\n        \"02_cause_share_by_platform\",\n    )\n\n\n# ---------------------------------------------------------------------------\n# B. Cause x genre\n# ---------------------------------------------------------------------------\n\ndef genre_association(data: pd.DataFrame) -> None:\n    igdb = pd.read_csv(IGDB_GENRES_CSV, usecols=[\"normalized_title\", \"genres\", \"match_status\"])\n    igdb = igdb[(igdb[\"match_status\"] == \"exact_normalized_match\") & igdb[\"genres\"].notna()]\n\n    matched = data.merge(igdb[[\"normalized_title\", \"genres\"]], on=\"normalized_title\", how=\"inner\")\n    logger.info(\n        \"Genres: %d of %d entries have an exact IGDB match with genres.\", len(matched), len(data),\n    )\n\n    exploded = matched.assign(genre=matched[\"genres\"].str.split(\"|\")).explode(\"genre\")\n    genre_sizes = exploded[\"genre\"].value_counts()\n    genres = genre_sizes[genre_sizes >= MIN_GENRE_ENTRIES].index\n\n    rows = []\n    for genre in genres:\n        in_genre = matched[\"genres\"].str.split(\"|\").apply(lambda g: genre in g)\n        for cause in CAUSES:\n            a = int((in_genre & matched[cause]).sum())\n            b = int((in_genre & ~matched[cause]).sum())\n            c = int((~in_genre & matched[cause]).sum())\n            d = int((~in_genre & ~matched[cause]).sum())\n            odds_ratio, p_value = stats.fisher_exact([[a, b], [c, d]])\n            rows.append({\n                \"genre\": genre,\n                \"cause\": cause,\n                \"genre_entries\": a + b,\n                \"genre_entries_with_cause\": a,\n                \"share_in_genre_pct\": round(100 * a / (a + b), 2),\n                \"share_in_other_genres_pct\": round(100 * c / (c + d), 2) if c + d else np.nan,\n                \"odds_ratio\": round(odds_ratio, 3),\n                \"fisher_p\": p_value,\n            })\n\n    table = pd.DataFrame(rows)\n    table[\"bh_q\"] = bh_qvalues(table[\"fisher_p\"])\n    table[\"significant\"] = table[\"bh_q\"] < FDR_ALPHA\n    table[\"matched_entries\"] = len(matched)\n\n    significant = table[table[\"significant\"]].sort_values(\"bh_q\")\n    logger.info(\"Significant genre x cause cells (BH q < %.2f):\\n%s\",\n                FDR_ALPHA, significant.to_string(index=False))\n\n    shares = table.pivot(index=\"genre\", columns=\"cause\", values=\"share_in_genre_pct\")[CAUSES]\n    order = shares.sort_values(\"licensing\", ascending=False).index\n    plot_share_heatmap(\n        shares.loc[order],\n        [f\"{g} ({genre_sizes[g]})\" for g in order],\n        \"Share of entries per stated cause, by IGDB genre (%)\",\n        \"03_cause_share_by_genre\",\n    )\n\n\n# ---------------------------------------------------------------------------\n# C. Cause x age at delisting\n# ---------------------------------------------------------------------------\n\ndef age_at_delisting(data: pd.DataFrame) -> None:\n    aged = data[data[\"age_years\"].notna()]\n    negative = int((aged[\"age_years\"] < 0).sum())\n    aged = aged[aged[\"age_years\"] >= 0]\n    month_precision = int((aged[\"digital_release_has_month\"] & aged[\"delisting_has_month\"]).sum())\n\n    logger.info(\n        \"Age at delisting: %d entries with both dates (%d with month precision), \"\n        \"%d dropped with negative age.\",\n        len(aged), month_precision, negative,\n    )\n\n    rows = []\n    for label in LABELS:\n        with_label = aged.loc[aged[label], \"age_years\"]\n        without = aged.loc[~aged[label], \"age_years\"]\n        rows.append({\n            \"label\": label,\n            \"entries\": len(with_label),\n            \"median_years\": round(with_label.median(), 2),\n            \"q1_years\": round(with_label.quantile(0.25), 2),\n            \"q3_years\": round(with_label.quantile(0.75), 2),\n            \"mean_years\": round(with_label.mean(), 2),\n            f\"share_under_{EARLY_AGE_YEARS}y_pct\": round(100 * (with_label < EARLY_AGE_YEARS).mean(), 2),\n            f\"share_under_{EARLY_AGE_YEARS}y_rest_pct\": round(100 * (without < EARLY_AGE_YEARS).mean(), 2),\n            \"mannwhitney_p\": stats.mannwhitneyu(with_label, without).pvalue if len(with_label) else np.nan,\n            \"ks_p\": stats.ks_2samp(with_label, without).pvalue if len(with_label) else np.nan,\n            \"negative_age_dropped\": negative,\n            \"month_precision_entries\": month_precision,\n        })\n\n    table = pd.DataFrame(rows)\n    table[\"mannwhitney_bh_q\"] = bh_qvalues(table[\"mannwhitney_p\"])\n    table[\"ks_bh_q\"] = bh_qvalues(table[\"ks_p\"])\n    logger.info(\"Age at delisting per cause:\\n%s\", table.to_string(index=False))\n\n    fig, ax = plt.subplots(figsize=(SINGLE_COLUMN, 2.6))\n    grid = np.linspace(0, MAX_PLOT_AGE, 301)\n\n    def ecdf(values):\n        values = np.sort(values.to_numpy())\n        return np.searchsorted(values, grid, side=\"right\") / len(values)\n\n    ax.plot(grid, ecdf(aged[\"age_years\"]), color=MUTED, linestyle=(0, (4, 2)), linewidth=1.0,\n            label=f\"All entries ({len(aged):,})\")\n    for cause in CAUSES:\n        values = aged.loc[aged[cause], \"age_years\"]\n        if values.empty:\n            continue\n        style = CAUSE_STYLE[cause]\n        ax.plot(grid, ecdf(values), color=style[\"color\"], marker=style[\"marker\"], markevery=30,\n                markeredgecolor=\"white\", markeredgewidth=0.4,\n                label=f\"{style['label']} ({len(values):,})\")\n\n    ax.set_xlim(0, MAX_PLOT_AGE)\n    ax.set_ylim(0, 1)\n    ax.set_xlabel(\"Years from digital release to first delisting\")\n    ax.set_ylabel(\"Cumulative share of entries\")\n    ax.legend(loc=\"lower right\", fontsize=7)\n    set_title(ax, \"Age at delisting by stated cause\")\n    fig.tight_layout(pad=0.3)\n    save_figure(fig, \"04_age_at_delisting_ecdf\")\n\n\n# ---------------------------------------------------------------------------\n# D. Cause x calendar year\n# ---------------------------------------------------------------------------\n\ndef causes_by_year(data: pd.DataFrame) -> None:\n    dated = data[data[\"delisting_year\"].between(FIRST_PLOT_YEAR, LAST_COMPLETE_YEAR)]\n    years = range(FIRST_PLOT_YEAR, LAST_COMPLETE_YEAR + 1)\n\n    table = dated.groupby(\"delisting_year\")[LABELS].sum().reindex(years, fill_value=0)\n    table.insert(0, \"all_entries\", dated[\"delisting_year\"].value_counts().reindex(years, fill_value=0))\n    table.index = table.index.astype(int)\n\n    fig, ax = wide_figure()\n    for cause in CAUSES:\n        style = CAUSE_STYLE[cause]\n        ax.plot(table.index, table[cause], color=style[\"color\"], marker=style[\"marker\"],\n                markeredgecolor=\"white\", markeredgewidth=0.4, label=style[\"label\"],\n                clip_on=False, zorder=3)\n\n    ax.set_xlabel(\"Year of first delisting\")\n    ax.set_ylabel(\"Entries\")\n    style_year_axis(ax, list(years))\n    style_count_axis(ax)\n    ax.legend(loc=\"upper left\", ncol=2)\n    set_title(ax, \"Delisted entries per year by stated cause\")\n    save_figure(fig, \"05_causes_by_year\")\n\n\n# ---------------------------------------------------------------------------\n# E. Relisting rate per cause\n# ---------------------------------------------------------------------------\n\ndef relisting_rate(data: pd.DataFrame) -> None:\n    rows = []\n    for label in LABELS:\n        mask = data[label]\n        a = int((mask & data[\"relisted\"]).sum())\n        b = int((mask & ~data[\"relisted\"]).sum())\n        c = int((~mask & data[\"relisted\"]).sum())\n        d = int((~mask & ~data[\"relisted\"]).sum())\n        odds_ratio, p_value = stats.fisher_exact([[a, b], [c, d]])\n        rows.append({\n            \"label\": label,\n            \"entries\": a + b,\n            \"relisted\": a,\n            \"relisted_pct\": round(100 * a / (a + b), 2) if a + b else np.nan,\n            \"relisted_rest_pct\": round(100 * c / (c + d), 2) if c + d else np.nan,\n            \"odds_ratio\": round(odds_ratio, 3),\n            \"fisher_p\": p_value,\n        })\n\n    table = pd.DataFrame(rows)\n    table[\"bh_q\"] = bh_qvalues(table[\"fisher_p\"])\n    table[\"overall_relisted_pct\"] = round(100 * data[\"relisted\"].mean(), 2)\n    logger.info(\"Relisting rate per cause:\\n%s\", table.to_string(index=False))\n\n    shown = table[table[\"entries\"] > 0]\n    fig, ax = plot_bars(\n        [f\"{label_name(label)} ({n:,})\" for label, n in zip(shown[\"label\"], shown[\"entries\"])],\n        shown[\"relisted_pct\"].tolist(),\n        [CAUSE_BAR_COLOR if label in CAUSES else FALLBACK_BAR_COLOR for label in shown[\"label\"]],\n        \"Share of entries later relisted, by stated cause\",\n        value_label=\"Entries later relisted (%)\",\n        value_format=\"{:.0f}%\".format,\n    )\n    save_figure(fig, \"06_relisting_rate_by_cause\")\n\n\n# ---------------------------------------------------------------------------\n# Main\n# ---------------------------------------------------------------------------\n\ndef main():\n    apply_style()\n    data = load_data()\n\n    cause_counts(data)\n    platform_split(data)\n    genre_association(data)\n    age_at_delisting(data)\n    causes_by_year(data)\n    relisting_rate(data)\n\n    logger.info(\"Delisting-cause analysis completed.\")\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"RQ3_package/delisting_causes/annotate_spot_check.py","group":"RQ3_package/delisting_causes","text":"\"\"\"\nManual spot check of the delisting cause labels.\n\nShows the rows of spot_check_sample.csv one at a time: the cause, its\ndefinition from the classification prompt, the quote the model gave as\nevidence, and the narrative with that quote highlighted. Each answer is\nsaved to the file immediately, so the check can be stopped and resumed;\nit restarts at the first unanswered row.\n\nKeys:  y = label correct   n = label wrong   s = skip   b = back\n       f = show the full narrative   q = quit\n\nRun validate_delisting_causes.py afterwards to get the precision per cause.\n\"\"\"\n\nimport re\nimport shutil\nimport textwrap\nfrom pathlib import Path\n\nimport pandas as pd\nfrom rapidfuzz import fuzz\n\nBASE_DIR = Path(__file__).resolve().parent\nSPOT_CHECK_CSV = BASE_DIR / \"spot_check_sample.csv\"\nPROMPT_TXT = BASE_DIR / \"prompt.txt\"\n\nCONTEXT_CHARS = 900\n\nBOLD, DIM, HIGHLIGHT, RESET = \"\\033[1m\", \"\\033[2m\", \"\\033[1;30;43m\", \"\\033[0m\"\nQUOTE_START, QUOTE_END = \"\\x01\", \"\\x02\"\n\n\ndef cause_definitions() -> dict[str, str]:\n    \"\"\"Definition of each cause, as given to the models in the prompt.\"\"\"\n    text = PROMPT_TXT.read_text()\n    block = text.split(\"THE FIVE CAUSES\", 1)[1].split(\"FALLBACK FLAGS\", 1)[0]\n    definitions = {}\n    for match in re.finditer(r\"^([A-Z_]+)\\s+(.*?)(?=^[A-Z_]+\\s|\\Z)\", block, re.M | re.S):\n        definitions[match.group(1).lower()] = \" \".join(match.group(2).split())\n    return definitions\n\n\ndef quote_span(quote: str, narrative: str) -> tuple[int, int] | None:\n    start = narrative.lower().find(quote.lower())\n    if start >= 0:\n        return start, start + len(quote)\n    alignment = fuzz.partial_ratio_alignment(quote, narrative)\n    if alignment is None or alignment.score < 80:\n        return None\n    return alignment.dest_start, alignment.dest_end\n\n\ndef render_narrative(narrative: str, span: tuple[int, int] | None, full: bool) -> str:\n    if span is not None:\n        start, end = span\n        narrative = narrative[:start] + QUOTE_START + narrative[start:end] + QUOTE_END + narrative[end:]\n        end += 2\n\n    prefix = suffix = \"\"\n    if not full and len(narrative) > 2 * CONTEXT_CHARS:\n        centre_start, centre_end = span if span is not None else (0, 0)\n        lo = max(0, centre_start - CONTEXT_CHARS)\n        hi = min(len(narrative), centre_end + CONTEXT_CHARS)\n        if lo > 0:\n            lo = narrative.find(\" \", lo) + 1\n            prefix = \"… \"\n        if hi < len(narrative):\n            hi = narrative.rfind(\" \", 0, hi)\n            suffix = \" …\"\n        narrative = prefix + narrative[lo:hi] + suffix\n\n    width = min(shutil.get_terminal_size().columns, 100) - 2\n    paragraphs = [textwrap.fill(p, width) for p in narrative.split(\"\\n\") if p.strip()]\n    text = \"\\n\\n\".join(paragraphs)\n    return text.replace(QUOTE_START, HIGHLIGHT).replace(QUOTE_END, RESET)\n\n\ndef show(row: pd.Series, position: int, total: int, answered: int,\n         definitions: dict[str, str], full: bool) -> None:\n    print(\"\\033[2J\\033[H\", end=\"\")\n    print(f\"{DIM}Row {position + 1}/{total} · {answered} answered{RESET}\")\n    print(f\"{BOLD}{row['title']}{RESET}  {DIM}(id {row['id']}){RESET}\\n\")\n    print(f\"{BOLD}Cause: {row['cause'].upper()}{RESET}\")\n    print(textwrap.fill(definitions.get(row[\"cause\"], \"\"), 98, initial_indent=\"  \",\n                        subsequent_indent=\"  \"))\n    print(f\"\\n{BOLD}Quote:{RESET} {row['quote']}\\n\")\n\n    span = quote_span(row[\"quote\"], row[\"narrative\"])\n    if span is None:\n        print(f\"{DIM}(quote not located in the narrative){RESET}\\n\")\n    print(render_narrative(row[\"narrative\"], span, full))\n\n    if row[\"correct\"]:\n        print(f\"\\n{DIM}Current answer: {row['correct']}{RESET}\")\n\n\ndef main() -> None:\n    sample = pd.read_csv(SPOT_CHECK_CSV, dtype=str, keep_default_na=False)\n    definitions = cause_definitions()\n\n    unanswered = sample.index[~sample[\"correct\"].str.strip().str.lower().isin([\"y\", \"n\"])]\n    position = int(unanswered[0]) if len(unanswered) else 0\n    full = False\n\n    while 0 <= position < len(sample):\n        answered = int(sample[\"correct\"].str.strip().str.lower().isin([\"y\", \"n\"]).sum())\n        show(sample.loc[position], position, len(sample), answered, definitions, full)\n\n        key = input(f\"\\n{BOLD}Correct? [y/n]{RESET}  s=skip b=back f=full q=quit > \").strip().lower()\n        full = False\n\n        if key in (\"y\", \"n\"):\n            sample.loc[position, \"correct\"] = key\n            sample.to_csv(SPOT_CHECK_CSV, index=False)\n            position += 1\n        elif key == \"s\":\n            position += 1\n        elif key == \"b\":\n            position = max(0, position - 1)\n        elif key == \"f\":\n            full = True\n        elif key == \"q\":\n            break\n\n    answered = int(sample[\"correct\"].str.strip().str.lower().isin([\"y\", \"n\"]).sum())\n    print(f\"\\nSaved. {answered}/{len(sample)} rows answered.\")\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"RQ3_package/delisting_causes/classify_delisting_causes.py","group":"RQ3_package/delisting_causes","text":"#!/usr/bin/env python3\n\n\"\"\"\nFlag the explicitly stated delisting causes in the delistedGames narratives\nwith local LLMs (Ollama).\n\nEach delistedGames entry has a free-text narrative (field `info`). Two local\nmodels from different families read the cleaned narrative and flag five fixed\ncauses (LICENSING, IP_CHANGE, SERVER, STORE_CLOSURE, PUBLISHER_EXIT), or the\nOTHER / NOT_STATED fallback, with a verbatim quote for every flagged cause.\nThe prompt is prompt.txt, next to this script.\n\nInputs:\n    - RawData/DelistedGames/delistedgames.json   narratives (`info`)\n    - Analysis/unified_games.csv                 the 2,123 delistedGames rows\n                                                 that passed the non-game filter\n    - prompt.txt\n    - a running Ollama server with the MODELS pulled, at OLLAMA_URL\n      (environment variable or --ollama-url; default http://localhost:11434).\n\nOutputs:\n    - llm_cache/<model_tag>.jsonl   one line per entry: id, model tag, model\n                                    digest, prompt hash, parsed answer, raw\n                                    answer. Ids already cached are skipped, so\n                                    an interrupted run resumes where it stopped.\n\nUsage:\n    python classify_delisting_causes.py                    # all entries, all models\n    python classify_delisting_causes.py --sample 20        # test run\n    python classify_delisting_causes.py --model qwen3:14b --ids 3 296 879\n    python classify_delisting_causes.py --show-clean 10    # print cleaned samples\n    python classify_delisting_causes.py --workers 4        # 4 parallel requests\n\nTemperature 0 and a fixed seed make answers repeatable on one machine. Other\nhardware, or parallel requests, can change a few near-tie answers, so run each\nmodel's whole cache on one machine with one --workers setting.\n\nclean_narrative() is shared with validate_delisting_causes.py, which checks the\nquotes against the same cleaned text.\n\"\"\"\n\nimport argparse\nimport hashlib\nimport json\nimport logging\nimport os\nimport random\nimport re\nimport time\nfrom concurrent.futures import ThreadPoolExecutor, as_completed\nfrom pathlib import Path\n\nimport pandas as pd\nimport requests\n\n\n# ---------------------------------------------------------------------------\n# Configuration\n# ---------------------------------------------------------------------------\n\nBASE_DIR = Path(__file__).resolve().parent\nREPO_DIR = BASE_DIR.parent.parent\n\nRAW_JSON = REPO_DIR / \"RawData\" / \"DelistedGames\" / \"delistedgames.json\"\nUNIFIED_CSV = REPO_DIR / \"Analysis\" / \"unified_games.csv\"\n\nPROMPT_FILE = BASE_DIR / \"prompt.txt\"\nCACHE_DIR = BASE_DIR / \"llm_cache\"\n\nOLLAMA_URL = os.environ.get(\"OLLAMA_URL\", \"http://localhost:11434\")\n\n# Primary model first, then a second model from another family.\nMODELS = [\"qwen3:14b\", \"gemma3:12b\"]\n\nSEED = 42\nTEMPERATURE = 0\nNUM_CTX = 8192\nREQUEST_TIMEOUT = 600   # seconds per entry\n\n# Narratives are truncated to this many words (the longest is ~1,400).\nMAX_WORDS = 3000\n\nCAUSES = [\"licensing\", \"ip_change\", \"server\", \"store_closure\", \"publisher_exit\"]\n\n# Every cause is an object whose quote comes BEFORE the boolean, so the\n# model has to find the evidence before it commits to a label.\nRESPONSE_SCHEMA = {\n    \"type\": \"object\",\n    \"properties\": {\n        **{\n            cause: {\n                \"type\": \"object\",\n                \"properties\": {\n                    \"quote\": {\"type\": \"string\"},\n                    \"applies\": {\"type\": \"boolean\"},\n                },\n                \"required\": [\"quote\", \"applies\"],\n            }\n            for cause in CAUSES\n        },\n        \"other_reason\": {\"type\": \"string\"},\n        \"other\": {\"type\": \"boolean\"},\n        \"not_stated\": {\"type\": \"boolean\"},\n        \"speculative\": {\"type\": \"boolean\"},\n        \"relisted\": {\"type\": \"boolean\"},\n        \"is_bundle\": {\"type\": \"boolean\"},\n    },\n    \"required\": CAUSES + [\n        \"other_reason\", \"other\", \"not_stated\", \"speculative\", \"relisted\", \"is_bundle\",\n    ],\n}\n\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format=\"%(asctime)s - %(levelname)s - %(message)s\",\n)\n\nlogger = logging.getLogger(__name__)\n\n\n# ---------------------------------------------------------------------------\n# Cleaning (shared)\n# ---------------------------------------------------------------------------\n\nQUOTE_MARKS = (\"“\", '\"', \"”\", \"‘\", \"'\")\n\n# A quote-led paragraph is a press quote, not marketing copy, when it is\n# attributed or talks about the delisting itself.\nATTRIBUTION = re.compile(\n    r\"\\b(said|says|stated|states|wrote|writes|explained|announced|according|\"\n    r\"told|posted|tweeted|confirmed|commented|responded|replied|statement|reads)\\b\",\n    re.I,\n)\nDELISTING_WORDS = re.compile(\n    r\"delist|remov|licen[cs]|no longer|pulled|discontinu|terminat|shut|expir|\"\n    r\"rights|unavailable|taken down|clos|bankrupt\",\n    re.I,\n)\n# Narrative that picks up again after a marketing block.\nRESUME_WORDS = re.compile(\n    r\"delist|removed from|end of service|no longer (available|sold|for sale|purchas)|\"\n    r\"taken down|pulled from\",\n    re.I,\n)\nFEATURES_HEADER = re.compile(r\"^(key |game )?features:?$\", re.I)\nFOOTER = re.compile(r\"^thanks (to|again)\\b\", re.I)\n\n\ndef clean_paragraphs(info: list) -> list:\n    \"\"\"\n    Narrative paragraphs of one entry.\n\n    Drops the site boilerplate (info[:2]), empty paragraphs, the trailing\n    \"Thanks to ...\" footer, and blocks of store-page marketing copy: a\n    feature-list header, or a quote-led paragraph that is neither attributed\n    nor about the delisting. A block ends at the next paragraph that talks\n    about the delisting again. Deliberately conservative: unflagged marketing\n    copy stays in, and the prompt tells the model to ignore it.\n    \"\"\"\n    paragraphs = [\" \".join(p.replace(\"\\xa0\", \" \").split()) for p in info[2:]]\n    paragraphs = [p for p in paragraphs if p]\n\n    while paragraphs and FOOTER.match(paragraphs[-1]):\n        paragraphs.pop()\n\n    kept = []\n    in_marketing = False\n\n    for k, paragraph in enumerate(paragraphs):\n        if in_marketing and RESUME_WORDS.search(paragraph):\n            in_marketing = False\n        elif k > 0 and (\n            FEATURES_HEADER.match(paragraph)\n            or (\n                paragraph.startswith(QUOTE_MARKS)\n                and not paragraphs[k - 1].endswith(\":\")\n                and not ATTRIBUTION.search(paragraph)\n                and not DELISTING_WORDS.search(paragraph)\n            )\n        ):\n            in_marketing = True\n\n        if not in_marketing:\n            kept.append(paragraph)\n\n    return kept\n\n\ndef clean_narrative(info: list) -> str:\n    \"\"\"Cleaned narrative as one string, paragraphs separated by blank lines.\"\"\"\n    words_left = MAX_WORDS\n    kept = []\n\n    for paragraph in clean_paragraphs(info):\n        words = paragraph.split()\n        if words_left <= 0:\n            break\n        kept.append(\" \".join(words[:words_left]))\n        words_left -= len(words)\n\n    return \"\\n\\n\".join(kept)\n\n\n# ---------------------------------------------------------------------------\n# Data\n# ---------------------------------------------------------------------------\n\ndef load_entries() -> pd.DataFrame:\n    \"\"\"\n    The delistedGames entries that are in the unified dataset (2,123), with\n    the raw title, platform and cleaned narrative.\n    \"\"\"\n    with open(RAW_JSON, encoding=\"utf-8\") as handle:\n        records = json.load(handle)\n\n    raw = pd.DataFrame(\n        {\n            \"id\": record[\"id\"],\n            \"title\": record[\"data\"].get(\"title\", \"\"),\n            \"platform\": record[\"data\"].get(\"platform\", \"\"),\n            \"info\": record[\"data\"].get(\"info\", []),\n        }\n        for record in records\n    )\n\n    unified = pd.read_csv(UNIFIED_CSV, usecols=[\"source\", \"source_record_id\"], low_memory=False)\n    kept_ids = set(unified.loc[unified[\"source\"] == \"delisted_games\", \"source_record_id\"].astype(int))\n\n    entries = raw[raw[\"id\"].isin(kept_ids)].copy()\n    entries[\"narrative\"] = entries[\"info\"].apply(clean_narrative)\n\n    logger.info(\"Loaded %d of %d delistedGames entries (in unified dataset).\", len(entries), len(raw))\n\n    return entries.drop(columns=\"info\").reset_index(drop=True)\n\n\n# ---------------------------------------------------------------------------\n# Ollama\n# ---------------------------------------------------------------------------\n\ndef prompt_text() -> str:\n    return PROMPT_FILE.read_text(encoding=\"utf-8\")\n\n\ndef prompt_hash() -> str:\n    return hashlib.sha256(prompt_text().encode(\"utf-8\")).hexdigest()[:12]\n\n\ndef model_digest(model: str) -> str:\n    \"\"\"Digest of a pulled model, so the cache pins the exact weights used.\"\"\"\n    response = requests.get(f\"{OLLAMA_URL}/api/tags\", timeout=30)\n    response.raise_for_status()\n\n    for entry in response.json().get(\"models\", []):\n        if entry.get(\"name\") == model or entry.get(\"model\") == model:\n            return entry[\"digest\"]\n\n    raise SystemExit(f\"Model {model} is not pulled. Run: ollama pull {model}\")\n\n\ndef user_message(entry) -> str:\n    return (\n        f\"Title: {entry.title}\\n\"\n        f\"Platform: {entry.platform}\\n\\n\"\n        f\"Narrative:\\n{entry.narrative}\"\n    )\n\n\ndef classify(model: str, entry) -> tuple:\n    \"\"\"One chat call. Returns (parsed answer, raw answer, seconds).\"\"\"\n    payload = {\n        \"model\": model,\n        \"messages\": [\n            {\"role\": \"system\", \"content\": prompt_text()},\n            {\"role\": \"user\", \"content\": user_message(entry)},\n        ],\n        \"format\": RESPONSE_SCHEMA,\n        \"stream\": False,\n        # Thinking off: Qwen3 would otherwise reason before the JSON.\n        # Models without a thinking mode ignore it on recent Ollama versions.\n        \"think\": False,\n        \"options\": {\n            \"temperature\": TEMPERATURE,\n            \"seed\": SEED,\n            \"num_ctx\": NUM_CTX,\n        },\n    }\n\n    start = time.time()\n    response = requests.post(f\"{OLLAMA_URL}/api/chat\", json=payload, timeout=REQUEST_TIMEOUT)\n\n    if response.status_code == 400 and \"think\" in response.text:\n        payload.pop(\"think\")\n        response = requests.post(f\"{OLLAMA_URL}/api/chat\", json=payload, timeout=REQUEST_TIMEOUT)\n\n    response.raise_for_status()\n\n    raw = response.json()[\"message\"][\"content\"]\n\n    return json.loads(raw), raw, round(time.time() - start, 2)\n\n\n# ---------------------------------------------------------------------------\n# Cache\n# ---------------------------------------------------------------------------\n\ndef cache_path(model: str) -> Path:\n    return CACHE_DIR / f\"{model.replace(':', '_').replace('/', '_')}.jsonl\"\n\n\ndef load_cache(model: str) -> list:\n    \"\"\"\n    Cached lines of one model made with the CURRENT prompt, last line per id.\n    Lines from an older prompt are ignored (and re-classified by run_model).\n    \"\"\"\n    path = cache_path(model)\n    if not path.exists():\n        return []\n\n    with open(path, encoding=\"utf-8\") as handle:\n        lines = [json.loads(line) for line in handle if line.strip()]\n\n    current = prompt_hash()\n    latest = {line[\"id\"]: line for line in lines if line[\"prompt_sha\"] == current}\n\n    stale = len({line[\"id\"] for line in lines} - set(latest))\n    if stale:\n        logger.warning(\"%s: %d cached ids are from an older prompt and are ignored.\", model, stale)\n\n    return list(latest.values())\n\n\ndef cached_ids(model: str) -> set:\n    return {line[\"id\"] for line in load_cache(model)}\n\n\ndef run_model(model: str, entries: pd.DataFrame, workers: int = 1) -> None:\n    digest = model_digest(model)\n    p_hash = prompt_hash()\n    done = cached_ids(model)\n    todo = entries[~entries[\"id\"].isin(done)]\n\n    logger.info(\n        \"%s (%s) at %s: %d cached, %d to classify, %d worker(s).\",\n        model, digest[:12], OLLAMA_URL, len(done), len(todo), workers,\n    )\n\n    CACHE_DIR.mkdir(exist_ok=True)\n\n    # Requests run in worker threads; only this thread writes the cache.\n    # On Ctrl-C the queued requests are cancelled instead of waited for.\n    pool = ThreadPoolExecutor(max_workers=workers)\n\n    try:\n        with open(cache_path(model), \"a\", encoding=\"utf-8\") as handle:\n            futures = {pool.submit(classify, model, entry): entry for entry in todo.itertuples(index=False)}\n\n            for n, future in enumerate(as_completed(futures), start=1):\n                entry = futures[future]\n                try:\n                    answer, raw, seconds = future.result()\n                except (requests.RequestException, json.JSONDecodeError, KeyError) as error:\n                    logger.warning(\"id %s failed: %s\", entry.id, error)\n                    continue\n\n                line = {\n                    \"id\": int(entry.id),\n                    \"model\": model,\n                    \"digest\": digest,\n                    \"prompt_sha\": p_hash,\n                    \"seed\": SEED,\n                    \"workers\": workers,\n                    \"seconds\": seconds,\n                    \"answer\": answer,\n                    \"raw\": raw,\n                }\n                handle.write(json.dumps(line, ensure_ascii=False) + \"\\n\")\n                handle.flush()\n\n                if n % 25 == 0 or n == len(todo):\n                    logger.info(\"%s: %d / %d\", model, n, len(todo))\n    finally:\n        pool.shutdown(wait=False, cancel_futures=True)\n\n    # Unload now, so the next model does not share the RAM with this one.\n    requests.post(f\"{OLLAMA_URL}/api/generate\", json={\"model\": model, \"keep_alive\": 0}, timeout=60)\n\n\n# ---------------------------------------------------------------------------\n# Main\n# ---------------------------------------------------------------------------\n\ndef show_clean(entries: pd.DataFrame, n: int) -> None:\n    for entry in entries.sample(n, random_state=SEED).itertuples(index=False):\n        print(\"=\" * 80)\n        print(f\"[{entry.id}] {entry.title} ({entry.platform})\")\n        print(entry.narrative)\n\n\ndef main():\n    global OLLAMA_URL\n\n    parser = argparse.ArgumentParser(description=__doc__.split(\"\\n\\n\")[0])\n    parser.add_argument(\"--model\", action=\"append\", help=\"Ollama tag (repeatable). Default: all MODELS.\")\n    parser.add_argument(\"--sample\", type=int, help=\"Classify a fixed random sample of N entries.\")\n    parser.add_argument(\"--ids\", type=int, nargs=\"+\", help=\"Classify only these entry ids.\")\n    parser.add_argument(\"--show-clean\", type=int, metavar=\"N\", help=\"Print N cleaned narratives and exit.\")\n    parser.add_argument(\"--workers\", type=int, default=1, help=\"Parallel requests to Ollama (default 1).\")\n    parser.add_argument(\"--ollama-url\", help=f\"Ollama server URL (default {OLLAMA_URL}, or $OLLAMA_URL).\")\n    args = parser.parse_args()\n\n    if args.ollama_url:\n        OLLAMA_URL = args.ollama_url.rstrip(\"/\")\n\n    entries = load_entries()\n\n    if args.show_clean:\n        show_clean(entries, args.show_clean)\n        return\n\n    if args.ids:\n        entries = entries[entries[\"id\"].isin(args.ids)]\n    elif args.sample:\n        entries = entries.loc[sorted(random.Random(SEED).sample(range(len(entries)), args.sample))]\n\n    for model in args.model or MODELS:\n        run_model(model, entries, args.workers)\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"RQ3_package/delisting_causes/validate_delisting_causes.py","group":"RQ3_package/delisting_causes","text":"#!/usr/bin/env python3\n\n\"\"\"\nCheck the LLM answers automatically and build the final cause labels.\n\nFor every cause a model flags, its quote must appear in the cleaned narrative\nthe model read (whitespace, quote marks and case normalised; fuzzy match with\nrapidfuzz partial_ratio >= QUOTE_MIN_SCORE = 95). A cause without a supporting\nquote counts as false. The two models are then compared per cause (Cohen's\nkappa and % agreement) on the entries both classified.\n\nFinal labels are the primary model's verified labels (MODELS[0]); the\n`<cause>_agree` columns keep a cause only when both models flag it with a\nverified quote, as a robustness check.\n\nInputs:\n    - llm_cache/<model_tag>.jsonl         (classify_delisting_causes.py)\n    - the cleaned narratives               (clean_narrative, shared)\n\nOutputs (next to this script):\n    - delisting_cause_labels.csv           one row per entry, final labels\n    - spot_check_sample.csv                optional human check: up to SPOT_CHECK_PER_CAUSE\n                                           random \"yes\" answers per cause with a\n                                           blank `correct` column. Written once and\n                                           never overwritten.\n\nThe quote check, the model agreement and, once `correct` has been filled in\n(y/n), the spot-check precision are printed to the log.\n\"\"\"\n\nimport json\nimport logging\nimport re\nfrom pathlib import Path\n\nimport pandas as pd\nfrom rapidfuzz import fuzz\n\nfrom classify_delisting_causes import (\n    CAUSES,\n    MODELS,\n    load_cache,\n    load_entries,\n)\n\n\n# ---------------------------------------------------------------------------\n# Configuration\n# ---------------------------------------------------------------------------\n\nBASE_DIR = Path(__file__).resolve().parent\n\nLABELS_CSV = BASE_DIR / \"delisting_cause_labels.csv\"\nSPOT_CHECK_CSV = BASE_DIR / \"spot_check_sample.csv\"\n\nPRIMARY, SECONDARY = MODELS[0], MODELS[1]\n\nQUOTE_MIN_SCORE = 95   # real quotes with spelling variants score 97+; stitched quotes ~91\nQUOTE_MIN_WORDS = 3   # a one- or two-word \"quote\" is not evidence\n\nSPOT_CHECK_PER_CAUSE = 20\nSEED = 42\n\nLABELS = CAUSES + [\"other\", \"not_stated\"]\n\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format=\"%(asctime)s - %(levelname)s - %(message)s\",\n)\n\nlogger = logging.getLogger(__name__)\n\n\n# ---------------------------------------------------------------------------\n# Quote check\n# ---------------------------------------------------------------------------\n\nCHAR_MAP = str.maketrans({\n    \"“\": '\"', \"”\": '\"', \"„\": '\"', \"‘\": \"'\", \"’\": \"'\", \"`\": \"'\",\n    \"–\": \"-\", \"—\": \"-\", \"…\": \"...\", \"\\xa0\": \" \",\n})\n\n\ndef normalise(text: str) -> str:\n    return \" \".join(text.translate(CHAR_MAP).lower().split())\n\n\ndef quote_found(quote: str, narrative: str) -> bool:\n    quote = normalise(quote or \"\").strip(\" .\\\"'\")\n\n    if len(quote.split()) < QUOTE_MIN_WORDS:\n        return False\n\n    text = normalise(narrative)\n\n    return quote in text or fuzz.partial_ratio(quote, text) >= QUOTE_MIN_SCORE\n\n\n# ---------------------------------------------------------------------------\n# Labels\n# ---------------------------------------------------------------------------\n\ndef final_labels(answer: dict, narrative: str, title: str) -> dict:\n    \"\"\"\n    Verified labels of one model answer.\n\n    A cause holds only with a verified quote. With no cause left, the entry is\n    OTHER if the model gave another reason (other / other_reason) or flagged a\n    cause whose quote failed, and NOT_STATED otherwise.\n    \"\"\"\n    row = {}\n    flagged_any = False\n\n    for cause in CAUSES:\n        item = answer.get(cause) or {}\n        flagged = bool(item.get(\"applies\"))\n        verified = flagged and quote_found(item.get(\"quote\", \"\"), narrative)\n        flagged_any |= flagged\n        row[cause] = verified\n        row[f\"{cause}_flagged\"] = flagged\n        row[f\"{cause}_quote\"] = item.get(\"quote\", \"\") if verified else \"\"\n\n    other_reason = (answer.get(\"other_reason\") or \"\").strip()\n\n    if any(row[cause] for cause in CAUSES):\n        row[\"other\"] = row[\"not_stated\"] = False\n    elif answer.get(\"other\") and not answer.get(\"not_stated\"):\n        row[\"other\"], row[\"not_stated\"] = True, False\n    elif answer.get(\"not_stated\") and not answer.get(\"other\"):\n        row[\"other\"], row[\"not_stated\"] = False, True\n    else:\n        row[\"other\"] = bool(other_reason) or flagged_any\n        row[\"not_stated\"] = not row[\"other\"]\n\n    row[\"other_reason\"] = other_reason if row[\"other\"] else \"\"\n    row[\"speculative\"] = bool(answer.get(\"speculative\")) and not row[\"not_stated\"]\n    row[\"relisted\"] = bool(answer.get(\"relisted\")) or \"[RELISTED]\" in title.upper()\n    row[\"is_bundle\"] = bool(answer.get(\"is_bundle\"))\n\n    return row\n\n\ndef model_labels(model: str, entries: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"Verified labels of one model, one row per cached entry.\"\"\"\n    lines = {line[\"id\"]: line for line in load_cache(model)}\n    rows = []\n\n    for entry in entries.itertuples(index=False):\n        line = lines.get(entry.id)\n        if line is None:\n            continue\n        rows.append({\"id\": entry.id, **final_labels(line[\"answer\"], entry.narrative, entry.title)})\n\n    missing = len(entries) - len(rows)\n    if missing:\n        logger.warning(\"%s: %d of %d entries are not cached.\", model, missing, len(entries))\n\n    return pd.DataFrame(rows).set_index(\"id\")\n\n\ndef cohen_kappa(a: pd.Series, b: pd.Series) -> float:\n    a, b = a.astype(bool), b.astype(bool)\n    observed = (a == b).mean()\n    expected = a.mean() * b.mean() + (1 - a.mean()) * (1 - b.mean())\n\n    return float(\"nan\") if expected == 1 else (observed - expected) / (1 - expected)\n\n\n# ---------------------------------------------------------------------------\n# Reports\n# ---------------------------------------------------------------------------\n\ndef quote_check_table(labels_by_model: dict) -> pd.DataFrame:\n    rows = []\n\n    for model, labels in labels_by_model.items():\n        for cause in CAUSES:\n            flagged = int(labels[f\"{cause}_flagged\"].sum())\n            found = int(labels[cause].sum())\n            rows.append({\n                \"model\": model,\n                \"cause\": cause,\n                \"flagged\": flagged,\n                \"quote_found\": found,\n                \"quote_not_found\": flagged - found,\n                \"share_not_found\": round((flagged - found) / flagged, 4) if flagged else 0.0,\n            })\n\n    return pd.DataFrame(rows)\n\n\ndef agreement_table(primary: pd.DataFrame, secondary: pd.DataFrame) -> pd.DataFrame:\n    common = primary.index.intersection(secondary.index)\n    p, s = primary.loc[common], secondary.loc[common]\n    rows = []\n\n    for label in LABELS:\n        rows.append({\n            \"label\": label,\n            \"n_entries\": len(common),\n            f\"yes_{PRIMARY}\": int(p[label].sum()),\n            f\"yes_{SECONDARY}\": int(s[label].sum()),\n            \"yes_both\": int((p[label] & s[label]).sum()),\n            \"agreement_pct\": round(100 * (p[label] == s[label]).mean(), 2),\n            \"cohen_kappa\": round(cohen_kappa(p[label], s[label]), 4),\n        })\n\n    return pd.DataFrame(rows)\n\n\ndef build_labels(entries: pd.DataFrame, primary: pd.DataFrame, secondary: pd.DataFrame) -> pd.DataFrame:\n    base = entries.set_index(\"id\")[[\"title\", \"platform\"]]\n    keep = LABELS + [\"other_reason\", \"speculative\", \"relisted\", \"is_bundle\"]\n    labels = base.join(primary[keep], how=\"inner\")\n\n    agreed = secondary.reindex(labels.index)\n    for cause in CAUSES:\n        labels[f\"{cause}_agree\"] = labels[cause] & agreed[cause].fillna(False).astype(bool)\n\n    labels[\"n_causes\"] = labels[CAUSES].sum(axis=1)\n    labels[\"evidence\"] = primary.loc[labels.index].apply(\n        lambda row: json.dumps(\n            {cause: row[f\"{cause}_quote\"] for cause in CAUSES if row[cause]},\n            ensure_ascii=False,\n        ),\n        axis=1,\n    )\n\n    return labels.reset_index()\n\n\ndef write_spot_check(labels: pd.DataFrame, entries: pd.DataFrame) -> None:\n    if SPOT_CHECK_CSV.exists():\n        logger.info(\"%s exists; not overwritten.\", SPOT_CHECK_CSV.name)\n        return\n\n    if len(labels) < len(entries):\n        logger.info(\"Spot-check sample skipped until every entry is classified.\")\n        return\n\n    narratives = entries.set_index(\"id\")[\"narrative\"]\n    evidence = labels.set_index(\"id\")[\"evidence\"].apply(json.loads)\n    rows = []\n\n    for cause in CAUSES:\n        yes = labels.loc[labels[cause], \"id\"]\n        for entry_id in yes.sample(min(SPOT_CHECK_PER_CAUSE, len(yes)), random_state=SEED):\n            rows.append({\n                \"cause\": cause,\n                \"id\": entry_id,\n                \"title\": labels.set_index(\"id\").at[entry_id, \"title\"],\n                \"quote\": evidence[entry_id][cause],\n                \"narrative\": narratives[entry_id],\n                \"correct\": \"\",\n            })\n\n    pd.DataFrame(rows).to_csv(SPOT_CHECK_CSV, index=False)\n    logger.info(\"Wrote %s (%d rows). Fill `correct` with y/n.\", SPOT_CHECK_CSV.name, len(rows))\n\n\ndef spot_check_precision() -> None:\n    if not SPOT_CHECK_CSV.exists():\n        return\n\n    sample = pd.read_csv(SPOT_CHECK_CSV, dtype={\"correct\": str})\n    answered = sample[sample[\"correct\"].fillna(\"\").str.strip().str.lower().isin([\"y\", \"n\"])]\n\n    if answered.empty:\n        return\n\n    answered = answered.assign(correct=answered[\"correct\"].str.strip().str.lower() == \"y\")\n    precision = answered.groupby(\"cause\")[\"correct\"].agg(checked=\"size\", correct=\"sum\")\n    precision[\"precision\"] = (precision[\"correct\"] / precision[\"checked\"]).round(3)\n    logger.info(\"Spot-check precision:\\n%s\", precision.to_string())\n\n\n# ---------------------------------------------------------------------------\n# Main\n# ---------------------------------------------------------------------------\n\ndef main():\n    entries = load_entries()\n\n    labels_by_model = {model: model_labels(model, entries) for model in (PRIMARY, SECONDARY)}\n\n    quote_check = quote_check_table(labels_by_model)\n    logger.info(\"Quote check:\\n%s\", quote_check.to_string(index=False))\n\n    agreement = agreement_table(labels_by_model[PRIMARY], labels_by_model[SECONDARY])\n    logger.info(\"Model agreement:\\n%s\", agreement.to_string(index=False))\n\n    labels = build_labels(entries, labels_by_model[PRIMARY], labels_by_model[SECONDARY])\n    labels.to_csv(LABELS_CSV, index=False)\n    logger.info(\"Wrote %s (%d entries).\", LABELS_CSV.name, len(labels))\n\n    write_spot_check(labels, entries)\n    spot_check_precision()\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"RQ3_package/delisting_causes/prompt.txt","group":"RQ3_package/delisting_causes","text":"You read entries from delistedgames.com, a volunteer-curated site that documents video games removed from sale on digital stores. Each entry has a narrative that explains when and why the game was delisted. Your task is to report which of five causes the narrative EXPLICITLY states as a reason the game was delisted, removed from sale, or made unavailable.\n\nTHE FIVE CAUSES (an entry can have several, or none):\n\nLICENSING       A licence for content INSIDE the game expired or was not\n                renewed: music/soundtrack, real car or brand names, sports\n                leagues/teams/players, film/TV/comic/book tie-ins,\n                trademarks. NOT: \"officially licensed\" in marketing copy;\n                rights to the game itself changing hands (-> IP_CHANGE).\nIP_CHANGE       Rights to the game or franchise ITSELF were sold,\n                transferred, reverted, acquired, or disputed legally.\nSERVER          Online services or servers were shut down, and the game was\n                pulled because of it or became unplayable.\nSTORE_CLOSURE   The storefront itself closed or stopped selling (Wii U/3DS\n                eShop, Xbox 360 marketplace, PS3/PSP/Vita store, Desura,\n                GameStop PC, OnLive, ...). The game left because the shop\n                closed, not because of the game.\nPUBLISHER_EXIT  The publisher or developer ceased operations, went\n                bankrupt, or was shut down. A publisher simply choosing to\n                remove the game with no stated reason does NOT count.\n\nFALLBACK FLAGS (only when none of the five causes applies):\n\nOTHER           A reason is stated but fits none of the five (e.g. replaced\n                by a remaster, platform-policy change). Put a short\n                description (at most 10 words) in other_reason.\nNOT_STATED      No reason is given, or the text says the reason is unknown.\n\nRULES\n\n1. Only count a cause the narrative states as a reason for THIS game's delisting or unavailability. Do not infer causes from the game's genre, its publisher, or your own knowledge.\n   - LICENSING needs the narrative to mention a licence, licensing, or rights to content inside the game. Removing or changing content for other reasons (political, legal, rating, censorship) is OTHER.\n   - PUBLISHER_EXIT needs the company to stop operating. A restructuring or a change of strategy is OTHER.\n   - A publishing agreement, publishing licence or publishing rights for the game ITSELF ending, expiring, lapsing or reverting (e.g. to the developer) is IP_CHANGE, not LICENSING: LICENSING is only for content INSIDE the game. Phrases such as \"expired publishing agreement\", \"publishing rights expired\", \"licensing between the developer and the publisher\" or \"regained publishing rights\" mean IP_CHANGE, also when they appear in a list of possible reasons or next to another cause.\n2. Many entries end with the game's store-page marketing copy (feature lists, product descriptions, quoted blurbs). Ignore it. Words like \"licensed\", \"official\", \"soundtrack\" or \"online multiplayer\" in marketing copy are NOT evidence.\n3. For every cause you mark true, copy a short quote (one sentence or less) VERBATIM from the narrative that states it. Copy the words exactly as they appear; do not paraphrase, shorten with \"...\", or fix spelling. If you cannot find such a quote, the cause is false and its quote is \"\".\n4. For every cause that is false, the quote is \"\".\n5. If any of the five causes is true, both \"other\" and \"not_stated\" are false and other_reason is \"\". Otherwise exactly one of \"other\" and \"not_stated\" is true.\n   - Choose OTHER whenever the narrative gives ANY reason, even a guessed one. Common OTHER reasons: replaced by a new edition, remaster, remake, bundle or collection; pulled to rework or fix the game; a business decision by the publisher; technical problems; content changes.\n   - Choose NOT_STATED only when the narrative gives no reason at all, or says the reason is unknown or that no explanation was given.\n6. A narrative can describe several delistings (different platforms or dates) with different causes. Mark every cause stated for any of them.\n7. \"speculative\" is true when the narrative presents the stated reason(s) as a guess rather than a confirmed fact (e.g. \"most likely\", \"presumably\", \"it is assumed\", \"possibly\"). It is false when the reasons are confirmed (e.g. announced by the publisher, developer or store) or when no reason is given.\n8. \"relisted\" is true when the narrative says the game was later made available again on a digital store it had been removed from, or re-released digitally (relisted, re-released, returned to sale). Staying available on a store it was never removed from is NOT relisting.\n9. \"is_bundle\" is true when the entry covers a bundle, collection, compilation or a whole franchise of several games rather than a single game.\n\nAnswer with JSON only, following the given schema.\n"},{"path":"docs/build_pipeline_figure.py","group":"docs","text":"#!/usr/bin/env python3\n\n\"\"\"\nPrint docs/pipeline_figure.html to a PDF.\n\nThe figure uses the icons and line style of docs/pipeline.html, keeping only\nthe sources and the processing steps. It is drawn by hand in\npipeline_figure.html; this script only prints it with headless Chrome.\n\nWrites, next to this script:\n    - pipeline_figure.pdf\n    - pipeline_figure.png   preview\n\"\"\"\n\nimport subprocess\nfrom pathlib import Path\n\nBASE_DIR = Path(__file__).resolve().parent\nSOURCE = BASE_DIR / \"pipeline_figure.html\"\nPDF = BASE_DIR / \"pipeline_figure.pdf\"\nPNG = BASE_DIR / \"pipeline_figure.png\"\n\nCHROME = \"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome\"\n\n# Figure size in CSS pixels (7.16 in x 2.7338 in at 96 px/in).\nWIDTH_PX, HEIGHT_PX = 687, 262\nPNG_SCALE = 3\n\n\ndef chrome(*args):\n    subprocess.run(\n        [CHROME, \"--headless=new\", \"--disable-gpu\", \"--virtual-time-budget=5000\",\n         *args, SOURCE.as_uri()],\n        check=True,\n        capture_output=True,\n    )\n\n\ndef main():\n    chrome(f\"--print-to-pdf={PDF}\", \"--no-pdf-header-footer\")\n    chrome(f\"--screenshot={PNG}\", f\"--window-size={WIDTH_PX},{HEIGHT_PX}\",\n           f\"--force-device-scale-factor={PNG_SCALE}\", \"--hide-scrollbars\")\n    print(f\"Wrote {PDF} and {PNG}\")\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"docs/build_pipeline_page.py","group":"docs","text":"#!/usr/bin/env python3\n\n\"\"\"\nRefresh the data shown in docs/pipeline.html.\n\nWrites, next to this script:\n    - previews.js   column names and first rows of every CSV/JSON output\n    - figs/*.png    copies of the RQ3 figures\n\nThe diagram and the filter/decision/issue text are written by hand in\npipeline.html and are not touched here.\n\"\"\"\n\nimport json\nimport logging\nimport shutil\nfrom pathlib import Path\n\nimport pandas as pd\n\n\nBASE_DIR = Path(__file__).resolve().parent\nREPO_DIR = BASE_DIR.parent\n\nPREVIEWS_JS = BASE_DIR / \"previews.js\"\nFIGS_DIR = BASE_DIR / \"figs\"\n\nPREVIEW_ROWS = 3\nMAX_CELL_CHARS = 60\n\nCSV_GLOBS = [\n    \"Analysis/*.csv\",\n    \"IGDB_miner/igdb_*.csv\",\n    \"RQ2_package/*.csv\",\n    \"RQ3_package/historical_analysis/*.csv\",\n    \"RQ3_package/delisting_causes/*.csv\",\n]\n\nRECORD_JSON_FILES = [\n    \"RawData/DeadGameWiki/dead_games.json\",\n    \"RawData/doesitplay_games.json\",\n    \"RawData/SteamTracker/steam_delisted_apps.json\",\n    \"RawData/DelistedGames/delistedgames.json\",\n]\n\nOBJECT_JSON_FILES = [\n    \"Analysis/model_readiness.json\",\n]\n\nFIGURE_GLOBS = [\n    \"RQ3_package/historical_analysis/*.png\",\n    \"RQ3_package/delisting_causes/figures/*.png\",\n]\n\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format=\"%(asctime)s - %(levelname)s - %(message)s\",\n)\n\nlogger = logging.getLogger(__name__)\n\n\ndef clip(value) -> str:\n    if isinstance(value, (list, dict)):\n        value = json.dumps(value, ensure_ascii=False)\n\n    value = \" \".join(str(value).split())\n\n    if len(value) > MAX_CELL_CHARS:\n        value = value[:MAX_CELL_CHARS - 3] + \"…\"\n\n    return value\n\n\ndef table_preview(df: pd.DataFrame) -> dict:\n    return {\n        \"columns\": [str(column) for column in df.columns],\n        \"rows\": [[clip(value) for value in row] for row in df.values.tolist()],\n    }\n\n\ndef main():\n    previews = {}\n\n    for pattern in CSV_GLOBS:\n        for path in sorted(REPO_DIR.glob(pattern)):\n            df = pd.read_csv(\n                path,\n                dtype=str,\n                keep_default_na=False,\n                nrows=PREVIEW_ROWS,\n            )\n            previews[path.relative_to(REPO_DIR).as_posix()] = table_preview(df)\n\n    for name in RECORD_JSON_FILES:\n        records = json.loads((REPO_DIR / name).read_text(encoding=\"utf-8\"))\n        df = pd.json_normalize(records[:PREVIEW_ROWS]).fillna(\"\")\n        previews[name] = table_preview(df)\n\n    for name in OBJECT_JSON_FILES:\n        if not (REPO_DIR / name).exists():\n            logger.warning(\"%s not found; no preview.\", name)\n            continue\n        data = json.loads((REPO_DIR / name).read_text(encoding=\"utf-8\"))\n        previews[name] = table_preview(pd.DataFrame([data]))\n\n    PREVIEWS_JS.write_text(\n        \"const PREVIEWS = \"\n        + json.dumps(previews, ensure_ascii=False).replace(\"</\", \"<\\\\/\")\n        + \";\\n\",\n        encoding=\"utf-8\",\n    )\n\n    FIGS_DIR.mkdir(exist_ok=True)\n\n    figures = [\n        path\n        for pattern in FIGURE_GLOBS\n        for path in sorted(REPO_DIR.glob(pattern))\n    ]\n\n    for path in figures:\n        shutil.copy2(path, FIGS_DIR / path.name)\n\n    logger.info(\n        \"Wrote %d previews to %s and %d figures to %s\",\n        len(previews),\n        PREVIEWS_JS,\n        len(figures),\n        FIGS_DIR,\n    )\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"docs/dataset/build_dataset_site.py","group":"docs/dataset","text":"#!/usr/bin/env python3\n\n\"\"\"\nRefresh the data shown in docs/dataset/index.html.\n\nWrites, next to this script:\n    - games.js           one entry per unique title, with its source records\n    - classification.js  taxonomy values for classified titles\n    - raw/*.json         copies of the four scraped source files, for download\n    - raw/files.js       name, size and record count of each raw file\n\nClassification is read from every Analysis/taxonomy_*classification*.csv.\nWhen a title appears in more than one file, the later file (sorted by name)\nwins, so the manually reviewed sample overrides the full classification. Titles without a classification are shown as \"not yet classified\", so\nnew classification files only need this script re-run.\n\nUsage: python docs/dataset/build_dataset_site.py\n\"\"\"\n\nimport json\nimport logging\nimport re\nimport shutil\nfrom pathlib import Path\n\nimport pandas as pd\n\n\nBASE_DIR = Path(__file__).resolve().parent\nREPO_DIR = BASE_DIR.parents[1]\n\nGAMES_CSV = REPO_DIR / \"Analysis\" / \"unified_games.csv\"\nCLASSIFICATION_GLOB = \"Analysis/taxonomy_*classification*.csv\"\n\nGAMES_JS = BASE_DIR / \"games.js\"\nCLASSIFICATION_JS = BASE_DIR / \"classification.js\"\nRAW_DIR = BASE_DIR / \"raw\"\n\n# Source key on the page -> scraped file in RawData/.\nRAW_FILES = {\n    \"steam_tracker\": \"RawData/SteamTracker/steam_delisted_apps.json\",\n    \"doesitplay\": \"RawData/doesitplay_games.json\",\n    \"delisted_games\": \"RawData/DelistedGames/delistedgames.json\",\n    \"dead_game_list\": \"RawData/DeadGameWiki/dead_games.json\",\n}\n\nEXCERPT_CHARS = 400\nDIMENSIONS = [\n    \"D1_digital_availability\",\n    \"D2_physical_availability\",\n    \"D3_medium_completeness\",\n    \"D4_online_dependency\",\n    \"D5_service_status\",\n    \"D6_platform_accessibility\",\n    \"D7_preservation\",\n]\n\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format=\"%(asctime)s - %(levelname)s - %(message)s\",\n)\n\nlogger = logging.getLogger(__name__)\n\n\ndef s(value) -> str:\n    return \"\" if pd.isna(value) else str(value).strip()\n\n\ndef year(value) -> str:\n    return \"\" if pd.isna(value) else str(int(value))\n\n\ndef first_url(text: str) -> str:\n    match = re.search(r\"https?://\\S+?(?=-https?://|\\s|$)\", text)\n    return match.group(0) if match else \"\"\n\n\ndef delisted_excerpt(info: str) -> str:\n    \"\"\"First paragraph after the site's two boilerplate lines.\"\"\"\n    if not info:\n        return \"\"\n    try:\n        parts = json.loads(info)\n    except json.JSONDecodeError:\n        return info[:EXCERPT_CHARS]\n    parts = [p.strip() for p in parts[2:] if p.strip()]\n    text = parts[0] if parts else \"\"\n    return text if len(text) <= EXCERPT_CHARS else text[:EXCERPT_CHARS].rsplit(\" \", 1)[0] + \"…\"\n\n\ndef record(row) -> dict:\n    src = row[\"source\"]\n    rec = {\n        \"s\": src,\n        \"n\": s(row[\"game_name\"]),\n        \"p\": s(row[\"raw__doesitplay__Platform\"]) or s(row[\"platforms\"]),\n        \"pub\": s(row[\"publisher\"]),\n        \"dev\": s(row[\"developer\"]),\n        \"ry\": year(row[\"release_year\"]),\n        \"ey\": year(row[\"event_year\"]),\n        \"st\": s(row[\"source_status\"]),\n    }\n    if src == \"steam_tracker\" and s(row[\"raw__steamtracker__AppID\"]):\n        rec[\"url\"] = f\"https://steamdb.info/app/{int(row['raw__steamtracker__AppID'])}/\"\n    elif src == \"doesitplay\":\n        rec[\"url\"] = s(row[\"raw__doesitplay__GameURL\"])\n        rec[\"x\"] = (f\"Offline play: {s(row['raw__doesitplay__OfflinePlay'])}; \"\n                    f\"download required: {s(row['raw__doesitplay__DownloadRequired'])}; \"\n                    f\"version: {s(row['raw__doesitplay__Version'])}; \"\n                    f\"region: {s(row['raw__doesitplay__Region'])}\")\n    elif src == \"dead_game_list\":\n        rec[\"url\"] = s(row[\"raw__deadgamelist__Home_page\"])\n        rec[\"x\"] = s(row[\"raw__deadgamelist__Notes\"])\n    elif src == \"delisted_games\":\n        rec[\"url\"] = first_url(s(row[\"raw__delistedgames__data__links\"]))\n        rec[\"x\"] = delisted_excerpt(s(row[\"raw__delistedgames__data__info\"]))\n    return {k: v for k, v in rec.items() if v}\n\n\ndef build_games() -> list:\n    df = pd.read_csv(GAMES_CSV, low_memory=False)\n    games = []\n    for title, group in df.sort_values(\"normalized_title\").groupby(\"normalized_title\", sort=False):\n        games.append({\"id\": title, \"r\": [record(row) for _, row in group.iterrows()]})\n    logger.info(\"Built %d titles from %d records\", len(games), len(df))\n    return games\n\n\ndef build_classification() -> dict:\n    out = {}\n    for path in sorted(REPO_DIR.glob(CLASSIFICATION_GLOB)):\n        df = pd.read_csv(path, keep_default_na=False)\n        for _, row in df.iterrows():\n            out[row[\"normalized_title\"]] = {\n                \"d\": [row[c] for c in DIMENSIONS],\n                \"ev\": row.get(\"evidence\", \"\"),\n                \"note\": row.get(\"manual_note\", \"\"),\n                \"src\": row.get(\"stratum_source\", \"\"),\n                \"m\": row.get(\"method\", \"manual review\"),\n                \"conf\": row.get(\"confidence\", \"\"),\n            }\n        logger.info(\"Read %d classified titles from %s\", len(df), path.name)\n    return out\n\n\ndef write_js(path: Path, name: str, data) -> None:\n    payload = json.dumps(data, ensure_ascii=False, separators=(\",\", \":\"))\n    path.write_text(f\"window.{name} = {payload};\\n\", encoding=\"utf-8\")\n    logger.info(\"Wrote %s (%.1f MB)\", path.relative_to(REPO_DIR), path.stat().st_size / 1e6)\n\n\ndef copy_raw_files() -> dict:\n    RAW_DIR.mkdir(exist_ok=True)\n    out = {}\n    for key, rel in RAW_FILES.items():\n        path = REPO_DIR / rel\n        shutil.copy2(path, RAW_DIR / path.name)\n        out[key] = {\n            \"file\": path.name,\n            \"bytes\": path.stat().st_size,\n            \"records\": len(json.loads(path.read_text(encoding=\"utf-8\"))),\n        }\n    return out\n\n\ndef main() -> None:\n    write_js(GAMES_JS, \"GAMES\", build_games())\n    write_js(CLASSIFICATION_JS, \"CLASSIFICATION\", build_classification())\n    write_js(RAW_DIR / \"files.js\", \"RAW_FILES\", copy_raw_files())\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"docs/code/build_code_page.py","group":"docs/code","text":"#!/usr/bin/env python3\n\n\"\"\"\nRefresh the source code shown in docs/code/index.html.\n\nWrites, next to this script:\n    - sources.js   every pipeline script as text, with its path\n    - src/         plain copies of the same files, at their repo paths\n\nThe notebook is copied with its outputs removed and shown as its cells.\nData, figures and the LLM caches are not included.\n\nUsage: python docs/code/build_code_page.py\n\"\"\"\n\nimport json\nimport logging\nimport shutil\nfrom pathlib import Path\n\n\nBASE_DIR = Path(__file__).resolve().parent\nREPO_DIR = BASE_DIR.parents[1]\n\nSOURCES_JS = BASE_DIR / \"sources.js\"\nSRC_DIR = BASE_DIR / \"src\"\n\n# Listed in pipeline order; each folder becomes a group on the page.\nSOURCE_GLOBS = [\n    \"main.py\",\n    \"requirements.txt\",\n    \"Scripts/*.py\",\n    \"IGDB_miner/*.py\",\n    \"RQ2_package/*.py\",\n    \"RQ3_package/*.py\",\n    \"RQ3_package/historical_analysis/*.ipynb\",\n    \"RQ3_package/delisting_causes/*.py\",\n    \"RQ3_package/delisting_causes/prompt.txt\",\n    \"docs/*.py\",\n    \"docs/dataset/*.py\",\n    \"docs/code/*.py\",\n]\n\n\nlogging.basicConfig(\n    level=logging.INFO,\n    format=\"%(asctime)s - %(levelname)s - %(message)s\",\n)\n\nlogger = logging.getLogger(__name__)\n\n\ndef strip_notebook(text: str) -> dict:\n    notebook = json.loads(text)\n    for cell in notebook[\"cells\"]:\n        if cell[\"cell_type\"] == \"code\":\n            cell[\"outputs\"] = []\n            cell[\"execution_count\"] = None\n    return notebook\n\n\ndef notebook_as_script(notebook: dict) -> str:\n    \"\"\"Cells in the '# %%' format that editors read as a notebook.\"\"\"\n    parts = []\n    for cell in notebook[\"cells\"]:\n        source = \"\".join(cell[\"source\"]).rstrip()\n        if cell[\"cell_type\"] == \"markdown\":\n            lines = [\"# \" + line if line else \"#\" for line in source.splitlines()]\n            parts.append(\"# %% [markdown]\\n\" + \"\\n\".join(lines))\n        elif cell[\"cell_type\"] == \"code\":\n            parts.append(\"# %%\\n\" + source)\n    return \"\\n\\n\".join(parts) + \"\\n\"\n\n\ndef main() -> None:\n    if SRC_DIR.exists():\n        shutil.rmtree(SRC_DIR)\n\n    files = []\n    for pattern in SOURCE_GLOBS:\n        for path in sorted(REPO_DIR.glob(pattern)):\n            rel = path.relative_to(REPO_DIR).as_posix()\n            text = path.read_text(encoding=\"utf-8\")\n            target = SRC_DIR / rel\n            target.parent.mkdir(parents=True, exist_ok=True)\n\n            if path.suffix == \".ipynb\":\n                notebook = strip_notebook(text)\n                target.write_text(json.dumps(notebook, indent=1, ensure_ascii=False) + \"\\n\", encoding=\"utf-8\")\n                text = notebook_as_script(notebook)\n            else:\n                shutil.copy2(path, target)\n\n            files.append({\n                \"path\": rel,\n                \"group\": path.parent.relative_to(REPO_DIR).as_posix() if path.parent != REPO_DIR else \"\",\n                \"text\": text,\n            })\n\n    payload = json.dumps(files, ensure_ascii=False, separators=(\",\", \":\"))\n    SOURCES_JS.write_text(f\"window.SOURCES = {payload};\\n\", encoding=\"utf-8\")\n    logger.info(\n        \"Wrote %d files to %s (%.0f KB) and %s\",\n        len(files),\n        SOURCES_JS.relative_to(REPO_DIR),\n        SOURCES_JS.stat().st_size / 1e3,\n        SRC_DIR.relative_to(REPO_DIR),\n    )\n\n\nif __name__ == \"__main__\":\n    main()\n"}];
